/**
 * Long-form dossier text for the districts and locations of Night City, and the
 * picture that goes with each one.
 *
 * Written by hand in the house voice (see src/lib/prose-style.ts). Presentation
 * copy only. No rules data lives here, and the engine never imports it: the
 * atlas JSON stays what the publisher printed, and this is what the player
 * reads. A place with no entry here falls back to its atlas blurb.
 *
 * `image` is a file under public/images/places. Keys are the atlas's own place
 * and district keys, so nothing has to be kept in step by hand.
 */

export type PlaceDossierEntry = {
  /**
   * File name (no extension) under public/images/places, when a picture has
   * been made. Text and pictures arrive separately, so an entry can be written
   * before its picture exists; the dossier simply shows no picture until it does.
   */
  image?: string;
  /** Paragraphs, in order. */
  text: string;
};

export const PLACE_DOSSIERS: Record<string, PlaceDossierEntry> = {
  little_europe: {
    image: "little-europe",
    text: `Little Europe is what happens when a city tries to build its future without first clearing away its past. Old brick tenements, narrow storefronts, Catholic stonework, fire escapes, and century-old façades stand shoulder to shoulder with glass towers, corporate residential blocks, neon-washed megastructures, and construction cranes hauling the next version of Night City into the sky. Before the Fourth Corporate War, this part of the city drew heavily from Little Italy, Northside, and the architectural DNA of places like New York, Boston, and old European cities. After the War smashed neighborhoods together and turned urban planning into triage, those pieces became Little Europe. The result is not harmonious. It is layered. Walk three blocks and you can cross forty years, two tax brackets, and several incompatible ideas about what Night City is supposed to become.

The divisions run deeper than architecture. Little Europe is a district of people who can see one another's lives through the windows. A corporate employee steps out of a climate-controlled tower and walks past a family business whose owners have been working the same battered counter since before the skyline changed. Execs sleep behind hardened security at Camden Court while Cube-A-Rama tenants fold their entire existence into rooms scarcely larger than closets. Danger Gal operatives roar home from a job to a building full of hot-pink chaos while, a few streets away, Holy Angels feeds people who have nothing. At Paradiso Terrestre, somebody spends more on dinner than another resident will see in a month. Neither person has to travel far enough to forget the other exists. Little Europe does not separate rich and poor cleanly. It rubs them against one another until sparks come off.

That friction is part of what keeps the district alive. Unlike the polished corporate enclaves where everything belongs to somebody with a security contract, Little Europe still feels inhabited rather than administered. People know their bartenders. Shopkeepers know which kids steal. Old veterans occupy the same tables every Thursday. Netrunners trade secrets over drinks at Short Circuit. Pool sharks ruin newcomers at Greta's. Fixers maintain booths, bartenders maintain secrets, priests maintain truces, and neighborhood businesses survive because enough people have quietly decided they deserve to. Even the megacorps have been forced to squeeze themselves into an existing social ecosystem rather than simply bulldoze it flat. Continental Brands can build a vertical neighborhood. It cannot stop the residents from giving every corridor insulting nicknames. Little Europe absorbs everything eventually, even the things trying to replace it.

And replacement is coming. Around 2045, executives and Fixers organized through a Chamber of Commerce had already begun carving away part of Little Europe and calling it Downtown, betting that the district could be transformed into Night City's next economic center. Development pushes upward. NCART links it to the Executive Zone and Watson. Megabuildings rise to accommodate the displaced. Across the water, new infrastructure promises another wave of construction, while the Hot Zone still glows to the east as a reminder of what happened the last time Night City's future became too ambitious. Little Europe stands between those two horizons: one side cranes and investment capital, the other radioactive history. The question hanging over every property deed and demolition notice is not whether the neighborhood will change. It is how much of it will still be recognizable when the money finishes arriving.

That makes Little Europe one of the best places in Night City to actually live a story. A job here rarely stays neatly in one world. Follow a corpo out of a skyscraper and they may disappear into a century-old pub. Chase a Netrunner through a cube hotel and the trail can end inside a church where drawing a weapon makes everyone in the room your enemy. A five-thousand-eurobuck suit can be fitted two streets from a bar with a functioning meat grinder. A private investigator, mobster, veteran, street kid, Exec, priest, Solo, and Tech can all plausibly cross the same intersection before lunch. That's Little Europe. Not old Night City. Not new Night City. Both of them, fighting over the same pavement. And for the moment, neither has won.`,
  },

  a1: {
    image: "camden-court",
    text: `Camden Court sells one thing better than almost anywhere else in Little Europe: the illusion that the city cannot reach you here. The apartment complex has been expensive for decades, favored by Solos with enemies and Execs with expense accounts, with the kind of security that makes ordinary residents feel comforted and professional killers start counting cameras. The lobby is polished without being ostentatious, the elevators behave themselves, the hallway lights work, and strangers lingering outside somebody's door tend to become security's problem very quickly. In Night City, these qualify as luxury amenities.

The residents are an unusual blend of corporate predators and people professionally employed to shoot corporate predators. You might share an elevator with a Petrochem middle manager carrying synth-groceries, a Solo coming home with dried blood beneath their fingernails, and a lawyer pretending not to recognize either of them. Nobody asks questions. Camden Court has developed its own quiet etiquette: don't stare at the cyberware, don't ask why the elevator was locked down last night, and if somebody from the sixth floor suddenly disappears, you never knew them.

For an edgerunner, Camden Court is simultaneously sanctuary and pressure cooker. A client might rent an apartment here because they know the building is hard to penetrate. A target might live here for exactly the same reason. Getting through the front door is one problem. Getting back out after the building realizes you do not belong is another. And somewhere behind all those expensive doors, people are still having affairs, hiding contraband, negotiating betrayals, and trying desperately to believe that enough money can make them safe.`,
  },

  a2: {
    image: "choppers",
    text: `The sign says Chopper's, and you don't need anybody to explain the joke. The place used to be a butcher shop, back when there was enough real meat moving through Night City for neighborhood butchers to matter. When the meat stopped coming, the butcher shop died. The hardware survived. Today the refrigerated display cases are packed with cold bottles instead of steaks, customers belly up to the old counters on high stools, and Norman, the owner, serves drinks across surfaces that once held cuts of beef. The industrial meat grinder is still in the building. It still works. Nobody has ever produced a convincing explanation for why.

Chopper's has the atmosphere of a place that has heard too much and intends to testify about none of it. The lighting is bad. The booze is strong. Half the furnishings look salvaged from the original shop, because they were, and there's something deeply Night City about drinking cheap whiskey beside an antique refrigeration unit while deals worth thousands of eurobucks are whispered three stools away. Regulars know which booths are good for private conversations, which bathroom lock is broken, and which subjects make Norman stop polishing glasses and start paying attention.

Everybody jokes about the grinder. Need a problem taken care of? Talk to Norman. Lose a friend? Check the sausages. Usually it's just black humor, the kind people cultivate when the mortality rate gets embarrassing. Usually. But Chopper's has been around long enough to understand an important Night City principle: a joke becomes much funnier when nobody is completely certain it's a joke.`,
  },

  a3: {
    image: "continental-brands",
    text: `Somewhere in the Continental Brands corporate hierarchy, a marketing executive decided employees shouldn't merely live in company housing. They should experience the Continental Brands lifestyle. The result is the Vertical Neighborhood, a residential tower in which every floor has been dressed as a different corner of the world. Apartments hide behind fake storefronts. Corridors twist into artificial streets. Scent vents pump manufactured aromas into the air while holographic vendors hawk imaginary goods to exhausted residents trying to remember whether the elevators are past the simulated noodle stand or beside the fake Moroccan spice market. Corporate calls it immersive. The people who live here call it a nightmare.

Getting lost is practically part of the lease. Ask three residents how to reach Apartment 47C and you may receive four answers, two shortcuts, and a warning never to take the "Venetian" stairwell after maintenance hours. The theming becomes surreal late at night, when holographic crowds continue their cheerful routines through nearly empty hallways and recorded street noise follows lone employees trudging home from another twelve-hour shift. It is difficult to describe the feeling of standing beneath an artificial sunset while your company-issued Agent informs you that you're late for work because you spent eleven minutes trying to find the real elevator.

For outsiders, the chaos can be useful. A courier can disappear into it. A thief can exploit it. A security team can curse it. Somewhere among the fake cafés, decorative alleyways, utility corridors, and branded cultural pastiche are thousands of small places where somebody can hide a package, conduct a meeting, or wait with a gun. The residents may hate the layout, but for an edgerunner being hunted through the tower, Continental Brands accidentally built one hell of a dungeon.`,
  },

  a4: {
    image: "cube-a-rama",
    text: `From the street, Cube-A-Rama almost looks respectable. Its original brick exterior survived the building's conversion into a cube hotel, leaving it with a kind of battered old-world charm that has become increasingly rare in Little Europe. Then you walk inside and discover that the charming historic shell contains row upon row of human storage compartments. Welcome home. Your bedroom is a box, your neighbors are separated from you by materials chosen largely because they were inexpensive, and every cubic centimeter has been engineered to remind you that privacy is something richer people purchase.

Yet Cube-A-Rama has life. People personalize their little cells with stickers, cheap lights, braindance posters, prayer cards, weapons, family photographs and whatever fragments of identity can be compressed into a few square meters. Conversations spill into common spaces because there's nowhere else for them to go. Arguments become public theater. Romance becomes an exercise in scheduling. Somebody is always showering, cooking, hacking, sleeping, screaming, laughing, or quietly packing everything they own into a bag. The notorious Short Circuit bar is close enough that some residents appear to navigate home largely through muscle memory.

Then there are the Netrunners. A group of them lives here, purpose unknown, and locals swear they sometimes communicate with one another in binary. Maybe it's performance. Maybe it's an in-joke. Maybe they're running something underneath the hotel that nobody has discovered yet. Nobody knows, which makes them considerably more interesting. At three in the morning, when half the hotel is asleep and the other half is pretending to be, you can sometimes hear fingers hammering keyboards behind closed cubes and wonder just how much of Night City is being quietly rewritten from inside a room barely large enough for a mattress.`,
  },

  a5: {
    image: "danger-gal-housing-facility",
    text: `You know you've reached Danger Gal employee housing because the building looks like somebody armed an art-deco architect with a corporate credit card and told them pink, but dangerous. The waterfront facility sits directly across from Danger Gal's headquarters, dressed inside in hot pink, pastel chartreuse, neon violet and black light. Arcade cabinets glow in common areas. Employees come and go at all hours. Security is tight, but the atmosphere is anything but sterile. This isn't a barracks. It's a clubhouse for heavily armed investigators who have decided adulthood is optional.

The residents call it the Danger Zone, and the nickname fits. Common spaces contain firing ranges, manga nooks, obstacle courses, beanbag pits, Kibble-cookie stations and Smash dispensers. Parties metastasize through the building with alarming regularity, often accumulating enough guests that you'd assume somebody had forgotten the definition of "secure corporate housing." Rumor says Piranhas show up often enough to qualify for frequent-visitor benefits. The result feels less like an apartment block and more like somebody welded a college dormitory to a private security contractor and then removed every adult responsible for saying no.

Don't mistake the chaos for weakness. The people drinking on the furniture are investigators, bodyguards, surveillance specialists, troubleshooters and professional violence-adjacent weirdos. That woman annihilating you at an arcade cabinet might have spent the afternoon tracking a kidnapping crew through the Combat Zone. The guy asleep in the beanbag pit may have a concealed handgun and a Trauma Team subscription. If you're invited to a party here, enjoy yourself. Make friends. Try the cookies. Just remember: in a building full of private investigators, somebody will notice everything you do.`,
  },

  a6: {
    image: "danger-gal-offices",
    text: `Danger Gal's headquarters rises over Little Europe as a thirteen-story art-deco monument to the proposition that intelligence work doesn't have to be beige. A decorative clocktower crowns the building. Below it, the company's private investigators, security specialists, analysts and operatives conduct business amid an interior aesthetic featuring hot-pink carpeting, mascot characters, model robots, pop-culture shrines and brightly colored firearms. There's even a go-kart circuit. You could mistake the place for a particularly unhinged entertainment company right up until you notice the armories. There are two. One contains the equipment Danger Gal admits owning.

Beneath the playful surface sits a serious intelligence operation founded by Michiko Sanderson, with investigations and security work stretching far beyond Night City. Vehicles cycle through the ground-level garage. AVs come and go from the rooftop hangar. Sensitive information moves through secured systems, operatives prepare for field assignments, and somewhere inside the building are archives containing the sort of information people kill to possess. That isn't speculation in the abstract. Edgerunners have tried breaking into those archives before. It went badly.

The upper floors are where the joke stops being funny. The eleventh and twelfth are reserved for the elite Puma Squad, with living quarters, training facilities, R&D space, meeting areas and an extensive armory. Breaking into Danger Gal HQ therefore poses an unusual tactical problem: even if you defeat the building's security, you may simply have succeeded in attracting the attention of people whose profession is finding people like you. Come here as a client and you may leave with answers. Come here as an enemy and you may leave through the garage in a container nobody asks about. Come here planning to steal from the archives, and you had better make peace with the possibility that Danger Gal already knows your name.`,
  },

  a7: {
    image: "fiddlers-green",
    text: `Fiddler's Green is an Irish pub in much the same way a plastic shamrock taped to a vending machine is Irish. There's green everywhere. Green lights. Green upholstery. Green drinks nobody in Dublin would admit to recognizing. The walls are crowded with Celtic knots, faded military photographs, cracked rugby memorabilia, and enough manufactured heritage to make the whole establishment feel like Saint Patrick's Day survived a nuclear exchange and opened a franchise. The clientele knows it. The staff knows it. Nobody particularly cares. The beer is cold, the portions are generous, and that's usually enough.

What gives the place some actual weight are the people behind the decoration. Fiddler's Green is run by Kate Mulvaney, her wife Audrey, and their extended family, with roots stretching back to veterans of the South American Wars. Beneath the tourist-pub veneer sits the easy camaraderie of people who have seen violence, survived it, and learned that sometimes the best response is another round and a story nobody entirely believes. Kate herself can occasionally be found mopping the floor, because apparently surviving a war and running a bar still doesn't exempt anybody from cleaning up somebody else's beer.

The place becomes more interesting after midnight. Veterans occupy their usual tables. Mercs trade exaggerated war stories with people who can tell exactly which parts are exaggerated. Somebody starts singing. Somebody else starts crying. Arguments become loud, but violence inside the Green is unusual because there is always the uncomfortable possibility that the grey-haired woman drinking quietly in the corner has killed more people than everyone else in the room combined. Come here looking for authentic Ireland and you'll be disappointed. Come looking for old soldiers, old stories, and people who know what the Fourth Corporate War did to the world, and suddenly Fiddler's Green becomes considerably more genuine.`,
  },

  a8: {
    image: "gretas",
    text: `There are pool halls, and then there is Greta's. The place has been around since the early days of Night City, beginning life as a straightforward lesbian bar before gradually becoming famous for something else entirely: some of the nastiest amateur pool players on the West Coast. By the Time of the Red, Greta's is widely considered the best pool hall in Night City, its tables guarded with the territorial seriousness other establishments reserve for vaults. The lesbian clientele remains an important part of the place's identity, but anyone who respects the room, pays their tab, and understands the difference between confidence and stupidity can walk through the door.

The real currency here isn't liquor. It's reputation. Money changes hands constantly around the tables as spectators bet on games, side bets attach themselves to other side bets, and somebody inevitably discovers that the quiet woman holding a battered cue has been setting them up for the last forty minutes. Greta's regulars know every imperfection in the felt, every strange bounce off the rail, every player worth backing and every newcomer pretending they aren't good. A thousand eurobucks can move across the room because one chipped ball kissed a cushion half a centimeter differently than expected.

That makes Greta's a marvelous place to conduct business. Nobody pays attention to two people talking beside a table when there's five hundred eb riding on the eight ball. Fixers scout talent here. Solos wager equipment. Romantic disasters unfold over drinks. Rivalries can last years without anybody drawing a firearm because settling the matter across green felt is considerably more humiliating. If somebody challenges you to a game at Greta's and casually asks what you're willing to bet, look at the room before you answer. Everybody else already knows how this ends.`,
  },

  a9: {
    image: "holy-angels-church",
    text: `In a city where nearly everything has a price, Holy Angels has rules instead. The old stone Catholic church has survived decades of Night City reinventing itself around it, and through all of them Father Kevin and Father Paul have maintained something almost absurdly precious: neutral ground. Gang members come here. Corpos come here. Solos come here. People who would happily murder one another six blocks away sit across the same table because once you enter Holy Angels, the weapons come off. Firearms, blades, ammunition, even weaponized cyberware gets surrendered for safekeeping. No exceptions. Father Kevin has spent decades making that rule stick.

Don't mistake sanctuary for softness. Father Kevin Sullivan is a former Solo, born in Belfast, and by 2045 he's seventy-five years old with absolutely no intention of letting age, gangs, corporations, or heavily armed idiots interfere with his church. His reputation as a mediator is extraordinary. Holy Angels has settled disputes between gangs and corporations that would otherwise have ended with bodies cooling in the street. The church feeds the hungry twice a day, shelters people with nowhere else to go, stores emergency food and water, and survives largely through donations, ingenuity, and the willingness of its community to protect it. Even 6th Street treats the church as something worth guarding.

That creates scenes found almost nowhere else in Night City. A Maelstrom lieutenant can sit three pews away from an NCPD detective. A corporate negotiator can break bread with somebody whose crew sabotaged their convoy last week. Outside, those people may be enemies. Inside, they are guests. Sometimes the silence in Holy Angels feels heavier than gunfire because everyone understands exactly how much violence is waiting beyond the doors. If Night City has anything resembling sacred ground, it might be this battered church where dangerous people voluntarily leave their weapons at the entrance and trust an old priest to keep the world from ending for another hour.`,
  },

  a10: {
    image: "paradiso-terrestre",
    text: `Paradiso Terrestre. Earthly Paradise. The name would be unbearably pretentious almost anywhere else. Here, somehow, they earn it. This is Southern Neo-Italian dining rebuilt for a world where authentic ingredients can require corporate logistics, agricultural contacts, smugglers, or all three. Reservations are mandatory. You do not simply wander in because you happen to be hungry. Somebody knows you're coming. Somebody has prepared for you. A table has been allocated, ingredients sourced, and your evening placed into a schedule that probably has more security than some Night Markets.

Inside, Paradiso Terrestre cultivates the rarest commodity in Night City: calm. Conversation remains low. Service is deliberate. The lighting flatters everyone. Plates arrive looking almost insultingly beautiful compared with the packaged food most citizens survive on. Neo-Italian cuisine doesn't pretend the old world survived untouched. It adapts. Synth proteins are treated with technique instead of apology. Hydroponic herbs matter. A genuine tomato might receive more reverence than a bottle of vintage wine did a century earlier. Nobody asks where certain ingredients came from unless they want the answer to ruin dinner.

And that's why Paradiso is useful for much more than eating. This is where an Exec brings somebody when the meeting cannot look like a meeting. Where a Fixer demonstrates that tonight's conversation is worth real money. Where a marriage proposal, corporate acquisition, murder contract, or betrayal can arrive between courses with exactly the same polished discretion. The staff does not stare. The neighboring tables do not stare. The bill eventually arrives, and for a moment you understand why the apocalypse failed to kill fine dining: civilization may collapse, supply chains may burn, but somebody will always pay obscene money to eat beautifully while the city dies outside.`,
  },

  a11: {
    image: "short-circuit",
    text: `Short Circuit is what happens when you give Night City's Techs and Netrunners a clubhouse and fail to establish any meaningful definition of the word safe. The reinforced three-story bar sits close to the Hot Zone, rebuilt in 2040 by Brain and his husband 3-Piece as an homage to the original Short Circuit, destroyed during the Fourth Corporate War. Downstairs, people drink beside workbenches while dismantling scavenged electronics. Broken drones, scorched circuit boards, salvaged military hardware and mysterious components migrate across tables beneath half-finished drinks. Brain encourages the practice and provides tools. Trash comes through the door. Sometimes something extraordinary leaves.

The second floor belongs to Netrunners. Comfortable chairs surround custom NET Architectures functioning as virtual clubs, and the entire building contains a shared Architecture called the Library, where patrons exchange information. Every December 24, an unknown Netrunner calling themselves S.A.N.T.A. has developed the charming seasonal habit of dumping classified corporate data into it. Nobody knows who S.A.N.T.A. is. Plenty of corporations would like to find out. Short Circuit's security takes that possibility seriously: biometric locks, cameras, paid Netrunners, patrolling Zhirafa drones, and an exterior elevator rigged to fill with sleeping gas if somebody gets clever.

The third floor is family territory: Brain's workshop, 3-Piece's recording space, their apartment, and the occasional location of 3-Piece's Joint, an invitation-only Night Market filled with salvaged equipment Brain has repaired, modified, or improved. Getting invited requires becoming a trusted regular, earning Brain or 3-Piece's confidence, and then surviving the final security test: their daughter Bug, who has an uncanny talent for spotting cops, corpos, and traitors. Short Circuit therefore occupies a strange place in Night City's ecosystem. It's a bar, workshop, data exchange, Night Market, social club, family home, and technological petri dish. Walk in with a fried cyberdeck and somebody may fix it. Walk in with a genuinely interesting piece of unknown hardware and suddenly you've bought yourself drinks for the evening. Walk in wearing a wire and Bug will probably know before you've ordered one.`,
  },

  a12: {
    image: "sopranos",
    text: `Soprano's has made an extraordinary business decision: theme an entire Italian restaurant around organized crime in a city where actual organized crime lives nearby. Red leather booths. Dark wood. Framed photographs of men looking vaguely threatening. Servers who talk about "the family." Menu items with names that make tourists giggle nervously. Somewhere, undoubtedly, a violin is working much harder than necessary. The commitment to the bit is absolute.

The remarkable thing is that the real Mob appears to have decided this is fine. Members of organizations such as the Skiv Family generally leave Soprano's alone, apparently regarding it with the same weary tolerance a shark might show toward a child wearing a shark costume. Perhaps it's too ridiculous to be insulting. Perhaps somebody important likes the pasta. Perhaps burning down a restaurant for having faux-mafia décor would constitute admitting that the décor bothered them. Whatever the reason, Soprano's has received the most valuable endorsement available in Little Europe: the people being parodied have chosen not to kill anybody over it.

Naturally, this makes it irresistible to aspiring criminals. Low-level boosters hold meetings here because it makes them feel important. Wannabe Fixers occupy corner booths and cultivate mysterious expressions. Tourists whisper when somebody with obvious cyberware walks through the door, convinced they've just witnessed a genuine mobster. Occasionally, inevitably, an actual member of the Mob comes in for dinner, and the entire restaurant spends two hours pretending not to notice. That's the essential charm of Soprano's: everyone is playing gangster except the people who really are gangsters, and those people mostly just want you to stop staring at them while they eat.`,
  },

  a13: {
    image: "torrell-and-chiang",
    text: `In Night City, clothing can tell people how much money you have, who you work for, whether you're armed, and how difficult killing you is likely to be. Torrell & Chiang understand all four. Considered by many to be the finest bespoke tailors in Night City, their Little Europe headquarters combines manufacturing space with a discreet storefront catering to people for whom five thousand eurobucks is an acceptable price for a three-piece suit. A properly cared-for Torrell & Chiang piece is expected to last roughly twelve years, assuming bullets, blood, fire, acid, and Night City don't revise the schedule.

Their genius lies in making protection disappear. Torrell & Chiang specialize in concealed armor and stain-resistant treatments, producing clothing that belongs in an executive boardroom while quietly acknowledging that the board meeting may end in gunfire. The cut is precise. The materials are expensive. Armor panels disappear beneath tailoring that never makes the wearer look like they're attending negotiations dressed as a tactical refrigerator. They produce coats, waistcoats and trousers, among other bespoke pieces, while happily sending customers elsewhere for mundane accessories like shirts, socks and cufflinks. They also produce lingerie because apparently elegance, discretion, and ballistic paranoia need not end when the trousers come off.

Walking into Torrell & Chiang's feels different from entering most Night City shops. Nobody rushes you. Nobody needs to. The staff knows almost instantly whether you're buying, browsing, or pretending. Measurements are taken with forensic precision. Questions are polite but revealing: Where will you be wearing this? How much movement do you require? Do you expect trouble? A client might be an Exec, Fixer, Rockerboy, diplomat, high-end Solo, or criminal whose profession is never spoken aloud. Shears, one of the shop's known tailors, has likely fitted people who intended to attend funerals and people who intended to cause them. In another city, a beautiful suit is vanity. In Night City, the finest compliment Torrell & Chiang can receive is that nobody noticed the armor until the shooting started.`,
  },
  upper_marina: {
    image: "upper-marina",
    text: `Upper Marina is a district built around the water, but don't mistake that for tranquility. The waterfront never stops moving. Cargo drones sweep over the docks carrying containers beneath them like steel insects. Nomad crews unload freighters beside automated cranes. Workboats nose through channels between pleasure craft and battered commercial vessels. Restaurants spill light across rebuilt promenades while, half a kilometer away, men in coveralls wrestle cargo out of a warehouse that still bears scars from the Fourth Corporate War. Among the functioning docks sit the rusting hulks of ships that never sailed again after the old world ended, too expensive to salvage and too stubborn to sink. Upper Marina simply built around them. **That's the district in miniature: polish laid over wreckage, with neither quite managing to hide the other.**

Before the War, these streets belonged to several different Night Cities: the old Marina District, pieces of Downtown, New Harbor, the Upper Eastside, even surviving fragments of the former City and Corporate District. When reconstruction came, the lines were redrawn and all those pieces were stitched together into Upper Marina. You can still see the seams. Old warehouses and machine shops squat beneath new residential towers. Brick industrial buildings that once smelled of oil and fish now contain expensive apartments with exposed beams, artisan cafés, boutiques, and carefully preserved machinery nobody remembers how to operate. Developers call the new neighborhoods **International**, selling waterfront living to people wealthy enough to regard industrial decay as aesthetic. Three streets away, the actual industry is still making enough noise to shake their windows.

That collision has produced money, and money has produced territory. Property owners elect the district's City Manager, **Kabria Chung**, while the NCPD provides the official security. *Official* is an important word. Maelstrom operates here. So do the **Prime-Time Players** and the **Street Queens**, alongside smugglers, Nomads, hustlers, warehouse crews, private security, corporate interests, and dozens of smaller predators who understand that anything moving through a port can disappear before the paperwork catches up. Down by the docks, a locked container might contain industrial components, medical supplies, military hardware, stolen cyberware, six terrified people, or exactly what the manifest claims. Nobody gets rich betting on the last one.

Yet Upper Marina is also one of the places where Night City is visibly trying to become a city again. Megabuildings rise to house the displaced. Reconstruction crews chew through ruined blocks. Plans call for NCART lines to stretch above ground and reconnect the district with the rest of Night City. Restaurants open where warehouses burned. Hospitals, apartments, clubs, offices, markets, docks, and entertainment venues attract people at every level of society. Some of Night City's most successful residents come here to drink above the water. Some of its most dangerous edgerunners come here to drink at **the Afterlife**. Somewhere nearby, Maelstrom can refurbish stolen chrome inside an old building whose walls still carry the impact scars from the people who tried to keep them out. Upper Marina's renaissance is real. So is everything growing underneath it.

And that's what makes the district such fertile ground for stories. Upper Marina is a place of **arrivals and departures**. Ships arrive. Cargo disappears. Nomads come ashore. Corpos buy waterfront property. Edgerunners meet before jobs they may not return from. A luxury condo can overlook a pier where somebody is being beaten for information. A gleaming restaurant can occupy the ground floor of a building whose basement connects to forgotten pre-War utility tunnels. Follow a shipment from the docks and it might end in a corporate lab, a Maelstrom workshop, a Night Market, or the trunk of somebody's car. Stand on the waterfront after dark and the whole district reflects back at you in broken pieces: neon trembling across black water, new towers rising behind rusted cranes, expensive apartments glowing above old factories. **Upper Marina is Night City rebuilding itself with one hand while the other keeps doing business exactly the way it always has.**`,
  },

  b1: {
    image: "the-afterlife",
    text: `Every city has places where legends drink. **Night City has a place where legends go to become ghosts.** The Afterlife sits in the remains of an old morgue on the edge of the Hot Zone, which tells you almost everything you need to know about the clientele's sense of humor. Refrigerated slabs once held corpses here. Now the dead make room for the professionally difficult to kill. Solos, Fixers, mercenaries, Nomad muscle, and edgerunners with enough reputation to get through the door gather beneath the ownership of **Rogue Amendiares**, herself one of Night City's great surviving Solo legends. Nobody needs to posture much inside the Afterlife. Getting in was the posture.

The bar operates on an unspoken understanding that reputation is more valuable than cash and considerably harder to replace. Jobs circulate here. Employers come looking for serious talent. Mercenaries study potential crews over drinks without appearing to study anybody. Old professionals recognize one another from operations nobody will discuss. There can be fights, naturally, because putting this many Solos in one building without fighting would violate several laws of physics, but the house culture traditionally draws a line between settling something and killing somebody. The Afterlife is a professional room. Act like an amateur and the room notices.

And then there are the drinks. Every Solo in Night City has heard the dream: live big enough, die spectacularly enough, and maybe someday the Afterlife puts your name on the menu. That's the dark little joke sitting beneath every glass. The people drinking here know perfectly well how careers like theirs usually end. They come anyway. So when a Fixer slides into the booth across from you and says there's a job, the question isn't merely how much it pays. **The question is whether tonight begins the story that eventually puts your name behind the bar.**`,
  },

  b2: {
    image: "buffalos",
    text: `There is something wrong with the building that houses Buffalo's. Not structurally, probably. **Spiritually.** For roughly sixty years, restaurants and bars have opened here with bright signs, ambitious menus, and business plans explaining why *this time* will be different. They have then failed with almost theatrical consistency. One predecessor was busted over questionable meat. Another got caught laundering money. A juice bar poisoned enough customers to become part of neighborhood folklore. Hospitality workers call it the **Bad Restaurant Curse**, and by 2045 Buffalo's had survived long enough for locals to start a betting pool on when it would finally die.

Buffalo's response to this history is apparently to pretend it doesn't exist. The kitchen serves global fusion cuisine with the fearless enthusiasm of chefs who have looked at the culinary traditions of six continents and decided all of them could benefit from being stacked on the same plate. Some combinations are genuinely excellent. Others appear to have originated during a dare. Its signature Buffalo Nose cocktail mixes bourbon, pickle juice, lemon, and hot sauce, which gives you some idea of the establishment's willingness to negotiate directly with God.

That looming sense of mortality makes Buffalo's weirdly lovable. Regulars celebrate every additional week like they're watching an underdog prizefighter stagger upright before the ten-count. Employees discuss the curse with varying degrees of irony. Bookies quietly update the odds. Somewhere, the owner is presumably trying not to think about the fact that customers have begun buying commemorative merchandise for a restaurant that hasn't actually closed yet. **Eat there while you can. Everybody else is.**`,
  },

  b3: {
    image: "city-medical-center",
    text: `City Medical Center is where Night City sends people when the neighborhood ripperdoc looks at the injury and says, *No. Absolutely not.* The enormous research hospital survived both the Fourth Corporate War and the fires that consumed much of old Downtown, though the Time of the Red has not been gentle with it. Lower levels have suffered flooding. Power, water, and communications can fail. Hallways built for orderly medicine absorb the overflow of a city that produces catastrophic injuries faster than it produces hospital beds. Yet behind all that battered infrastructure remain some of the finest surgeons, researchers, equipment, and medical technology in Night City. For certain procedures, this is still the place you want to wake up.

Assuming, naturally, that you can pay. City Medical has extensive corporate ties and offers far more than emergency surgery. Therapy, advanced medical treatment, biosculpting, reconstruction, and procedures unavailable in neighborhood clinics can all be found somewhere in the complex for clients with sufficient eurobucks or the correct insurance. Money changes the experience dramatically. One patient waits beneath flickering lights beside twenty bleeding strangers. Another recovers upstairs in a private suite while an Exec signs authorization forms downstairs. Same building. Same medicine. Different Night City.

Hospitals also accumulate secrets. A Solo wakes from surgery with no memory of who paid the bill. A corporate researcher transfers a patient under armed guard at three in the morning. A wounded ganger arrives carrying something inside their body that wasn't put there by any doctor. Medical records become blackmail. Pharmaceuticals disappear from inventory. Somebody in a secured ward is officially dead but still has a pulse. City Medical Center saves lives every hour. **That doesn't mean everyone inside wants their patient to survive.**`,
  },

  b4: {
    image: "garden-of-earthly-delights",
    text: `The Garden of Earthly Delights doesn't sell sex so much as **curated surrender**. Wealthy clients enter through discreet doors and begin with dinner, choosing food and intoxicants from carefully arranged menus before being guided onward into an elaborate bathhouse. The transition is deliberate. Clothes disappear. Street noise disappears. Responsibility begins disappearing shortly afterward. Eventually guests retire to private rooms with companions, many fitted with cutout chips that allow programmed personas to take over according to a client's specifications. In Night City slang, they're **meat puppets**. The Garden prefers considerably more elegant terminology.

Everything is engineered around discretion. The Garden operates under the patronage of **David Ling Po**, with security supplied by the Gold Dragons, and the clientele tends toward people wealthy enough that recognizing them can become dangerous. The staff understands that guests are not merely buying pleasure. They're buying a sealed compartment in reality where nobody asks whether the person enjoying dinner is a politician, crime boss, Exec, famous Rockerboy, or somebody whose face appeared on the screamsheets that morning. Rumors attach themselves naturally to a business like this, including darker stories about exactly which fantasies management will permit for sufficient money. Stranger still, the establishment's most expensive service is reportedly a private room containing **no companion at all**. Why that costs more is not something the Garden explains.

For an edgerunner, the place practically sweats complications. A target comes here because they believe nobody can reach them. A client hires you to retrieve something left in a private room. An employee wants out. A cutout chip contains memories it shouldn't. Somebody books the empty room every Thursday and emerges three hours later looking terrified. The Garden promises that whatever happens inside belongs only to the guest. **In Night City, a promise of absolute secrecy is simply another way of announcing that something worth stealing is hidden behind the door.**`,
  },

  b5: {
    image: "graffitix",
    text: `GraffitiX is what happens when Night City's street art survives long enough for rich people to start putting prices beside it. The upscale Upper Marina gallery showcases some of the city's most promising emerging artists, turning spray paint, braindance fragments, sculpture, digital installations, reclaimed war debris, and whatever else the scene invents next into objects of serious cultural attention. Downstairs, buyers circulate through exhibitions while discussing revolution beside complimentary drinks. Upstairs is reserved for paid exhibitions and artists in residence, where reputations can be built quickly and destroyed even faster.

The tension is delicious. Some artists showing here grew up tagging corporate walls and dodging security drones. Now corporations bid on their work. Fixers mingle with collectors. Young creators desperately need the money and desperately don't want to become decorative rebellion for an Exec's penthouse. A piece painted on scavenged Militech armor can sell for thousands of eurobucks to somebody employed by Militech. Nobody agrees whether that means the artist won or lost.

GraffitiX is therefore as much marketplace as gallery. Careers begin here. So do feuds. An anonymous piece might contain evidence of a crime. A sculpture could incorporate stolen technology. A famous artist might vanish the night before an exhibition. And if a new installation seems to depict a murder that hasn't happened yet, Night City has taught you not to assume it's metaphor.`,
  },

  b6: {
    image: "la-lune-blue",
    text: `**La Lune Blue does not need your business.** That's the first thing to understand. This is one of Night City's highest-end French restaurants, with a reputation for serving some of the finest French cuisine on the West Coast. The room is immaculate without screaming wealth, because truly expensive places rarely need to raise their voices. Service unfolds with ritual precision. Glassware appears soundlessly. Plates arrive composed rather than assembled. Even the lighting seems to have been interviewed before being allowed inside.

The gatekeeper is maître d' **Maurice**, who treats the dress code less like a suggestion and more like an immigration policy. Show up dressed incorrectly and you may discover that possessing enough money for dinner does not necessarily qualify you to eat it. In a city obsessed with visible status, La Lune Blue understands that exclusion is part of the product. Getting a table tells people something about you before you've ordered anything.

Which makes it ideal territory for quiet warfare. Corporate deals happen beneath white tablecloths. Lovers discover infidelity between courses. Fixers meet clients who would never be seen in the Afterlife. Somebody at the next table may be negotiating the acquisition of a company, or arranging for its CEO to stop breathing. Nobody raises their voice. Nobody reaches for a weapon. **At La Lune Blue, people stab one another with sentences. The knives are reserved for dinner.**`,
  },

  b7: {
    image: "marina-floathomes",
    text: `From the shore, Marina FloatHomes can look almost idyllic: rows of compact houseboats rocking gently against their moorings, stadium lights reflecting across the water, narrow walkways connecting one tiny floating home to the next. They're studio apartments with tides. Residents can walk to McCartney Field for games and concerts, sit outside over the water after work, and briefly pretend they've discovered an affordable loophole in Night City's housing market.

Then you meet the neighbors. Many residents are low-ranking **Ziggurat and Continental Brands employees**, people climbing corporate ladders one miserable rung at a time while waiting for the promotion that gets them into proper company housing. Alongside them lives a surprisingly prosperous population of scavvers drawn by proximity to the Old City Center ruins. They come home late carrying salvage, injuries, grudges, and sometimes enough blood to require questions nobody wants to ask. Occasionally, somebody discovers a dead scavver inside one of the FloatHomes. This is treated less as shocking than as extremely inconvenient.

Life here runs on proximity. Everyone hears arguments through open windows. Everybody notices the unfamiliar boat that tied up at two in the morning. Contraband can pass beneath floorboards and disappear onto the water before police reach the dock. A resident may spend all day maintaining the continent's communications network and spend all night listening to the scavver next door dismantle something that probably belonged to a corporation yesterday. **The FloatHomes aren't quite respectable and aren't quite lawless. They're floating in the narrow space between.**`,
  },

  b8: {
    image: "mccartney-cubes",
    text: `Nobody living at McCartney Cubes ever has to wonder whether Night City won last night. They'll hear about it through the walls. Located directly across from McCartney Field Stadium, the cube hotel's floors are painted in the garish colors of different local sports franchises, transforming an already cramped building into something resembling a team merchandise store converted into human storage. Soundproofing is minimal. When the Death Dealers or Nuke are playing, sleep becomes a theoretical concept.

Residents have embraced the proximity with typical Night City ingenuity. Sports fans have even built crude viewing platforms atop the cubes to steal sightlines into the stadium, leading McCartney management to seek their removal when the freeloading became too obvious. Imagine living in a box barely larger than your bed while somebody three meters above you has constructed an unauthorized grandstand out of scrap metal because tickets cost too much. That's not a housing problem. That's **community spirit**.

Game nights turn the entire area feral. Vendors appear. Bets circulate. Arguments erupt over teams, players, calls, and matches half the building couldn't actually see. After a victory, the celebrations last until dawn. After a loss, the walls acquire new holes. The best advice for anyone taking a room here is simple: **pick a team before your neighbors pick one for you.**`,
  },

  b9: {
    image: "mccartney-field-stadium",
    text: `McCartney Field holds **75,000 people**, which means on event nights it contains enough humanity to qualify as its own temporary city, only with more alcohol and significantly worse impulse control. The stadium survived the destruction that reshaped central Night City and became the beating heart of Upper Marina's sports and concert scene. Corporate sponsorship coats nearly everything that doesn't move quickly enough to escape branding. On quiet afternoons the structure looms over the neighborhood like dormant machinery. On game nights it wakes up hungry.

The roster of resident franchises tells you exactly what Night City considers entertainment. The **Slammers** play baseball. The **Heat** play basketball. The **Death Dealers** play combat soccer. **Nuke** plays murderball, a sport whose name saves everyone the inconvenience of pretending player safety is the primary concern. Then there is the **New Battlegrounds Championship Wrestling League**, where spectacle, violence, personalities, implants, sponsorships, and storylines blur together until nobody particularly cares which parts are predetermined. Add enormous concerts to that schedule and the stadium rarely stays quiet for long.

For edgerunners, seventy-five thousand spectators represent seventy-five thousand complications. Tickets are scalped. Drugs move through bathrooms. Fixers use luxury boxes. Gangs control parking lots. Athletes have debts, rivalries, contracts, chrome, lovers, enemies, and very expensive bodies. A sniper can disappear into a crowd. So can a target. Somebody wants a player protected before the championship. Somebody else wants them unable to play. And when the lights go down before a sold-out event and seventy-five thousand people begin screaming together, **Night City sounds less like a city than a living animal.**`,
  },

  b10: {
    image: "night-city-bubbles",
    text: `Night City Bubbles exists for people whose idea of relaxation requires both an appointment and a substantial credit limit. The high-end Upper Marina spa specializes in expensive personal services delivered in surroundings designed to make the city outside feel temporarily unreal. Steam curls through immaculate rooms. Towels are warm before you touch them. Everything smells engineered to reduce blood pressure. Nobody screams unless they've paid for something extremely unusual.

Some Bubbles employees can also be hired as escorts for outside engagements, and they're expected to do more than look good beside a client. They know how to navigate fashionable parties, corporate functions, gallery openings, dinners, and social circles where saying the wrong thing can cost considerably more than the evening's fee. That makes them professionally observant people who spend hours standing beside Night City's wealthy while everyone assumes they're decorative. **An astonishing amount of confidential information gets spoken near someone society has decided not to notice.**

A spa like Bubbles therefore attracts stories almost automatically. An Exec books the same employee every Thursday but never touches them. An escort overhears something worth killing for. A client leaves a data shard in a robe. Somebody enters for a massage and never comes out the front door. Bubbles sells serenity. Night City has always understood that **serenity becomes much more expensive when you know too much.**`,
  },

  b11: {
    image: "reo-meatwagon-offices",
    text: `If Trauma Team is emergency medicine with military discipline, **REO Meatwagon is emergency medicine with its elbows out.** Night City's second-largest EMS operation runs armored ambulances from its Upper Marina facilities near the Combat Zones, dispatching crews into some of the city's ugliest situations to drag injured clients back out again. They're medics. They're armed. They're aggressive. And their corporate relationship with Trauma Team has historically contained approximately as much professional courtesy as a knife fight in an elevator.

REO is notorious for **meat jumping**: intercepting Trauma Team calls, arriving first, taking the wounded client, and charging them an obscene amount for the privilege of surviving the experience. The practice has led to direct confrontations between emergency crews whose job descriptions theoretically begin with saving lives. Imagine lying on the pavement with a collapsed lung while two armored medical corporations argue over who gets to invoice you. Congratulations. You now understand healthcare in Night City.

The offices themselves consequently feel halfway between hospital, garage, dispatch center, and fortified motor pool. Ambulances scream in and out. Medtechs clean blood from equipment while dispatch screams coordinates. Solos guard entrances. Somebody wheels a half-conscious ganger through one door while lawyers argue about liability behind another. Despite the reputation, REO crews genuinely save people who would otherwise die. That's what makes the whole operation so perfectly Night City. **They're vultures, maybe. But when you're bleeding out in an alley, a vulture with a trauma kit can look a lot like an angel.**`,
  },

  b12: {
    image: "travlstay-citycenter",
    text: `TravlStay CityCenter has achieved an impressive feat: making homelessness look competitive. The cube hotel sits near the edge of the Hot Zone with paper-thin walls, no meaningful security, and hallways where residents may literally have to step over bodies when leaving their rooms. The cubes themselves offer the essentials: a place to lie down, a door, and the comforting knowledge that the door's ability to protect you is largely conceptual. Officially, this is housing. **Technically, so is a shipping crate.**

The lack of security produces a strange ecosystem. People who actively value privacy generally leave. People who value anonymity stay. Prostitutes, boosters, drifters, scavvers, addicts, exhausted edgerunners, people hiding from landlords, people hiding from gangs, and people hiding from considerably more organized institutions rotate through the building without anyone keeping close track. After dark, every human activity imaginable seems to occur simultaneously on opposite sides of walls with the acoustic properties of cardboard. Saturday nights have been compared to living inside a blender after somebody hits the switch.

And yet TravlStay has one genuine advantage: **nobody cares who you are.** Need somewhere to disappear for two nights? Need a room paid in cash? Need to meet somebody who refuses to enter a building with cameras? TravlStay may be perfect. Just don't leave anything valuable unattended, including weapons, shoes, internal organs, or friends.`,
  },

  b13: {
    image: "ziggurat-offices",
    text: `Ziggurat Headquarters curves above the bay like somebody turned a corporate logo into architecture. The skyscraper is deliberately impressive, engineered to dominate the waterfront and remind everyone looking up at it that **Ziggurat built the nervous system of the modern city**. Founded in Night City in 2030, the company transformed surviving local fiber infrastructure into the CitiNet and layered the Data Pool on top of it. By 2040, Ziggurat's networks had spread through most major cities across North America. Every message, Garden Patch update, local feed, search, argument, advertisement, rumor, and cat video moving across those systems ultimately owes something to the people working inside this building.

Public access to headquarters is extremely limited, generally restricted to events such as press conferences. Employees don't necessarily get much more separation from the company. Hanging beneath the main structure is the residential complex known as the **Hanging Gardens**, where Ziggurat workers can live directly attached to their workplace. The bay views are spectacular. The commute is nonexistent. The windows are sealed, reportedly after footage of an employee's suicide spread virally through the Data Pool. Apartment doors display their occupants' Garden Patches, and residents are expected to maintain enough online activity to keep pace socially with their neighbors. Even at home, the company that connects everyone is watching whether you remain sufficiently connected.

It's difficult to imagine a better target for a Netrunner and difficult to imagine a worse place to actually break into. The headquarters contains engineers, administrators, network specialists, infrastructure planners, security teams, and presumably enough sensitive information to start wars in several jurisdictions. Sabotage a CitiNet node here and neighborhoods could go dark. Steal the right internal files and you could learn who is talking to whom across an entire city. Maybe that's why the building rises so confidently over the bay. **Ziggurat doesn't merely occupy Night City. A substantial portion of Night City's conversations pass through machinery Ziggurat owns.** And somewhere inside that shining tower, somebody has root access.`,
  },

  downtown: {
    image: "downtown",
    text: `Downtown is not old Night City coming back. **It is somebody's attempt to decide what the next Night City will be before everyone else gets a vote.** Around 2045, Mister Kernaghan and the Chamber of Commerce, a coalition of Fixers and Execs with enough money, influence, and ambition to move neighborhood boundaries, carved a section out of Little Europe and began turning it into the most commercially friendly district on the Island. The streets are cleaner. Construction moves faster. Security is more visible. New glass rises between older buildings while corporate logos arrive before the concrete has finished curing. Every renovated block carries the same message: *the emergency is ending, the money is coming back, and you had better own something before it does.*

The word everyone uses is **rebirth**. Downtown prefers that word because *gentrification* makes investors uncomfortable. Property gets bought, consolidated, cleaned, fenced, and relaunched. Apartments become executive housing. Corner businesses discover their leases have acquired extra zeroes. Streets that once belonged to Little Europe suddenly acquire private patrols and architectural renderings showing happy professionals drinking coffee beneath trees that have not been planted yet. At the center of the experiment sits the Chamber of Commerce, treating urban development as a business opportunity with sidewalks. Downtown's city manager, **Emelia Ortega**, represents the district's interests, while **Whitewater Security** handles much of the protection. This is a neighborhood being rebuilt by people who understand that whoever controls the rebuilding controls what comes afterward.

And, irritatingly, **a lot of it works**. Shops open. Office towers fill. Continental Brands plants its Night City headquarters here. Restaurants and clubs attract people after dark. Fire Station #2 can deploy heavily augmented rescue crews instead of hoping the nearest engine still starts. Compared with the ruins and Rebuilding Urban Zones elsewhere on the Island, Downtown can feel almost miraculous. Streetlights function. Businesses expect deliveries to arrive. People sign leases longer than six months. Somebody is landscaping. In the Time of the Red, landscaping borders on political propaganda. The Chamber wants visitors to walk these streets and believe Night City has finally moved beyond merely surviving. For a few blocks at a time, you might even believe them.

But Night City never permits cleanliness without fingerprints. The **Eastern Tigers Triad, Skiv Family, and Undertow** all maintain interests in the district, because criminals understand economic redevelopment just as well as investors do. The sidewalks host kids running little **chrome-shine** stands, polishing exposed cyberware for pocket change. Some of those kids have also been caught attaching tiny listening devices to customers' chrome, broadcasting conversations onto the CitiNet for reasons nobody has satisfactorily explained. That may be the most perfect Downtown business model imaginable: offer a convenient service, collect somebody's data without permission, and figure out how to monetize it later.

For an edgerunner, Downtown is dangerous precisely because it looks increasingly civilized. Combat Zones advertise danger with burned-out cars and gunfire. Downtown gives you valet parking. A job can begin in a fashionable club, move through a corporate lobby, disappear into an architecturally unfortunate office building, and end behind the gates of a residential street where everybody has money and nobody wants witnesses. Fixers are buying property beside Execs. Gang money hides inside legitimate redevelopment. Private security guards construction sites containing secrets worth more than the buildings themselves. **Downtown is Night City putting on a clean suit for the first time in years. The blood hasn't disappeared. Somebody just taught it how to wear cufflinks.**`,
  },

  c1: {
    image: "acadia-way",
    text: `Acadia Way is a single street with a gate across it, and that gate says more about Downtown than any corporate manifesto ever could. Behind it sits a row of carefully restored bungalow-style homes, low and almost quaint beneath a skyline increasingly obsessed with glass, height, and corporate ambition. Lawns are maintained. Paint isn't peeling. Porch lights work. The houses look like artifacts from a vanished America, rescued from demolition and polished until nostalgia became an amenity. Then someone put security at the entrance to make sure the rest of Night City stayed outside.

The appeal is obvious. Downtown changes by the month, but Acadia Way offers wealthy residents something increasingly exotic: **smallness**. A front door instead of a residential tower lobby. A private patch of ground instead of a conapt balcony. Neighbors whose names you might actually learn, although probably only after checking their professional profiles first. Execs, successful professionals, senior Fixers, and people with money that prefers not to advertise its source can buy the fantasy of ordinary suburban life in the middle of a recovering megacity.

Of course, the gate changes everything. Acadia Way isn't a surviving neighborhood anymore. It's a preserved specimen. Outside, Night City rebuilds through noise, displacement, hunger, and opportunism. Inside, somebody waters flowers. If a target lives here, getting close means defeating the very thing the residents are actually paying for: **the ability to pretend nothing beyond the gate is their problem.**`,
  },

  c2: {
    image: "continental-brands-offices",
    text: `Continental Brands chose one of Downtown's new skyscrapers for its Night City headquarters because nothing says *the future has returned* quite like putting a food conglomerate in a tower of fresh glass. The upper floors contain exactly what you'd expect from one of the world's major food companies: offices, administration, meeting rooms, and the occasional chemical laboratory quietly working on whatever comes after "food." The architecture is new. The workspaces are professional. Somewhere above the city, people make decisions that determine what millions of other people are going to eat.

The first two floors are considerably more interesting. They contain the **Oasis Megamart**, Continental Brands' largest Oasis store in Night City. Calling it a grocery store feels inadequate. In a world still clawing its supply chains back together, a supermarket this large is a monument to logistics. Shelves stretch beneath hard commercial lighting, stocked with Continental products, packaged foods, drinks, household goods, nutritional substitutes, and enough branded choice to manufacture the impression that scarcity is somebody else's problem. People come from across the city simply because Oasis has things their neighborhood store doesn't.

That makes the building both corporate headquarters and temple. Downstairs, customers buy the products. Upstairs, executives decide what the products will become. Somewhere between those floors are loading docks, inventory systems, laboratories, security doors, data, formulas, contracts, suppliers, and corporate secrets. A Netrunner might break in looking for research. A Fixer might want shipping manifests. A desperate neighborhood might simply want a truckload of food. **Continental Brands feeds Night City, which means somewhere in this building is a spreadsheet explaining exactly how hungry the city is allowed to become.**`,
  },

  c3: {
    image: "cortex-complex",
    text: `Somebody designed the Cortex Complex to resemble a human brain. **They should probably apologize to the human brain.** Constructed by Halsey, Ferris & Skiv, the building bulges and folds through Downtown in a way that is technically thematic and aesthetically unfortunate, an office complex whose architectural concept becomes less charming the longer you look at it. Locals have compared it to everything from grey matter to something dropped by a particularly large animal. The important thing is that the offices are affordable by Downtown standards, the elevators mostly work, and nobody has yet proven the building causes migraines by proximity alone.

Two notable businesses operate inside. **Jack Skorkowsky Real Estate** deals in the hottest commodity in the rebuilding city: property. Land, apartments, development rights, relocations, leases, and all the little pieces of paper that determine who gets to remain somewhere after somebody richer notices it. **DizCom**, meanwhile, handles industrial design, the less glamorous but enormously profitable work of deciding what tomorrow's manufactured world will look like before factories begin producing it. The tenants fit Downtown perfectly. One sells the city's physical space. The other helps design the things that will fill it.

For an edgerunner, Cortex Plaza is the sort of place where a job sounds boring until it very suddenly isn't. Steal property records. Photograph a prototype. Intimidate an assessor. Recover architectural plans. Find out why one DizCom engineer hasn't gone home in three days. Office buildings conceal crimes exceptionally well because everyone assumes anyone carrying a briefcase belongs there. **Sometimes the hardest part of a Cortex Complex job isn't breaking in. It's discovering which completely ordinary office contains the reason somebody hired you to kill.**`,
  },

  c4: {
    image: "delirium",
    text: `Delirium begins where ordinary nightlife stops pretending reality is enough. The three-story **gothpunk virtuality club** is owned by Magnus Haggard and attracts seemingly every mutation of goth, punk, fetish-fashion obsessive, virtuality devotee, and nocturnal creature Night City can manufacture. Black clothing is merely the baseline. Latex, leather, chrome, antique lace, luminous implants, skeletal prosthetics, mourning veils, combat boots, synthetic wings, sharpened silhouettes, and fashions that appear to have escaped from particularly expensive nightmares crowd together beneath the club's lighting. Nobody looks strange here. **Looking ordinary takes effort.**

Delirium operates across three levels. The second floor contains a small stage for live performers, surrounded by walls and ballet-style bars that become part railing, part dance apparatus, part invitation for somebody to make a regrettable decision. The third floor is more restricted, divided among security, a VIP lounge, and Haggard's own apartment. Virtuality transforms the rest. Patrons can layer synthetic spaces over physical architecture until a crowded club becomes a cathedral, graveyard, alien landscape, ruined palace, or shared hallucination designed by whoever controls the night's experience.

That's also what makes Delirium useful. A person can be physically standing ten meters away and appear to be somewhere else entirely. Messages can hide inside environmental overlays. A meeting can happen in a virtual crypt while security cameras record two patrons staring silently at an empty wall. Someone can change the Architecture mid-set and turn entertainment into panic. And upstairs, behind the VIP barriers, Magnus Haggard watches his strange kingdom operate beneath him. **At Delirium, reality isn't sacred. It's just the default setting.**`,
  },

  c5: {
    image: "night-city-firestation-2",
    text: `Night City Fire Station #2 looks less like a municipal building and more like somebody expects the fire to shoot back. **Often, it does.** The station is large, fortified, heavily equipped, and considered the best-funded firehouse in Night City. Its crews respond to incidents throughout the Rebuilding Urban Zones and to arson calls along the edges of the Combat Zones, which means a normal shift can involve structural fires, chemical spills, collapsed buildings, unexploded ordnance, armed gangs, damaged electrical grids, industrial accidents, and civilians who refuse to evacuate because everything they own is inside the burning apartment.

The station's answer to this environment is equipment and chrome. Some of its firefighters are **Full Body Conversions**, people whose biological bodies have been almost entirely replaced with cybernetic frames capable of entering environments that would cook, crush, poison, or tear apart an ordinary responder. Imagine a firefighter walking through flames carrying enough structural strength to rip open a collapsed security door, thermal systems painting victims through smoke while armored hands move debris that would normally require machinery. Night City invented cybernetic bodies for war, industry, and survival. Fire Station #2 found another use: **sending them into hell to bring somebody back.**

That doesn't make the work clean. Firefighters see what remains after Night City's worst nights. They know which landlords bypass safety systems, which gangs burn buildings for territory, which corporations quietly transport hazardous materials through residential blocks, and which "accidental" fires always seem to happen just before redevelopment contracts are signed. They also arrive before investigators do. Before cleanup crews do. Before somebody has remembered to remove the evidence. A firefighter can become an extraordinary contact in Night City because they don't merely know where the bodies are buried. **Sometimes they're the ones who pulled the bodies out.**`,
  },

  the_hot_zone: {
    image: "the-hot-zone",
    text: `The Hot Zone is where Night City keeps its ghost. Twenty-two years ago, this was the center of corporate power on the West Coast, a vertical kingdom of banks, luxury hotels, media towers, corporate plazas, AV pads, restaurants, and mirrored skyscrapers where fortunes moved faster than traffic below. Then the bomb went off beneath Arasaka Towers in 2023. Buildings folded into one another. Streets vanished beneath rubble. Underground infrastructure collapsed or flooded. Cars burned where they stopped. Thousands of people disappeared beneath concrete, steel, glass, and ash. Night City eventually rebuilt around the crater, but it never rebuilt **here**. Step across the invisible boundary into the Hot Zone and the modern city simply ends. No bright storefronts. No dependable CitiNet. No traffic. No advertisements politely asking for your money. Just shattered towers leaning against a red sky and twenty years of wind moving through empty windows.

The radiation has diminished since the immediate aftermath, but diminished is not the same thing as gone. The Health Department still warns people to enter protected, and anyone scavenging deep ruins without a detector is gambling with something considerably slower than a bullet. Worse, the contamination isn't always obvious. Precious metals pulled from buried corporate vaults have reached the Night City black market still carrying enough radiation to make people sick, forcing banks to start testing recovered gold before accepting it. That's the Hot Zone's particular cruelty: **everything valuable survived in the same rubble that can kill you.** Somewhere beneath those collapsed offices are twenty-year-old corporate prototypes, weapons, jewelry, encrypted drives, medical equipment, cyberware, cash, pharmaceuticals, research samples, and vaults nobody ever opened. Every scavver knows there might be a fortune thirty meters away. Every scavver also knows thirty meters may be the difference between going home rich and never going home at all.

There is no City Manager because there is barely a city here to manage. The NCPD technically provides security, which is Night City bureaucracy's way of making a joke without realizing it. In practice, the Zone belongs to whoever can hold whatever piece they're standing on. **Maelstrom** runs major scavenging operations among the ruins. Reckoners stalk the camps and preach about the end of the world to people already living inside convincing evidence for it. Lightning Cats move through the district, scavver crews carve territories around profitable ruins, and squatters inhabit whatever structures look unlikely to collapse before breakfast. There are people living here because nowhere else will take them. People hiding because nobody else comes looking. People digging because one good score might get them out forever. And predators who understand that someone desperate enough to enter the Hot Zone probably has very few people waiting for them to return.

The Zone shrinks a little every year. Reconstruction crews advance inward from Little Europe, Upper Marina, and the Glen, clearing rubble, testing soil, stabilizing foundations, and reclaiming one poisoned block at a time. From a distance, that sounds hopeful. Up close, reclamation is another war over territory. Maelstrom sabotages work sites. Scavvers resent bulldozers burying treasure they haven't extracted yet. Reckoners don't necessarily appreciate civilization erasing one of their finest arguments for the apocalypse. Heavy equipment breaks under brutal conditions, sometimes naturally and sometimes with considerable assistance. Behind the crews come fences, construction trailers, private security, land claims, surveyors, developers, and people explaining how much your miserable patch of ruin has suddenly become worth. **Night City isn't healing the wound so much as purchasing it by the square meter.**

For an edgerunner, nowhere else in the city offers quite the same combination of opportunity and dread. The Hot Zone is an enormous dungeon without a GM generous enough to map it for you. Streets terminate beneath collapsed buildings. Basements connect to forgotten subway tunnels. Corporate offices hang sideways fifty stories above the ground. A door sealed since 2023 might open onto a pristine laboratory, a room full of skeletons, or both. Urbanauts climb impossible structures because somebody has to prove they can. Scavvers kill one another over coordinates. Corps quietly hire crews to recover things they officially insist were destroyed decades ago. And sometimes, beneath all the danger, you find something painfully ordinary: a desk with photographs still attached to it, a child's shoe beneath concrete, an apartment table set for a dinner that never happened. That's when the Hot Zone becomes more than ruins. **It's the place where Night City remembers that the Fourth Corporate War wasn't history when the bomb fell. It was somebody's Tuesday.**`,
  },

  d1: {
    image: "the-ashcroft-hotel",
    text: `Before the bomb, the **Ashcroft Hotel was the address in Night City**. Owned by the wealthy Ashcroft-Hammersmith family, it was the city's largest, most expensive, and most exclusive hotel, the kind of place where European corporate royalty, celebrities, and famous Solos paid thousands of eurobucks a night to have every unpleasant feature of reality removed from their immediate vicinity. Security was provided by elite German professionals and guaranteed in writing. Restaurants, luxury shops, AV pads, immaculate suites, polished metal, expensive fabrics, staff trained to anticipate desires before guests voiced them. If the old Corporate Center was Night City's throne room, the Ashcroft was where visiting aristocracy slept. Then 2023 arrived.

The building still stands only because **its two ruined halves are leaning against each other**. One wing tilts into the other like a pair of dying giants refusing to fall separately. The old gleaming exterior is scorched and pitted. Ground-level entrances disappeared beneath rubble long ago, forcing access through improvised elevated routes. Inside, floors slope at sickening angles, hallways terminate in open air, welded gangways bridge gaps where sections of hotel no longer exist, and even modest explosions can make the entire structure shudder. Maelstrom turned this corpse of luxury into the logistical center of its Hot Zone scavenging operations, filling it with diggers, guards, salvaged equipment, weapons, cameras, and whatever the gang drags out of the surrounding ruins. The suites where executives once complained about pillow firmness now store radioactive treasure pulled from dead corporations.

The Ashcroft also has a darker recent history. A Maelstromer called **Ripper** once ran scavenging crews from inside the hotel, forcing diggers into the ruins while conducting grotesque cybernetic experiments of his own. His operation was eventually brought down, but Maelstrom kept the Ashcroft as its scavenging hub afterward. That history hangs over the place because buildings remember what people use them for, even when people don't. Somewhere inside might be a forgotten penthouse safe sealed since 2023. Somewhere else, a Maelstrom crew is sorting cyberware beside a banquet hall that once hosted million-euro corporate weddings. **The Ashcroft used to prove how rich Night City could make you. Now it proves how thoroughly Night City can take everything back.**`,
  },

  d2: {
    image: "the-n54",
    text: `The **N54** was once Network 54's Night City headquarters, a broadcasting tower belonging to one of the organizations that helped decide what millions of people believed had happened that day. Then the bomb tore most of its façade away and left the skyscraper standing naked above the ruins. Somehow, impossibly, it remains the tallest structure in the Hot Zone. From several districts away you can still see its bent skeleton stabbing upward from the wreckage, upper floors and old satellite equipment hanging over a city that no longer needs the building for anything. For most sane people, that's a warning. For **urbanauts**, it's an invitation.

Climbing the N54 and tagging the summit has become a Night City tradition among urban explorers. There is no safe route because the building is no longer sufficiently interested in architecture to provide one. Climbers cross exposed beams hundreds of meters above the street, squeeze through twisted structural cavities, trust corroded staircases, improvise ascents through elevator shafts, and crawl around sections where the exterior simply isn't there anymore. Wind becomes an opponent. Metal moves beneath your hands. Every floor offers a spectacular view of exactly how far you'll fall. Tags accumulate near the summit like names carved into the wall of a shrine, each one saying the same thing in a different hand: **I came up here and the city didn't get me.**

There is one place nobody tags. Near the top sits a tent containing the remains of an urbanaut known as **Lailah**, still accompanied by an FN-RAL. Tradition says you salute her and leave everything untouched. Steal from the site and the climb becomes cursed. Maybe that's superstition. Maybe people who disturb unstable objects at the top of a bomb-damaged skyscraper simply experience unusually predictable bad luck. Either way, the tradition holds. Reach the summit, add your mark, look across Night City from higher than almost anyone else in the Hot Zone, and suddenly you understand why people keep doing it. **For a few minutes you're standing above the place that killed an entire skyline. Then comes the difficult part: getting back down.**`,
  },

  d3: {
    image: "toggles-temple",
    text: `Somewhere beneath the western edge of the Hot Zone, a conspiracy theorist named **Toggle** has built what may be the finest private firearms playground in Night City. Toggle's Temple sprawls through an interconnected maze of old sewers, abandoned basements, underground parking garages, utility spaces, and whatever other forgotten pieces of pre-War infrastructure could be stitched together without anybody official noticing. The customer entrance isn't even in the Hot Zone proper. It's hidden inside a Little Europe sewer tunnel a few blocks north of Short Circuit. You don't find the Temple because you saw an advertisement. **Someone who already knows Toggle decides you should know where the door is.**

Inside is an edgerunner's ballistic fever dream. There's an enormous armory filled with weapons customers can borrow, conventional firing ranges for people interested in merely shooting things, and an elaborate configurable obstacle course modeled after the "crime houses" used to train tactical police teams. Rooms and routes can be rearranged into combat scenarios, letting crews practice entries, room clearing, target identification, movement under fire, and the extremely useful skill of discovering how badly their supposedly brilliant tactical plan survives contact with an actual hallway. Handguns, SMGs, assault weapons, bows, heavy weapons: Toggle's philosophy seems to be that preparedness is a spectrum and **rocket launchers happen to sit on it.**

Then there's Toggle. Competent enough to run the sprawling facility largely alone, paranoid enough to have constructed it in the first place, and famous for theories involving conspiracies that occasionally make Night City's genuine conspiracies sound disappointingly conservative. One of the Temple's recurring themes is preparation for threats most people would regard as implausible, which becomes considerably funnier once you remember what qualifies as normal in 2045. Toggle's secrecy is protected partly by the facility itself and partly by a loyal clientele of edgerunners who understand how useful the place is. Laugh at the dolphin conspiracy if you want. **Just do it after Toggle finishes teaching you how to clear a kill house with a shotgun.**`,
  },

  d4: {
    image: "totentanz",
    text: `**Totentanz means Dance of the Dead. Nobody involved appears concerned that the name might be too subtle.** The club occupies the upper floors of the ruined Burleson Tower, an old one-star hotel that survived the 2023 disaster badly enough to remain standing and well enough for Maelstrom to decide it was home. Totentanz had already been a notorious boostergang club before the bomb, a place where chrome-heavy gangs came to drink, fight, and turn recreational violence into a spectator sport. After Maelstrom lost its old territory in the fires following the nuclear blast, survivors fought their way into Burleson Tower, killed the rival gang occupying it, stabilized what remained of the structure, and reopened the club. In the Time of the Red, **Totentanz isn't merely where Maelstrom parties. The tower is the beating, malfunctioning mechanical heart of the gang.**

Getting there means entering a building that probably should have collapsed years ago and then climbing toward loud music and people who regard extreme cyberware as an ideological commitment. Maelstrom occupies the middle floors, stores scavenged equipment and cyberware throughout the tower, keeps vehicles below, and maintains security under the watch of leaders like **Warlock** and his lieutenants. Their main meeting space contains one of the gang's more unsettling traditions: fire-scarred chrome recovered from members who died after the 2023 blast, including the mummified remains of former leader **Hammer**, displayed as relics. Wearing cyberware taken from those dead members is considered an honor. Maelstrom doesn't merely remember its history. **It bolts history onto itself.**

Totentanz itself is noise, metal, bodies, alcohol, and barely contained violence. Other boostergangers can enter, but Maelstrom law is the only law that matters once you're inside. Historically, the club measured a successful night partly by the body count, and beneath the tower lurks **the Pit**, a place used for punishment and entertainment where Maelstrom keeps something closer to a captive cyberpsycho than a pet. Even by 2045, the entire structure is deteriorating badly enough that Maelstrom knows it will eventually need another home. That gives the place the atmosphere of a party being held aboard a sinking ship by people who have decided the correct response is to turn the amplifiers up. Walk into Totentanz displaying fear and they'll smell it. Walk in displaying too much confidence and somebody will want to test it. **The trick is looking like you belong in a room where everyone is trying very hard to become less human than the person beside them.**`,
  },

  little_china: {
    image: "little-china",
    text: `Little China exists in the uncomfortable space between Combat Zone and neighborhood, and everybody living there understands how much hangs on which word wins. By the 2040s, much of the district had become a dangerous sprawl of damaged buildings, improvised communities, gang territory, failing infrastructure, and streets where municipal services were closer to rumors than guarantees. Yet scattered among all of that are blocks where doors lock, businesses open every morning, children go somewhere resembling school, and people sweep the sidewalk because they expect there to still be a sidewalk tomorrow. Wealthy members of Night City's Chinese community helped fund the Little China Redevelopment Association, and the LCRA has been clawing territory back one block at a time. In the places it has successfully secured, life can feel almost normal. In Little China, almost normal is an extraordinary achievement.

The man most closely associated with that ambition is David Ling Po, appointed City Manager by the LCRA and tied deeply into Little China's business and political life. Under his watch, redevelopment isn't being presented merely as construction. It is a declaration that Little China intends to rejoin the urban center on its own terms rather than wait for outsiders to decide the neighborhood has finally become valuable enough to save. Gold Dragons Security patrols much of the reclaimed territory, giving certain streets a level of stability absent elsewhere in the district. The difference can be startling. Walk through one intersection and you're passing scaffolding, shops, apartment windows, and elderly people carrying groceries. Walk five minutes in the wrong direction and you're counting Red Chrome Legion tags while wondering why every intact window suddenly has someone watching from behind it.

Little China is crowded because people make room where there isn't any. Cargo containers become homes. Apartment buildings hold twice as many people as they were designed for. Ground floors turn into markets, clinics, noodle shops, tailors, repair stalls, pharmacies, gambling rooms, and businesses without English names because nobody operating them needs one. Electricity is negotiated. Plumbing is shared. Somebody's bedroom ceiling is somebody else's shop floor. Food smells drift through alleys already thick with exhaust, incense, hot circuitry, damp concrete, cheap disinfectant, frying dough, old river water, and the particular electrical perfume of overloaded infrastructure. The neighborhood doesn't possess much empty space, so life simply stacks itself upward.

And life here has predators. The Red Chrome Legion maintains a presence, bringing its ugly ideology and violence into a community with very little patience for either. The Weng Fang Tong has influence beneath the surface of respectable institutions, while the Gold Dragons occupy the strange Night City position of being both community protectors and part of a larger criminal ecosystem. Fixers work the gaps between all three. Smugglers know the waterfront. Edgerunners know which alleys belong to whom after midnight. Ordinary residents survive by cultivating the sort of neighborhood intelligence no Agent can provide: which block is safe tonight, whose nephew joined the wrong gang, which shopkeeper will hide someone in the back room, and when the sound outside means stay inside. Little China survives partly because people here understand that community can function as infrastructure when infrastructure stops functioning.

And above all of it rises Guăngbō Tower, wrapped in scaffolding and ambition. The LCRA has poured money into restoring the old broadcasting tower while other buildings still wait for repairs because symbolism matters. Its reopened interior houses businesses, security offices, civic organizations, entertainment, and one of Night City's increasingly rare public libraries. Property values around it are already climbing. To critics, that's redevelopment theater. To supporters, it's proof that Little China is coming back. Both may be right. That's the district's tension in one building: every repaired window is hope, every rising rent is a warning. For an edgerunner, Little China is therefore never just another Combat Zone. It is a neighborhood halfway through deciding what it will become, and everybody from gangsters to landlords to grandmothers is fighting for a hand on the pen.`,
  },

  e1: {
    image: "bridgetown",
    text: `Bridgetown hangs beneath Pelican Boulevard because nobody with better options builds a neighborhood under an overpass. Cargo containers are stacked, welded, bridged, wired, and repurposed into a dense little community beside the waterfront, forming towers of corrugated steel underneath the concrete shadow of the elevated roadway. Windows have been cut where shipping manifests once went. Extension cables snake between homes. Walkways have been improvised from scrap metal, timber, old ladders, and optimism. When heavy traffic passes overhead, the entire place seems to vibrate faintly in sympathy. It's cheap by Night City standards, which explains almost everything else.

Nighttime gunfire is common enough that residents have learned to distinguish between a fight that's going to keep going and one that will burn itself out in thirty seconds. The waterfront provides its own uglier calendar. Enough bodies are dumped upriver that Bridgetown residents have learned roughly how long a weighted corpse remains underwater before decomposition brings it back to the surface. About three days. Tuesdays can be bad. Incense sells particularly well in the neighborhood, partly for the dead and partly because river air occasionally requires spiritual and practical intervention at the same time.

Yet Bridgetown isn't merely a slum waiting for somebody to rescue it. People live here. They know one another. Somebody fixes generators. Somebody watches children while their parents work. Somebody always has a pot going. Residents paint containers, hang lights, reinforce stairs, and construct tiny porches six meters above the ground because human beings possess a remarkable ability to turn even temporary shelter into home. An edgerunner looking for someone in Bridgetown may discover that finding the right container is easy. Getting the neighborhood to admit the person exists is another matter entirely.`,
  },

  e2: {
    image: "chrome-cross",
    text: `There are dive bars where dangerous people drink, and then there's Chrome Cross, where the danger is part of the clientele's identity. The damaged building sits in the Little China Combat Zone not far from the old Forlorn Hope, held together with the same combination of neglect and stubbornness as much of the surrounding block. Outside, salvaged cars and trucks collect in the parking lot, mismatched body panels covered in poorly spelled hate slogans. Inside, the Red Chrome Legion drinks. That tells any sensible person everything required to make an informed decision about entering.

The Legion brings its neo-fascist ideology into the room with all the subtlety of a brick through a window. Chrome, red insignia, racist propaganda, intimidation, and the constant possibility of violence establish the atmosphere. Outsiders are judged immediately. People the Legion hates are not welcome. People the Legion merely dislikes may be tolerated if there's profit involved. The bar attracts dealers and other parasites willing to conduct business with the gang, including Fixers moving illicit braindances and whatever else can be exchanged for eurobucks without requiring anyone involved to possess principles.

That makes Chrome Cross useful to exactly the sort of edgerunner who already knows entering is a terrible idea. Need to identify a Legion lieutenant? Buy something from somebody using the gang as protection? Plant a tracker beneath one of those ugly trucks? Find out who's supplying them weapons? Chrome Cross puts targets in one convenient building, surrounded by heavily armed extremists who will interpret even a slightly unusual sneeze as provocation. Sometimes intelligence work is sophisticated. Sometimes it's walking into the worst bar in Little China and trying not to look like you have a reason for being there.`,
  },

  e3: {
    image: "forlorn-hope",
    text: `Before the events of Hope Reborn, the Forlorn Hope is one of those rare Night City institutions that doesn't advertise because the right people already know where it is. The bar began as a gathering place for veterans, founded by John "The Professor" Freeman and built around the simple idea that people who had survived war needed somewhere to sit among others who understood what survival had cost them. Over the decades it became a home away from home for veterans of the SouthAm conflicts, the Fourth Corporate War, and the endless smaller wars people insist on calling jobs. Solos dominate the room, but experienced Fixers, Netrunners, Nomads, cops, and other professional survivors are part of the family too.

The Hope is quieter than the Afterlife. That's important. The Afterlife is where edgerunners go to build reputations. The Forlorn Hope is where people with reputations no longer need to explain themselves. Conversations have history behind them. Old photographs mean something. A joke can reference an operation twenty years ago and leave half the table laughing while everybody else wisely stays quiet. Marianne Freeman keeps the place running, while its longtime circle of veterans and professionals gives the bar the peculiar feeling of a military reunion that never entirely ended. Even Rogue has been known to use the Hope to meet promising edgerunners who haven't yet earned their way into the Afterlife.

For a young merc, being invited inside matters. Nobody rings a bell or hands you a membership card. You simply realize one night that the person beside you knows your name, somebody pours without asking what you drink, and the old Solo at the end of the bar has finally stopped watching your hands. Jobs circulate here, but so do warnings, favors, introductions, and the kind of advice that keeps people alive. The Afterlife asks what legend you're going to become. The Forlorn Hope asks whether you'll survive long enough to become old.`,
  },

  e4: {
    image: "guangbo-tower",
    text: `Guăngbō Tower is Little China looking Night City directly in the eye and saying, we are still here. Before the Fourth Corporate War it housed the KLIA radio station. By 2045, the thirty-story building is being dragged back from ruin by the LCRA despite portions of its exterior still looking distinctly pre-revival. Scaffolding clings to the tower while crews rebuild the façade, and the old burned-out KLIA sign remains hanging outside like a scar nobody has decided whether to remove. Inside is another story. The rehabilitation has advanced far enough for roughly twenty organizations and businesses to move in, sending surrounding rents upward and giving local merchants something they haven't had enough of lately: confidence.

Guăngbō is almost a vertical neighborhood by itself. Gold Dragons Security operates from the basement, complete with firing range, gym, martial hall, garage, and holding cells. Ling Po Imports occupies lower floors. The LCRA works from the ninth and tenth. The Ling Po Public Library, one of the precious few libraries readily accessible to ordinary people in 2045 Night City, keeps a collection ranging from Tang Dynasty literature to Cantonese comedy and manhua. Higher up, Libertine Lanes recreates a beloved pre-War bowling alley using painstakingly salvaged original materials. At the top, Virtex's Virtuality Venue offers classic and modern games high above the district. The tower is offices, entertainment, community infrastructure, politics, commerce, and security stacked thirty floors high.

Which makes it one of the most interesting buildings in Little China for an edgerunner. Almost everyone important eventually has a reason to pass through. Community organizers ride elevators beside Tong-connected businessmen. Gold Dragons drink after work beside teenagers coming from the arcade. Somebody researching neighborhood history might be three floors from somebody arranging a smuggling operation. The ventilation doesn't work particularly well, the exterior is still half construction site, and the building carries more political expectations than some governments. None of that matters. Every evening, Guăngbō's occupied windows light up above streets once written off as Combat Zone. Little China doesn't need the tower to be beautiful yet. It needs people elsewhere in Night City to see the lights.`,
  },

  e5: {
    image: "prosperity-gardens-tenements",
    text: `The name Prosperity Gardens contains at least fifty percent more prosperity than the building does. The mixed-use tenement block on Lum Place is packed far beyond anything resembling intended occupancy. Some apartments house entire extended families in spaces designed for two people. Some tenants share bathrooms. The less fortunate carry drinking and washing water from a standpipe downstairs. Ground-floor businesses include the sorts of places a neighborhood actually needs: a cheap tailor, dry-goods shop, bodega, and a Chinese cruller shop that can make the entire miserable corridor smell considerably better than it looks. Yet despite the overcrowding, rent is high and there's a waiting list.

The reason is simple: Prosperity Gardens may be the safest place to live in Little China. Nobody knows why. Trouble arrives. Trouble disappears. Gang members, thieves, and other predators who cause problems around the building have a habit of turning up later tied to lampposts near Guăngbō Tower, alive, heavily concussed, and incapable of agreeing on what hit them. Residents have theories. Naturally. Theories multiply whenever somebody's jaw is broken by an invisible community-service program. The mysterious vigilante has become part protector, part urban legend, and part extremely persuasive argument for paying Auntie Hung's rent on time.

Auntie Hung, the landlady, is herself enough reason to behave. She keeps the building remarkably clean, refuses to tolerate graffiti, and happens to be an expert practitioner of Hung-gar kung fu who has taught students ranging from successful mercenaries to Weng Fang Tong lieutenants. Winning her favor reportedly involves gifts of cognac, cigarettes, or seafood, though anyone mistaking that for softness is volunteering for a practical demonstration of traditional martial arts. Prosperity Gardens sometimes hosts a bustling day market too, making its courtyards and ground floors some of the most alive spaces in the neighborhood. It's cramped, noisy, under-serviced, and held together by repairs layered on top of repairs. People are desperate to live there anyway. In Little China, safety doesn't need marble floors. Sometimes it just needs an old woman with standards and something in the shadows that scares the gangs more than they scare the tenants.`,
  },

  university_district: {
    image: "university-district",
    text: `The University District is narrow because Night City has never allocated much room for contemplation. Wedged along the edge of territory that has repeatedly threatened to collapse into Combat Zone conditions, it contains the city's only surviving traditional institution of higher learning and the ecosystem that has grown around it. Before the Fourth Corporate War, this part of Night City was supposed to be the intellectual counterweight to the Corporate Center: students, professors, bookstores, parks, cafés, brownstones, laboratories, and the old Night City University campus arranged around the idea that a functioning metropolis required somewhere devoted to something other than profit. Then the Corporate Center exploded. The university remained. Commerce got a crater. Academia got walls.

Those walls matter. Night City University has become an academic fortress, surrounded by barriers, controlled entrances, hardened buildings, and Campus Security because occasionally the violence outside decides education looks like an easy target. The campus consequently feels less like a modern university and more like a monastery that discovered assault rifles. Students still argue about politics beneath synthetic grass, professors still complain about budgets, food trucks still gather near the cafeteria, and somebody is always late for class. But all of it happens inside a defensive perimeter. NCU's longtime dean, Edward Michaels, has spent years trying to preserve the institution's independence, particularly from corporations eager to turn research funding into influence. In Night City, insisting knowledge should remain independent of whoever pays for it qualifies as a radical political position.

The irony is visible just across the district. Biotechnica occupies a large eastern campus of laboratories, offices, greenhouses, geodesic domes, armed security, and tunnels that allow employees to move between buildings without breathing too much Night City air. The corporation conducts botanical research publicly and significantly stranger work less publicly. At night, people living nearby have reported metallic scraping, howls, and screams coming from behind the fences. Biotechnica denies anything unusual is happening, which is reassuring only if you've never encountered a corporation before. Half the neighborhood's scientists seem capable of discussing genetic reconstruction over coffee while forgetting that ordinary people consider the sentence we improved the animal a reasonable place to start asking follow-up questions.

Around these institutional fortresses grows the actual neighborhood: students living three to a cube because rent is rent, professors drinking beside people who forged their student IDs fifteen minutes earlier, guerrilla gardeners producing vegetables more valuable than some electronics, artists and performers keeping old cultural buildings alive, and gangs whose identities are built around forgotten entertainment franchises. The Philharmonic Vampyres perform opera in a gothic concert hall. The Princesses of Justice turned an abandoned children's carnival into a fortified refuge and garden. NCU students party in apartments overlooking the Hot Zone because young people have always demonstrated an extraordinary ability to treat catastrophic danger as an interesting backdrop for Friday night.

For an edgerunner, the University District is therefore one of Night City's strangest hunting grounds. Here, the valuable thing usually isn't money sitting in a safe. It's information. Research. Samples. Student records. Genetic material. Academic reputations. Corporate secrets. A professor somebody wants recruited. A prototype Biotechnica insists doesn't exist. A missing student. An experiment that escaped. A plant capable of surviving contaminated soil. A rumor overheard at Yewtree that turns out to be worth fifty thousand eurobucks. The University District survives because people here still believe knowledge can build a better future. Night City, naturally, keeps asking what that knowledge is worth on the open market.`,
  },

  f1: {
    image: "biotechnica-campus",
    text: `Biotechnica's Night City campus looks less like corporate headquarters and more like somebody dropped a research colony onto the city and decided the locals should remain outside. Office buildings and laboratories sit among enormous geodesic greenhouse domes, rooftop terraces, secured compounds, and carefully maintained fragments of greenery. Fences surround the property. Armed security patrols around the clock alongside custom-built security dogs, while underground tunnels connect buildings so employees can travel without exposing themselves to the polluted air outside. The corporation's public-facing work focuses heavily on botanical science and ecological reconstruction, subjects that sound almost humanitarian until you remember who owns the patents.

Then there are the noises. Residents nearby have reported metal scraping against metal, animal howls, and screams coming from the campus after dark. Biotechnica insists there is nothing mysterious happening. Biotechnica also conducts genetic work on animals, including experiments intended to enhance species and help reconstruct damaged ecosystems, as well as cloning work connected to high-end cyberpets. Much of that isn't advertised on the visitor brochures. Somewhere behind those greenhouse walls, the distinction between conservation, product development, and *what exactly did you people make?* has become rather flexible.

Which makes the campus irresistible to edgerunners and terrifying to sensible ones. A client might want research stolen, an escaped specimen recovered, an employee extracted, or proof that one of those midnight noises possesses a serial number. Breaking in means fences, trained security, secure laboratories, decontamination checkpoints, tunnels, and scientists who may be considerably more frightened of whatever is inside their lab than they are of you. If something starts howling after the lights go out, the important question isn't whether Biotechnica created it. It's whether Biotechnica can still control it.`,
  },

  f2: {
    image: "biotechnica-habitation-sphere-alpha",
    text: `Sphere Alpha is what happens when your employer decides commuting is an unnecessary source of independence. The massive geodesic dome sits inside Biotechnica's secured campus and houses roughly half of the employees who work there. Apartments exist beneath the same broad structure as rare plants and controlled greenery, while tunnels connect residents directly to laboratories and offices elsewhere on campus. The result is part corporate housing, part greenhouse, part research colony. Residents wake beneath engineered climate systems, walk through secured corridors to work, and can go days without setting foot in the actual city.

Getting inside from outdoors requires roughly five minutes of decontamination. Tunnel checkpoints are faster, but hardly pleasant. The high-pressure process is infamous for destroying natural hairstyles badly enough that many residents simply switch to Techhair. The especially interesting part is that employees refuse to explain why the procedures are so aggressive. The official answer involves Night City's pollution. The unofficial answers involve pollen, experimental organisms, genetic contamination, escaped spores, proprietary microorganisms, and one particularly entertaining theory involving a plant that learned to recognize employees.

Sphere Alpha is beautiful in the sterile corporate sense. Greenery grows where the city outside struggles to keep weeds alive. Air smells clean. Temperature remains perfect. Residents have rooftop access and botanical surroundings unavailable to almost everyone else in Night City. Then you notice every entrance is a decontamination chamber. Paradise looks different once you realize management is equally concerned about keeping the outside world from getting in and whatever lives inside from getting out.`,
  },

  f3: {
    image: "night-city-symphony-hall",
    text: `The Night City Symphony Hall survived long enough to become something wonderfully ridiculous. Built as a grand gothic venue for opera, orchestral music, theater, and serious culture, it eventually fell into disuse after the Fourth Corporate War. Then the Philharmonic Vampyres moved in. Today the old stone building still greets visitors with marble steps, towering pillars, and the architectural dignity of an earlier Night City. Inside, long red drapes, velvet doors, gold fittings, holographic classic vampires, black candles, and theatrical gloom have transformed the venue into somewhere Count Dracula might have opened after securing an arts grant.

The Philharmonic Vampyres are not content merely to occupy the place. They perform. Operas, plays, concerts, elaborate productions, and parties draw students from nearby NCU, who seem entirely willing to overlook the gang affiliation if tickets are cheap and the afterparty looks interesting. Their shows aren't necessarily prestigious, but they are enthusiastic, theatrical, and memorable. In 2045, a gang shootout reportedly erupted during one performance. Only gangers were hurt. Within days, the incident had largely faded from local conversation. That's not because nobody cared. That's because Night City has an extremely demanding definition of noteworthy violence.

For a crew, Symphony Hall is a dream of balconies, backstage corridors, dressing rooms, rigging, hidden offices, catwalks, curtains, crowds, and people wearing costumes elaborate enough to conceal almost anything. A contact might insist on meeting during the second act. A target might be performing. Somebody could hide a rifle above the stage. And if the Philharmonic Vampyres invite you into their private offices behind doors marked with the seal of Vlad Tepes, try not to insult the décor. They have committed to the bit for decades.`,
  },

  f4: {
    image: "night-city-university",
    text: `Night City University was founded in 1994 as Richard Night University, part of Richard Night's original vision for a city where scholarship would balance corporate power. That balance went spectacularly wrong everywhere else, but NCU endured. By 2045 it is the city's central institution of traditional higher education, a collection of science buildings, humanities facilities, libraries, clinics, administration halls, student spaces, and newer structures such as the Loggagia Arboretum, where plant specimens donated by Biotechnica are preserved. It remains a genuine university. People study history here. Engineering. Science. Art. Politics. They argue about philosophy inside a city where philosophical disagreement frequently ends with somebody drawing a handgun.

The campus itself has become heavily fortified because the University District borders dangerous territory and gang incursions are not theoretical. Walls, controlled entrances, Campus Security, and hardened architecture give NCU the atmosphere of a scholastic monastery preparing for siege. Inside those defenses, university life continues with magnificent stubbornness. Students sprawl across synthetic grass near the cafeteria. Food trucks compete for their eurobucks. Professors hurry between classes. Research assistants survive on caffeine and poor decisions. Protest movements form, fracture, and reform. Counterculture thrives because putting thousands of educated young people behind walls has historically failed to produce political quiet.

NCU also possesses what every institution in Cyberpunk eventually acquires: secrets. Researchers accept funding they shouldn't. Students investigate things they shouldn't. Corporations recruit talent before graduation. Professors have enemies. Archives contain information powerful people assumed disappeared during the War. Campus Security knows considerably more about student activities than students would appreciate. NCU teaches people to ask questions. Night City provides an endless supply of people who would prefer those questions remain unanswered.`,
  },

  f5: {
    image: "parkside-living",
    text: `Parkside Living is what happens when somebody builds apartments overlooking the Hot Zone and college students respond, "Yeah, but how's the rent?" The studio complex sits near the border between University District and the Glen, close enough to Biotechnica and NCU to attract students and even some faculty. City authorities have declared the building safe despite its proximity to the ruins, and that was enough for people desperate for housing to move in. Students who can afford something better than cube life particularly like Parkside because it offers off-campus freedom and easy access to nightlife in the Glen.

During the academic year, the complex behaves less like an apartment building and more like a dormitory whose resident assistants surrendered years ago. Music leaks through walls. Somebody is always hosting something. The main-floor lounge is notorious as an information exchange where gossip moves faster than official university communication. Who slept with whom, who failed what class, which professor is leaving, whose research grant vanished, which student got arrested, which club has drugs tonight. Parkside residents can reconstruct half the university's social ecosystem without opening their Garden Patches.

Strangely, the place often feels safer than it probably is. There is comfort in noise, lights, neighbors, and the certainty that somebody nearby is awake at three in the morning. For an edgerunner seeking information about NCU, Parkside may be more useful than hacking the university itself. Academic secrets begin in laboratories. Student secrets begin in the lounge. The student secrets are usually much more entertaining.`,
  },

  f6: {
    image: "princessland",
    text: `Once upon a time, Princessland! was a traveling children's carnival built around an animated show called Princesses of Justice. There were themed rides, tea parties, bright decorations, smiling heroines, and enough licensed merchandise to crush the spirit of any parent carrying a wallet. Then the Fourth Corporate War happened while the carnival was in Night City. The operators abandoned it. The rides rusted. The lights went dark. Years later, a posergang styling themselves after those same cartoon heroines moved in and decided the story wasn't finished.

Under their leader Adorable, the Princesses of Justice transformed the abandoned carnival into something astonishingly functional. Flowerbeds became gardens. Attractions were repurposed for food production. The old Mermaid Princess waterpark became a fish farm. The gang repairs what it can, cultivates crops, and operates one of Night City's rare shelters for people fleeing domestic abuse. Entry isn't casual. Visitors often have to prove themselves through favors, and some of those favors involve persuading abusive former partners that pursuing someone into Princessland would be an exceptionally poor lifestyle choice.

The whole place has an uncanny beauty. Faded cartoon castles rise above vegetable plots. Old ride vehicles become storage bins. Smiling fiberglass princesses watch armed women patrol between gardens. At night, jury-rigged lights illuminate attractions whose designers never imagined they'd become defensive architecture. Princessland was built to sell children a fantasy about brave heroines protecting the innocent. The Princesses of Justice took that fantasy far more seriously than the company that created it.`,
  },

  f7: {
    image: "stems-and-seeds",
    text: `Fresh vegetables in Night City are not decoration. They are contraband from a better world. Stems & Seeds is a guerrilla gardening collective near NCU run by botanist Lily Ramos, also known as Lily Larson, a former Petrochem researcher who lost her corporate position following the post-War reshuffling that produced Continental Brands. Rather than abandon her expertise, Lily started growing food. Real food. Plants rooted in soil and hydroponic systems, tended by human hands, harvested rather than manufactured. NCU students provide much of the labor, earning a little money and some fresh produce in return.

The operation looks chaotic until you watch Lily work. Beds, containers, improvised greenhouse panels, nutrient systems, water storage, salvaged grow lamps, compost, seed stock, and defensive measures fit together with the precision of an engineering project disguised as a community garden. Restaurants and other businesses buy natural ingredients from her, giving Stems & Seeds a commercial footprint larger than its humble appearance suggests. A crate of excellent tomatoes can be worth serious money in a city raised on Kibble.

That creates problems. Crops can be stolen. Water can be contaminated. Seeds can be patented. Corporations can suddenly remember that a cultivar technically belongs to them. Students can disappear. A strange fungus can arrive in a shipment from somewhere it shouldn't exist. Stems & Seeds embodies a simple act that becomes strangely rebellious in Night City: put something living into the ground, care for it, and expect to still be there when it's ready to harvest.`,
  },

  f8: {
    image: "university-cubes",
    text: `University Cubes is student housing stripped down to its mathematical minimum. The cube hotel sits on the waterfront just beyond NCU's fortifications, offering tiny rooms to people whose educational ambitions are considerably larger than their housing budgets. A cube gives you somewhere to sleep, somewhere to store a few possessions, and enough privacy to pretend the person six centimeters beyond the wall isn't also studying for tomorrow's exam. For students counting every eurobuck, that's often sufficient.

NCU rents roughly half the building as overflow accommodation for teaching assistants and adjunct professors, producing one of Night City's stranger residential mixtures. A freshman surviving on instant noodles may share a communal washroom with the person grading their midterm. A lecturer with three degrees may sleep in a compartment barely larger than their desk because academia has preserved at least one ancient tradition intact: exploiting junior faculty.

The hallways smell of caffeine, laundry, cheap food, and overheated electronics. Students study on floors because their rooms are too small. Relationships begin and end within earshot of everyone. Somebody is always running an unauthorized server. Somebody else is making food with an appliance explicitly forbidden by the lease. University Cubes teaches an important lesson before class even begins: higher education can expand your mind considerably faster than it expands your living space.`,
  },

  f9: {
    image: "yewtree",
    text: `Yewtree is a slightly overpriced neo-hipster bar near NCU where the beer is fashionable, the furniture looks deliberately mismatched, and almost everyone drinking there insists they discovered the place before it became popular. Students pack the room most nights. Officially, the bar checks identification. Unofficially, the bouncers possess a remarkable inability to recognize fake student IDs. This is not incompetence. It's policy. Management reached the extremely sensible conclusion that college students will find alcohol regardless, so it might as well happen somewhere adults are quietly watching.

The arrangement goes deeper. Yewtree covertly cooperates with NCU Campus Security. Drinks are watered just enough to keep students partying without becoming catastrophically intoxicated, and bartender Stuart Hedley pays close attention when someone appears to be deliberately getting another person drunk. Serious concerns find their way back to Campus Security. The students generally have no idea. They think they've beaten the system. The system is serving them ten-eurobuck watered beer and taking notes.

That makes Yewtree one of the district's best places to hear things nobody intended to become intelligence. Students talk when they drink. Researchers complain about supervisors. Teaching assistants gossip about projects. Somebody mentions a strange delivery to Biotechnica. Somebody else says their roommate hasn't come home. A professor drinks alone after discovering their funding disappeared. Yewtree's greatest product isn't alcohol. It's the extraordinary amount of information generated when educated people become convinced nobody important is listening.`,
  },
  the_glen: {
    image: "the-glen",
    text: `The Glen is where Night City keeps the people who decide what happens to everyone else. **Politicians write the laws here. Banks decide which dreams receive financing. Courts decide who disappears. Police decide which streets are worth protecting. Corporations decide what all of those decisions are worth.** After the Fourth Corporate War, Night Corp and its allies transformed portions of old South Night City into a new administrative center, pouring money into government buildings, financial institutions, embassies, parks, residential towers, and infrastructure while much of the surrounding city was still learning how to keep the lights on. Today the Glen is one of Night City's safest and wealthiest districts, protected by NCPD, private security firms, and enough armed corporate muscle to make spontaneous crime require considerably more planning than usual.

The result is less a government district than an **ecosystem of influence**. Step outside City Hall and you can walk to the Hall of Justice, Night City's largest bank, the headquarters of the NCPD's First Division, foreign consulates, investment firms capable of moving national economies, and corporate towers containing companies whose products may already be installed inside your skull. Lobbyists crowd cafés. Lawyers eat beside city officials. Foreign diplomats ride elevators with Fixers. Execs drink at Club Atlantis after work while somebody from City Hall quietly explains which construction contracts are about to become available. The wealthy don't necessarily need to conspire here. They simply keep encountering one another at lunch. That is much more efficient.

Running the district in 2045 is **City Manager Zohara Freeman**, a former Combat Cabb CEO and daughter of former Mayor Mbole Ebunike and actress Rachel Becher. She was appointed by Night Corp rather than arriving through anything resembling an ordinary political career, and she has worked hard to make the Glen visible as Night City's model of recovery: festivals, concerts, public events, beautification programs, a pristine public park, and plenty of face time with residents. She is clever enough to balance corporate demands against public expectations while never forgetting which side can afford better lawyers. Night City still technically operates under a state of emergency, and there hasn't been an ordinary mayoral administration for years. **Democracy survives here, but someone keeps checking its expense account.**

That money creates resentment beyond the district's polished edges. In 2045, residents of South Night City discovered that Night Corp had redirected funds meant for their reconstruction toward upgrades in the Glen, including the NCPD's First Division headquarters. Their protest marched into the governmental district and erupted into an hours-long battle with police, leaving casualties and expensive property damage. Nobody agrees who started it. The more important question is why people from a struggling district had to march past gleaming towers built with money they believed had been taken from them. Even today, construction never quite stops. New towers rise, security checkpoints multiply, and rumors persist that somebody has been planting explosives inside unfinished buildings. **The Glen is proof Night City can rebuild. It is also proof that rebuilding is a political decision about who gets rebuilt first.**

For an edgerunner, this makes the Glen exceptionally dangerous territory because **violence here wears paperwork**. In a Combat Zone, somebody wants you dead and sends a booster with a gun. In the Glen, somebody cancels your banking privileges, flags your Agent, issues an arrest warrant, revokes a permit, buys your landlord, freezes your assets, and sends the booster afterward if you remain inconvenient. Jobs here revolve around information, leverage, evidence, influence, access, and the tiny weaknesses hidden inside supposedly impregnable institutions. A clerk with gambling debts can be worth more than a platoon of Solos. A stolen financial record can destroy an Exec. A security badge can open a door no amount of gunfire will. **Night City may be ruled from corporate boardrooms, but the Glen is where power gets stamped, notarized, financed, prosecuted, and filed.**`,
  },

  g1: {
    image: "1st-night-city-bank",
    text: `**If Night City has a bloodstream, an uncomfortable amount of it passes through 1st Night City Bank.** The institution is the city's largest local bank and one of the main arteries through which Night Corp distributes money to companies, developers, and individuals involved in keeping the city functioning. It is where prosperous citizens park their fortunes and where local projects come looking for financing, provided the people requesting money can first demonstrate that they don't particularly need it. The irony is not lost on anyone waiting outside with a business plan and no collateral.

The lobby deliberately looks reassuringly old-fashioned. Marble floors. Classical music. Red velvet queue barriers. **Actual human tellers.** Bulletproof windows provide views over the park outside, and loan officers conduct business inside quiet private offices. Upstairs sits the real vault, separated from public space by identification requirements, retina scans, cameras, and heavy security. The nostalgia ends abruptly once someone tries walking through the wrong door.

That makes the bank one of Night City's most seductive impossible jobs. Rob the vault? Probably suicidal. Steal a loan file? Much more interesting. Change the ownership record on a construction company? Suddenly worth millions. Discover who received financing two weeks before the city announced a redevelopment project? Now you're playing the game that actually matters. **The smartest thieves don't come to 1st Night City Bank looking for money. They come looking for proof of where the money went.**`,
  },

  g2: {
    image: "air",
    text: `Air has discovered the logical endpoint of capitalism: **charging people to breathe.** Night City's atmosphere is polluted badly enough that masks occasionally become a practical necessity, so somebody built a sleek oxygen bar for customers wealthy enough to turn respiratory function into nightlife. Air resembles a sterile white showroom more than a club, with transparent glass bars, tiny brushed-steel stools, and rows of clear masks dangling above the counter. Select a blend, slot your credchip, put on the mask, and enjoy sixty glorious seconds of atmosphere that hasn't been trying to poison you.

The house favorite is the **Alpine Mountain Blend**, a scented mixture containing twenty-percent oxygen with pine and herbal notes, sold by the minute. People sit beneath spotless lighting inhaling imaginary mountain air while traffic outside pumps exhaust into the street. Deals happen through transparent masks. Execs hold conversations between measured breaths. Couples come here on dates and discover that apparently nothing says romance like watching a meter deduct eurobucks every sixty seconds.

Air is ridiculous until you've spent a week working in the Hot Zone. Then that first clean breath hits your lungs and suddenly ten eurobucks doesn't seem unreasonable. That's the genius of the place. **Night City ruins something everyone once received for free, then opens a luxury business selling it back.**`,
  },

  g3: {
    image: "bears",
    text: `Bear's doesn't look remotely sophisticated enough for the Glen, which is precisely why people love it. The bar is named partly for its owner, **Bear Young**, an enormous Solo with a rolling laugh, and partly for the moth-eaten bear head mounted above the counter. Family legend insists Bear's great-grandfather personally killed the animal in Canada. Nobody has verified the story. Nobody particularly wants to accuse Bear of lying while standing within arm's reach.

The reason people actually come is the beer. Bear believes good ale should be thick, rich, and substantial enough to qualify as food, and he has little patience for breweries disguising bad flavor beneath chemistry. Apprentices train under him while the kitchen pushes out SCOP burgers, fries, chili con Kibble, and wings. His celebrated **Berry Beer** uses blackberry purée during secondary fermentation and reaches a cheerful nine percent alcohol. Local folklore also claims Bear once threw two Maelstromers out by himself, laughing while he did it, then bought the room a round. That story receives considerably less skepticism than the bear head.

Bear's is therefore one of the Glen's great pressure-release valves. Civil servants loosen collars here. Solos stop performing toughness. Lawyers complain about clients. Construction crews drink beside people financing the buildings they're erecting. A Fixer can conduct business without the suffocating status games found elsewhere in the district. **Sometimes the best place to learn what the powerful are really thinking is wherever they go when they're tired of being powerful.**`,
  },

  g4: {
    image: "city-hall",
    text: `Night City destroyed its old center of government and rebuilt another one in the Glen because apparently the city's faith in bureaucracy is harder to kill than concrete. The new **City Hall opened to the public in 2037**, deliberately echoing the pre-War building with a colonial-style design constructed largely from wood. That sounds almost quaint until you notice the scanners, drones, defensive systems, armed NCPD officers, and security infrastructure surrounding it. The architecture says civic tradition. The hardware says somebody has tried to assassinate civic tradition before.

Inside, the building rarely stops moving. Lobbyists, corporate representatives, special-interest groups, bureaucrats, aides, Fixers, petitioners, journalists, foreign representatives, maintenance staff, security officers, and the occasional actual citizen flow through the corridors from morning until deep into the night. Night City remains under a state of emergency in 2045, with the City Council carrying much of the municipal burden after years without a conventional mayoral administration. Yet the machinery continues grinding. Permits get issued. Contracts get signed. Budgets get moved from one district to another. Somewhere, somebody discovers their neighborhood has been saved or ruined by a line item on page eighty-four.

Curiously, the sheer volume of people can sometimes become City Hall's greatest weakness. Properly credentialed professionals disappear into crowds better than masked intruders ever could. A courier walks through carrying the wrong envelope. An intern photographs a document. A lobbyist's assistant accepts money because their rent doubled. **Breaking into City Hall with guns is idiotic. Breaking into City Hall wearing a good suit and looking annoyed that somebody has delayed your meeting might actually work.**`,
  },

  g5: {
    image: "city-police-precinct-1",
    text: `Precinct #1 stands where the Glen presses against the Old Combat Zone and Old Japantown, and it looks less like a police station than a fortress built to prevent the rest of Night City from climbing over the border. The NCPD's First Division operates here, making the facility one of the most important police installations on the central Island. It contains communications systems, holding cells, an armory, crime facilities, drone rookeries, vehicle bays, classified files, and infrastructure for AVs, helicopters, and TAC Squad armored vehicles. More than two thousand officers fall under the First Division's sprawling responsibilities.

Getting through the front door involves decontamination, cyberware and weapon scans, armed guards, and the general feeling that the building distrusts you personally. Beyond the public areas, the internal design becomes intentionally confusing. Corridors twist into controlled sectors equipped with defensive systems capable of escalating from deterrence to lethal force. Precinct #1 also houses the central server for the NCPD's dedicated CitiNet and a vault containing classified hard-copy records considered too sensitive to digitize. **Somewhere inside are secrets the police don't trust computers to remember.**

The uncomfortable part is what happens outside. Precinct #1 technically serves enormous portions of central Night City, including several Combat Zones, but police presence is radically stronger in prosperous districts such as the Glen than in communities that cannot afford the same political attention. The headquarters therefore functions as both shield and symbol. From one side, residents see protection. From the other, people see thousands of officers standing behind a fortified border. **The law may be citywide. Response time has a zip code.**`,
  },

  g6: {
    image: "club-atlantis",
    text: `Club Atlantis is designed to make sobriety feel unreliable. Owned by heavyweight Fixer **Mister Kernaghan**, the multilevel nightclub assaults spatial reasoning with moving mirrored walls, sliding staircases, cerulean light, angular avant-garde art, robotic dancers, and a hovering central stage. You don't simply enter Atlantis. You become slightly uncertain whether the room moved while you were looking away. The bar serves liquor from around the world, including the absurdly expensive HALO Drop, a Manhattan built around Highrider whiskey.

The clientele is exactly who you'd expect to find near Night City's administrative center after midnight. Execs come to burn off stress. Fixers come because stressed Execs make excellent customers. Glitterkids come because everyone else is there. Live performers occasionally appear without warning. Danger Gal handles security and keeps obvious gang trouble outside, although the Piranhas have reportedly adapted by conducting their business in the parking lot. Meanwhile, the upper levels conceal **Mister K's invitation-only Midnight Market**, where people capable of dropping ten thousand eurobucks without visibly flinching can purchase luxuries unavailable through ordinary channels.

Atlantis is therefore one of those rare Night City locations where three entirely different jobs can be happening on three floors at the same time. Downstairs, a junior Exec is getting drunk enough to leak merger plans. On the dance floor, a Fixer is identifying potential talent. Upstairs, somebody is quietly purchasing an object they cannot legally own. **If the Afterlife is where edgerunners go to find dangerous work, Atlantis is where dangerous work sometimes puts on designer clothes and comes looking for them.**`,
  },

  g7: {
    image: "glenlife-perfected",
    text: `Glenlife Perfected has one of the finest exteriors in the district, which is useful because the landlord desperately wants prospective tenants to stop looking once they've seen it. The façade suggests sophisticated Glen living within walking distance of City Hall. The first-floor spaces reinforce the illusion. Everything works. Everything gleams. Everything whispers *you've made it*. Then the elevator groans, the tour goes one floor too high, and the building begins confessing.

The actual studios are cramped and prone to mildew. Power flickers when residents use appliances. Maintenance requests enter some bureaucratic afterlife from which none have returned. Elevators fail regularly. The landlord's commitment to repairs appears inversely proportional to how difficult a problem is to hide before the next viewing. Yet the building remains desirable because it sits only a block from City Hall in one of central Night City's safest neighborhoods. **It's a firetrap with excellent crime statistics.**

That creates a strange resident culture. Young professionals tolerate the mold because their commute is six minutes. Government clerks trade repair tips in the hallway. People whose offices oversee housing standards return home to apartments that violate several of them. Everyone complains. Nobody moves because the next comparable address costs twice as much. Glenlife Perfected embodies one of the oldest urban truths Night City managed to preserve through nuclear war: **location can forgive almost anything except the rent.**`,
  },

  g8: {
    image: "hall-of-justice",
    text: `The **Hall of Justice was designed by somebody who apparently felt courthouses were insufficiently terrifying.** Opened alongside City Hall, the enormous courthouse-and-jail complex blends brutalism with medieval fortress imagery: oversized towers, immense black steel doors, a portcullis, gray stone interiors, and enough oppressive scale to ensure defendants understand the architectural verdict before any judge speaks. Where City Hall uses wood and civic nostalgia to imply continuity, the Hall uses stone and steel to communicate one much simpler idea: *you are inside now*.

Lower floors process civilians and administrative matters. Higher floors handle increasingly serious criminal cases, creating the wonderfully Night City concept that the worse your alleged crime, the farther upward justice physically takes you. Rumors place the city's judicial AI, **the Judge**, somewhere near the top. Prisoners are held below ground in cells smaller than many cube hotel rooms, with chemical suppression systems capable of filling them with whatever guards decide the situation requires. Drones, scanners, automated defenses, and NCPD personnel watch everything. Eight years after opening, the place reportedly still hadn't suffered a successful conventional escape.

Outside, justice becomes entertainment. Executions and public electro-whippings can be staged in a concrete amphitheater, complete with paid seating, premium tickets, vendors, drinks, and snacks. Nothing quite captures Night City governance like watching somebody receive a state punishment while eating a SCOPdog. For an edgerunner, the lesson is obvious: **if a job ends inside the Hall of Justice, the time for the escape plan was yesterday.**`,
  },

  g9: {
    image: "kasims",
    text: `Kasim's announces itself by smell before sight: **cardamom, bitter coffee, rose-scented tobacco, and something sweet emerging from the kitchen.** Owner Kasymbek Kasim runs the Turkish coffeehouse without alcohol, in keeping with his beliefs as a devout Muslim, and closes the establishment on Fridays so he and his family can attend prayers. In a district built around people shouting into phones, Kasim's invites customers to sit down, smoke a nargile, listen to music, and allow conversation to take longer than absolutely necessary.

The coffee arrives thick, dark, unfiltered, and flavored with cardamom in tiny cups that look comically inadequate until the first sip explains why they're small. Pots come with sweets, often lokum or baklava made by **Elif, Kasymbek's mother**, who runs the kitchen and occasionally joins favorite customers outside. If she likes you enough, she may read the grounds left in your cup and tell you what she sees. Kasymbek himself has connections among the Thelas Nomads and may once have sailed with them, which helps explain how certain products find their way through supply chains that don't appear on conventional manifests.

Kasim's is consequently one of the best places in the Glen to exchange information without making the exchange look important. Reporters, musicians, Fixers, travelers, and regulars linger over games and tobacco. Nobody needs another drink to justify sitting there for an hour. **Night City has a thousand bars where somebody can overhear you yelling over the music. Kasim's gives you a corner, a tiny cup of coffee, and enough time to choose your words carefully.**`,
  },

  g10: {
    image: "merrill-asukaga-and-finch-offices",
    text: `If 1st Night City Bank handles ordinary wealth, **Merrill, Asukaga & Finch handles the kind of money that begins influencing geography.** The world's largest independent financial and investment institution occupies the upper levels of the pristine white Thurgood Towers, twin skyscrapers connected by elevated walkways. The offices are designed to project disciplined wealth rather than vulgar excess. The message isn't *look how much money we have*. It's *look how seriously we take yours*. New clients generally require referrals, because if you have to ask whether MA&F will manage your fortune, you may not possess a fortune worth managing.

Access is tightly controlled. Appointments are mandatory, armed escorts accompany visitors, and employees use implanted access technology to operate secured doors and elevators. Rumors claim those implants possess unpleasant secondary functions should an employee betray the firm. Half the skyscraper can remain vacant despite demand elsewhere in the Glen, either because rents are extraordinary or because MA&F simply prefers fewer neighbors. The lower floors house carefully selected businesses, while the firm's other civic oddity remains the **Night City Body Lotto**, whose winning claims are verified through MA&F. Imagine trusting the same financial institution with your investment portfolio and the official accounting of how many people died yesterday.

Edgerunners rarely need to steal money from MA&F. Information is better. Client lists. Investments. Short positions. Property acquisitions. Quiet bets against corporations that don't yet know they're failing. The wealthiest people in Night City tell MA&F what they expect the future to look like, then put money behind the prediction. **If you could see enough of those accounts at once, you wouldn't just know where the money is. You'd know where the city is going next.**`,
  },

  g11: {
    image: "night-city-plaza",
    text: `Night City Plaza might be the most extravagant thing in the Glen because **admission is free**. The lush, year-round public park is the largest green space in Night City and the spiritual center of the district, carefully maintained in a metropolis where many residents grow up knowing plants primarily as images on packaging. Corpzoners eat lunch here. Children play. Streetrats wander through just to see what living greenery looks like. On the southern side stand a statue of Richard Night and a memorial to those killed in the 2023 nuclear disaster, both guarded closely enough to discourage anyone from improving them with spray paint.

The Plaza is also a major performance space. Members of the Julliard Guild receive licenses to perform in the park, while unauthorized musicians periodically try their luck until NCPD moves them along. A professional stage hosts larger concerts and theatrical productions, and City Manager Freeman has made keeping the Plaza clean, safe, and active a visible priority. It is political symbolism you can picnic on. **Look, the city says. We can still grow grass. We can still play music. We are rebuilding.**

Which makes the Plaza perfect for stories. Political demonstrations happen beside corporate lunch breaks. Rockerboys perform beneath government surveillance. A clandestine meeting can happen on a bench precisely because everyone assumes spies prefer dark alleys. Somebody leaves a package beneath the nuclear memorial. Somebody plans an assassination during a concert. Somebody simply sits under a tree because they haven't seen one in months. **In Night City, a public park can be evidence of civilization, propaganda, a venue, a protest site, and a crime scene before sunset.**`,
  },

  g12: {
    image: "raven-microcybernetics",
    text: `Raven Microcybernetics has taken the unusual corporate approach of hiding one of Night City's most important cyberware operations inside a building so visually forgettable it practically possesses camouflage. The company occupies the upper ten floors of a fifty-story skyscraper on the Glen's northern side. Raven remains one of North America's premier cybernetics manufacturers, known for high-quality cyberware and electronics even after competitors such as Rocklin and Dynalar claimed greater market share. Security is provided by **McCain Security**, Raven's own subsidiary, whose personnel are better trained and equipped than ordinary rent-a-cops.

The floors beneath Raven are occupied by closely affiliated businesses, turning the skyscraper into a small corporate ecosystem. **Clean Sweep Enterprises** handles professional cleaning and electronic counter-surveillance. **Dayton Aeronautics** manufactures aircraft. **Everest VentureWare** deals in survival equipment. **KillStrom Music**, affiliated with EBM, produces high-end musical equipment. High-end surgeon **Doctor William Galen** also maintains medical offices in the building. None of these tenants looks particularly dramatic in a directory. Collectively, they represent exactly the sort of supply chain relationships a corporate intelligence specialist might become intensely curious about.

Raven's offices are therefore a magnificent place for a job that begins with cyberware and refuses to stay simple. A prototype is disappearing. An engineer is defecting. A partner company has been compromised. A competitor wants research. A patient of Doctor Galen has something installed that shouldn't exist yet. And because Raven sits forty floors above a building full of related companies, **the easiest way into the corporation may be through somebody whose business card doesn't say Raven anywhere on it.**`,
  },

  g13: {
    image: "seafoam",
    text: `Seafoam is what happens when the party leaves Club Atlantis, discovers nobody is ready to sleep, and pours itself into a cube hotel across the street. Most residents are club rats, temporary crashers, and people whose housing decisions have been heavily influenced by the sentence *it's close to Atlantis*. Around two in the morning, the communal spaces begin filling with refugees from the club. Music returns. Drugs appear. Somebody finds speakers. Somebody else finds people willing to dance. **Seafoam doesn't close because Seafoam never formally admits the party began.**

The downside is that security is nowhere near Atlantis standards. The Reckoners have learned that unconscious revelers constitute an excellent source of charitable contributions, and residents occasionally wake without money, equipment, inventory, or even pieces of chrome. One particularly charming habit involves leaving victims with a note thanking them for their "donation." The 2045 scene also includes a quiet relationship between Reckoners and Voodoo Boys supplying drugs to the crowds, proving once again that even apocalyptic cults understand vertical integration.

Yet the danger is part of Seafoam's attraction. For people who can't afford Atlantis prices all night, the hotel is where the social barriers collapse. Junior Execs end up beside street kids. Netrunners occupy corners. Musicians jam with strangers. Somebody knows where the after-afterparty is. Someone else knows where your missing Agent went. **You can have an extraordinary night at Seafoam. Just perform an inventory check before you start celebrating how memorable it was.**`,
  },

  old_japantown: {
    image: "old-japantown",
    text: `Old Japantown survived the bomb without taking a direct hit. The distinction was largely academic. When Arasaka Towers went up in 2023, the ground beneath the district partially liquefied, infrastructure buckled, and radioactive debris rode the wind eastward. Buildings that had survived the blast became unsafe. Streets cracked. Utilities failed. Cancer became something people discussed alongside rent and groceries. Anyone with sufficient money, connections, or common sense began moving north toward what would eventually become Kabuki and the Watson Development. The people left behind were the stubborn, the poor, the old, and those whose attachment to home outweighed their fear of what home had become. Two decades later, Old Japantown is still populated by the descendants of that decision.

What remains is not one coherent neighborhood so much as islands of civilization surrounded by Combat Zone sea. A fortified family enclave can sit three streets from a gang battlefield. A clean clinic operates around the corner from buildings nobody enters after dark. Convenience stores install serious security because keeping noodles and batteries on the shelves has become an act of civic infrastructure. Elderly residents still live in homes their families owned before the War while their grandchildren return from safer districts to look after them. You can walk past surviving Japanese restaurants, shrines, markets, old cultural landmarks, and patched-together apartment blocks, then turn the corner and see a burned-out vehicle being used as a Red Chrome Legion checkpoint. Old Japantown doesn't have a safe side and a dangerous side. It has safe rooms separated by dangerous hallways.

The official power structure is almost as compromised as the streets. Japanese corporation Sanroo bought cheap land here and, rather than tolerate an unpredictable local government, effectively bought that too. Its Pacifica Confederation branch manager, Adriane Casselle, serves simultaneously as Old Japantown's City Manager. Security falls largely to the Kimen-Gumi, a Tyger Claws splinter organization deputized to act as local law enforcement. They wear distinctive masks, patrol selected neighborhoods, arrest people, seize property, and maintain enough order for parts of the district to function. But Old Japantown is considered a career graveyard within the wider Tyger Claws organization. Some officers sent here see the assignment as punishment, and corruption thrives wherever resentment meets opportunity. The badge might belong to the city, the loyalty might belong to a gang, and the paycheck may ultimately originate with a corporation. That's Night City governance distilled to three signatures.

Beyond those pockets of control, the gangs are conducting a slow-motion war. The Iron Sights have spent years pushing the Red Chrome Legion northward, turning streets into territory measured in casualties. Maelstrom raids inward from the Hot Zone, testing Tyger Claw defenses before melting back into the ruins. The Kimen-Gumi tries to hold the center while everyone else probes the edges. Ordinary residents learn the geography instinctively. Which blocks belong to whom. Which colors not to wear. Which gunshots mean stay inside. Which ones mean leave through the rear entrance immediately. And above all hangs another problem nobody has solved: radiation still blows in occasionally from the Hot Zone, and cancer rates have been climbing despite experts insisting contamination should have diminished years ago. That suggests something out there may still be leaking. Old Japantown already survived one radioactive disaster. Somewhere nearby, something may be quietly preparing the sequel.

For an edgerunner, that fractured geography creates extraordinary possibilities. Here, a five-star hotel can stand behind armored doors while people sleep in leaking cargo containers a few blocks away. A used-car dealer can remain open in a Combat Zone because his husband is an ex-Lazarus Solo and his suppliers are Nomads. A hospital can offer state-of-the-art medicine without asking your name because corporations need desperate human beings for clinical trials. A bodega becomes neutral infrastructure because half the neighborhood depends on it. Old Japantown isn't empty ruins. That's what makes it dangerous. People have built lives here. Every block belongs to somebody, every surviving business exists for a reason, and every tiny patch of stability has teeth.`,
  },

  h1: {
    image: "crisis-medical-center",
    text: `Crisis Medical Center is what happens when excellent medicine loses its ethics committee somewhere during the apocalypse. Despite sitting in the middle of a Combat Zone, the facility possesses astonishingly advanced medical technology, much of it paid for by corporate benefactors including Biotechnica, Rocklin Augmentics, and Dynalar. Edgerunners, gang members, Solos, street people, and anyone else requiring serious repair can come through the doors without explaining precisely how the bullet got there. Crisis treats all factions and has established itself as neutral ground. Bringing somebody's street war into the hospital is considered exceptionally bad manners.

There is, inevitably, a price hiding underneath that generosity. Crisis constantly runs drug trials, cyberware evaluations, psychiatric studies, and experimental medical procedures funded by its corporate partners. Volunteers receive a little cash for participating, which attracts people from nearby communities who desperately need both money and healthcare. Rumors claim the distinction between patient and test subject can become fuzzy once you're inside. Perhaps the doctor asks permission before trying a prototype clotting compound. Perhaps consent appears somewhere in the electronic paperwork you accepted while bleeding through your shirt. The equipment is too good for the neighborhood because the neighborhood isn't really the customer. The neighborhood is the sample population.

That's what makes Crisis magnificent RPG territory. A crew can come here because they genuinely need surgery and leave wondering why somebody took an extra vial of blood. A corporation hires them to recover an escaped trial participant. A Medtech discovers patient outcomes have been falsified. Someone in the Precipice starts displaying the same strange side effect as three other volunteers. Or an edgerunner wakes after emergency surgery with a piece of chrome they don't remember authorizing. Crisis Medical saves lives every night. Whether every life leaves the hospital exactly as it entered is a separate question.`,
  },

  h2: {
    image: "highcourt-plaza-hotel",
    text: `Highcourt Plaza should not exist here. That's part of its appeal. In the middle of Old Japantown's crumbling Combat Zone sits an elegant Art Deco hotel with polished surfaces, indoor pools, spas, exceptional food, silk sheets, clean rooms, and the nearly miraculous promise of beds containing no vermin whatsoever. Before the city fell apart, Highcourt was one of Night City's premier luxury hotels. Somehow it simply refused to stop being one. Walk through its doors and Old Japantown disappears behind glass, brass, immaculate carpets, and employees trained to behave as though gunfire several blocks away is somebody else's scheduling problem.

The trick is reaching those doors. The Highcourt maintains extremely serious private security, strong enough that trespassers have historically become removal problems rather than guest-relations problems. Most wealthy visitors don't drive through the surrounding district at all. The hotel contracts with Aerocab to bring guests in by AV, dropping them directly into safety from above. Employees aren't afforded quite the same luxury. They ride an armored shuttle from an NCART station in Little China and presumably spend the journey reconsidering their career choices. Oddly, management markets the hostile neighborhood as a feature: paparazzi, stalkers, investigators, and overeager fans have to survive Old Japantown before they can bother anybody staying upstairs.

That makes Highcourt ideal for the wealthy person who needs privacy without officially needing protection. Celebrities hide here. Execs conduct discreet meetings. Somebody being hunted might book a suite precisely because getting to them requires crossing both a Combat Zone and hotel security. The Highcourt isn't an oasis despite Old Japantown. It's an oasis that weaponized Old Japantown as a moat.`,
  },

  h3: {
    image: "honest-hiros-used-cars",
    text: `Honest Hiro's is one of Old Japantown's genuine miracles: a used-car dealership where the adjective "Honest" is not entirely sarcastic. Hiro is a Fixer who keeps at least a dozen vehicles on his lot despite operating in the middle of a Combat Zone. Most arrive through Nomad contacts, particularly the Steel Vaqueros, who sell him cars and utility vehicles that aren't quite rugged enough for road-family work but are perfectly serviceable for city dwellers. Hiro understands exactly what he's selling and generally tells customers what's wrong with it. If he says the suspension is bad, the suspension is bad. If he says the engine will probably make it to Watson, the word *probably* is doing contractual work.

Hiro's security arrangement explains why the cars remain on the lot overnight. His husband, Steve, is a veteran Solo and former Lazarus operative who retains enough old contacts to make attacking the dealership a surprisingly ambitious criminal enterprise. Hiro also maintains relationships with edgerunners who trade protection work for access to vehicles. Down-on-their-luck runners occasionally sleep in old kombis and RVs parked around the lot, running power and water lines out to them for a fee. A crew needing wheels for a single job can sometimes rent something for the day, provided it comes back intact. Hiro knows perfectly well what the phrase *just one job* usually means.

The result feels less like a dealership and more like a tiny Nomad embassy that accidentally sells cars. Travelers arrive with news. Mercenaries trade favors. Somebody sleeps beneath a van while somebody else negotiates over an engine block. Need a getaway car nobody will trace easily? Hiro might have one. Need to know which road families recently came through Night City? Buy him lunch. Need somebody to overlook three new bullet holes when you return the vehicle? That conversation is going to cost more than the rental.`,
  },

  h4: {
    image: "mrs-suzukis-bodega",
    text: `In a district where businesses can disappear between Tuesday and Friday, Mrs. Suzuki's Bodega simply keeps opening the door every morning. The shop is the flagship of a small family-owned chain and widely regarded as Old Japantown's most secure, reliable market. Shelves carry Japanese staples, preserved foods, spices, packaged goods, household necessities, and whatever fresh ingredients can be sourced through Night City's broken supply chains. Gunfire outside occasionally provides the soundtrack. Customers keep shopping. There are neighborhoods where convenience means staying open late. Here it means still existing next month.

The store's most valuable products come from the Shroomers, an isolationist community living underground and cultivating huge gardens of fungus and lichen. Mrs. Suzuki is their exclusive Old Japantown distributor, giving her access to natural food that commands real value in the Time of the Red. That relationship also makes the bodega important to the Tyger Claws, who provide security through the Kimen-Gumi and reportedly offer favorable protection rates because everyone benefits from keeping the mushroom pipeline intact. Once a month, the Suzuki family also runs an invitation-only Night Market inside an abandoned big-box store. The best customers hear when. Everyone else hears afterward.

Mrs. Suzuki's therefore functions as much like community infrastructure as retail. People hear neighborhood news there. Fixers notice who suddenly started buying expensive food. Grandparents trade gossip beside armed gang members buying dinner. A stranger asking too many questions will be remembered before they've reached the register. In Old Japantown, an information network doesn't require servers. Sometimes it requires one woman, three generations of family, and knowing exactly who buys mushrooms every Thursday.`,
  },

  h5: {
    image: "the-precipice",
    text: `The Precipice is a cargo-container community close enough to the Hot Zone that the name feels less metaphorical than intended. Containers stack into improvised homes separated by narrow metal passages, staircases, balconies, electrical cables, water lines, and all the usual engineering compromises of people building housing out of objects designed to cross oceans full of freight. Residents worry about radiation drifting in from the ruins, which at least gives them one peculiar advantage: Crisis Medical Center is nearby and knows how to check whether the environment is slowly killing them.

Crisis has also become part of the local economy. Many Precipice residents earn extra eurobucks volunteering for the hospital's experimental programs. It's the perfect economic loop if you don't examine it too closely. Poor people live beside contaminated territory. Nearby corporations require human test subjects. The hospital offers advanced healthcare and money in exchange for participation. Residents sign up because groceries cost money. Sometimes capitalism doesn't need a conspiracy. Geography does the recruiting.

Which means the Precipice has unusually good neighborhood knowledge about medical experimentation. People compare side effects over meals. Someone knows which study pays well. Someone else warns never to volunteer for anything with a blue consent screen. A resident returns from Crisis with their tremor gone and their eyes behaving strangely. Another stops coming home altogether. For an edgerunner investigating one of the corporations behind Crisis, the most useful research database may be sitting outside on a folding chair, drinking cheap beer and showing you the scar where the prototype went in.`,
  },

  h6: {
    image: "unnamed-cube-hotel",
    text: `Nobody seems to know the name of this cube hotel. It's possible the building doesn't know either. There is one reinforced entrance, no visible staff, no cameras, questionable locks, and a lobby vendit that electronically collects rent from people who understand the value of a housing arrangement where nobody asks for references. Inside are the standard tiny windowless cubes, common facilities, and almost none of the institutional supervision that makes normal hotels inconvenient for criminals, fugitives, lovers, Netrunners, and people whose evening plans benefit from plausible deniability.

Cleaning is automated through ceiling-mounted water jets that hose down the rooms and drain into gutters cut along the floor. At least, they're supposed to drain. Not every room has been properly sloped, so some residents discover that housekeeping means waking to several centimeters of filthy water and learning which possessions float. The system doubles as eviction enforcement. Miss enough payments and whoever operates the building simply runs the jets until continued tenancy becomes an aquatic endurance event. There are landlords who send notices. This one apparently believes in pressure washing.

Yet the hotel has customers precisely because it's terrible. No cameras. No questions. No desk clerk remembering your face. Need somewhere to hide for forty-eight hours? Somewhere to conduct a meeting neither participant wants recorded? Somewhere your enemies can't simply bribe reception for your room number? The Unnamed Cube Hotel suddenly starts looking downright luxurious. Just wedge something beneath the door, keep your weapon within reach, and store electronics above floor level. Privacy is expensive in Night City. Here it's cheap because absolutely everything else is awful.`,
  },

  south_night_city: {
    image: "south-night-city",
    text: `South Night City is where Night City put everything respectable neighborhoods didn't want to look at. Long before the Fourth Corporate War, this was the industrial backside of the metropolis: warehouses, shabby worker housing, port infrastructure, freight yards, utility facilities, cheap commercial blocks, and miles of buildings constructed because somebody needed somewhere to put the people who kept the rest of the city running. Then 2023 shook the peninsula, refugees flooded south, infrastructure failed, gangs moved into the vacuum, and entire stretches of the district slipped into Combat Zone status. Twenty years later, factories still operate beside apartment blocks, freight still moves through streets where burned cars haven't been cleared, and thousands of people continue living beneath the industrial haze because being poor does not make somebody temporary.

The tragedy is that South Night City isn't beyond saving. Garven Haakensen simply isn't particularly interested in saving it. A former acting mayor who vanished after the Arasaka Tower disaster, Haakensen eventually returned with money, secrets, and enough leverage to buy himself a seat on the City Council. As City Manager, he has spent years converting public office into a personal revenue stream, scattering whatever remains after the kickbacks toward the district beneath him. His gleaming Haakensen Tower, the only modern skyscraper in South Night City, cost enough that locals bitterly joke the money could have fed the entire district for a year. To Haakensen's office, the tower is a beacon of renewal. To many residents, it's a forty-story middle finger with windows.

Even law enforcement has become another hustle. Haakensen has a habit of awarding security contracts to whoever makes the arrangement most attractive to Haakensen. In 2045, that means Scythe Security, a small outfit whose previous marquee assignment was guarding a shopping plaza. Suddenly they're deputized to police an entire Combat Zone. Their people carry patched armor and cheap GunMart weapons while desperately recruiting enough bodies to pretend the contract is achievable. They patrol some streets, guard selected businesses, and protect Haakensen Tower with admirable enthusiasm. Elsewhere, residents increasingly rely on guardian gangs, community organizations, armed neighbors, or themselves. There's even a persistent rumor that the contract was designed to fail, depressing property values so investors can buy South Night City cheap later. Neglect stops looking like incompetence when somebody has a financial position on the collapse.

And yet South Night City is ferociously alive. The Zoners organize residents and agitate for a future worth living in. The DeadWoods protect rail lines. The Sinful Adams turned a cemetery shantytown into one of the district's gentler communities. Artists still make music inside Silverhand Studios. Ripperdocs stitch strangers back together at Savage Docs while rival criminal organizations temporarily agree not to shoot each other near the operating rooms. Students live in cargo containers because the university district ends on one side of the street and affordability begins on the other. The Slammer lets gangs settle disputes with fists and blades instead of drive-bys. None of these people are waiting for City Hall. South Night City survives through a thousand small acts of people doing the job their government already invoiced them for.

That's what makes the district magnificent territory for edgerunners. Here, nearly every job exists inside the gap between what should happen and what actually does. Protect a tenant group because Scythe won't. Recover medicine because the supply convoy got hijacked. Find out who's buying condemned property. Guard a Halloween carnival in a graveyard. Extract somebody from a BD club whose problems go considerably deeper than gang violence. A corporation might hire you, a community might hire you, or somebody might slide a handful of wrinkled eurobucks across a table because you're the closest thing their street has to public services. South Night City is ugly, loud, exploited, and dangerous. It is also full of people fighting like hell to make tomorrow slightly less terrible than today. In Night City, that might be the purest form of civic virtue left.`,
  },

  i1: {
    image: "the-boneyard",
    text: `The Boneyard used to be the Night City Garden of Rest, a quiet cemetery where the dead were supposed to receive considerably more peace than the living generally managed. Then the Fourth Corporate War filled South Night City with refugees. People pitched tents between headstones, scavenged materials for walls, tapped illegally into city water mains, planted crops in the unusually fertile ground, and gradually transformed the cemetery into a shantytown. Years passed. Children were born. Gardens spread between graves. What began as temporary shelter became one of South Night City's strangest permanent neighborhoods. The dead got neighbors.

The Boneyard is controlled by the Sinful Adams, a neo-goth posergang who take both halves of that description seriously. They dress like walking funeral processions but care fiercely about the community beneath the eyeliner. They protect residents, maintain a small school where educated gang members teach local children, and react extremely badly to anyone desecrating the graves their homes were built around. Edgerunners can even camp here if they're willing to contribute and help defend the settlement. There's a local bar called the Crypt, and berry thickets growing around the cemetery provide ingredients for homemade alcohol. It's poor. It's improvised. By South Night City standards, it's remarkably pleasant.

Once a year, on Halloween, the Boneyard becomes something wonderful. The Sinful Adams throw an enormous carnival for residents and neighbors, filling the graveyard with performances, games, music, costumes, attractions, sweets for kids, and exactly the sort of theatrical excess you'd expect from goths handed a cemetery and a holiday. The event is famous enough that security sometimes becomes a paid gig in itself. Night City has neighborhoods where gangs terrorize children. The Sinful Adams run a haunted house for them. Choose your monsters carefully.`,
  },

  i2: {
    image: "mindnutz-lover",
    text: `MindNutz Lover is the hottest braindance club in South Night City, a status which means people willingly cross a Combat Zone to have somebody else temporarily occupy their nervous system. The exterior promises sensation. Inside, clients surrender themselves to braindances crafted to provide experiences reality cannot safely deliver: fantasies, violence, intimacy, exhilaration, terror, celebrity, power, and whatever stranger appetite somebody has learned to encode into neural signals. Scythe Security guards the establishment, making it one of the district's better-protected nightlife venues.

But MindNutz Lover carries one of Night City's nastier secrets. During the events surrounding Reaping the Reaper, the club becomes connected to a malevolent rogue AI known as the Reaper, an entity capable of weaponizing braindance technology against human minds. That turns the place from decadent nightlife into something much more disturbing. Plugging into a braindance already requires surrendering control over perception. Imagine discovering something on the other side is capable of surrendering you back differently.

Even without rogue AI, the club is an edgerunner's nightmare and playground. Someone can be physically present while mentally somewhere else. Patrons emerge disoriented. Memories can be confused with experiences. Security watches bodies while whatever matters may be happening inside somebody's head. A target can walk through the door voluntarily and become helpless five minutes later. At MindNutz Lover, asking whether someone saw something happen is useless until you establish which reality they were in at the time.`,
  },

  i3: {
    image: "savage-docs",
    text: `Savage Docs represents something dangerously close to trust in South Night City. The clinic began decades ago as the practice of the original Savage Doc, a respected ripperdoc who became a fixture of the old district. After his death, five apprentices kept the name alive, eventually expanding the operation into an old emergency medical facility with seven treatment rooms, three beds apiece, and enough equipment to handle serious trauma, surgery, pharmaceuticals, and cyberware installation twenty-four hours a day. Some machines are dated. The staff isn't. Savage Docs has earned a reputation for being fair, clean, competent, and safe, which in a Combat Zone makes it practically sacred ground.

The strangest proof of that reputation is security. The clinic is protected by both the Kanzaki Family Yakuza and the Tyger Claws, two organizations considerably more accustomed to trying to kill one another. Here, they don't. Both understand that eventually somebody important will arrive at Savage Docs leaking blood, and nobody wants the best local Medtechs afraid to open the door. It is essentially a healthcare version of mutually assured destruction. Hurt the clinic and someday the surgeon standing over your chest cavity might remember.

Johnny B Good, one of Savage Doc's original apprentices, has become the glue holding the operation together, combining serious medical skill with the much rarer ability to keep a Combat Zone clinic's books from exploding. He pays well for useful medical equipment, which naturally creates work for enterprising crews willing to ask very few questions about provenance. Need emergency surgery at three in the morning? Savage Docs will help. Need prototype cyberware installed without corporate paperwork? That's a conversation. Need to cause trouble inside the clinic? Congratulations. You've finally found something the Yakuza and Tyger Claws can agree about.`,
  },

  i4: {
    image: "silverhand-studios",
    text: `Long before the bomb turned Johnny Silverhand into myth, he did something surprisingly constructive with his money: he subsidized artists. Silverhand Studios converted warehouses into cheap lofts and creative spaces where musicians, painters, sculptors, photographers, performers, and assorted beautiful disasters could live cheaply enough to concentrate on making things. The South Night City location was already legendary before 2023, and many artists who later became significant started somewhere inside its high-ceilinged warehouse spaces. Then the War came, the building took a beating, and the artists did what artists reliably do when handed structural damage: they painted over it. By 2045 its scarred exterior disappears beneath an endlessly changing skin of murals.

After Johnny's death, Kerry Eurodyne took control of the Silverhand Studios operation. He's less involved than Johnny once was but still visits when he's in Night City, encouraging the musicians and artists keeping the idea alive. The South Night City building is managed locally on Kerry's behalf, and the old philosophy remains largely intact: creativity first, respect the people making things, tolerate a certain amount of chaos. What's disappeared is much of the old financial generosity. Rent is still comparatively reasonable, but starving artists are increasingly expected to starve on schedule.

The inside is exactly the kind of place that drives landlords mad and culture forward. Someone is welding a sculpture at midnight. A band is rehearsing below another band rehearsing. Somebody's shooting a music video in the stairwell. Somebody hasn't paid rent but has just finished the best painting anyone in the building has seen all year. Fixers occasionally appear looking for talent. Corps occasionally appear looking to purchase talent. Silverhand Studios exists because Johnny understood something Night City often forgets: rebellion needs somewhere to rehearse.`,
  },

  i5: {
    image: "the-slammer",
    text: `The Slammer is built around a radical idea for South Night City: maybe gangers can settle a dispute without shooting everyone standing nearby. The sprawling waterfront establishment occupies two buildings. One contains the crowded bar and dance floor, where strong drinks, deafening music, sea Nomads, boosters, mercenaries, and enough gang colors to start several wars coexist under extremely negotiated conditions. The other contains the Arena, a crude ring built from layered cinder blocks where people come to make those conditions considerably more explicit.

The Arena is no-holds-barred, but murder is not the point. Gangers from across Night City's Combat Zones reserve the space to settle disputes through direct combat instead of escalating into shootings, retaliations, and bodies accumulating for the next three weeks. Before a fight, terms are agreed. Afterward, the loser is expected to abide by them. Gambling is encouraged, with Fixer JessiGames handling much of the action. For people accustomed to street wars, the whole thing functions almost like trial by combat, a bizarre piece of shared law emerging from groups outsiders insist are lawless.

The owner, former Iron Sights ganger Cassius Brown, employs current and former gang members and maintains enough peace to keep the arrangement working. The house special is the Tongue Killer, Smash mixed with hot sauce, because apparently the Arena hasn't caused enough suffering. For edgerunners, the Slammer is an extraordinary information hub. Gang disputes become public knowledge. Bets reveal loyalties. A champion can become an ally. And if somebody challenges you to the Arena, remember: winning the fight is only half the problem. You still have to live with whatever you agreed to beforehand.`,
  },

  i6: {
    image: "south-cargo-village",
    text: `South Cargo Village occupies one of Night City's cruelest addresses: directly across the border from people whose lives are considered worth policing. The cargo-container community sits beside the Glen, close enough that residents can literally watch NCPD patrols moving along the safer side of the road. Those same officers generally treat the village as Combat Zone territory. Cross one street and response times change. Cross it the other way and suddenly there are patrol cars. You could teach an entire political science course without leaving the intersection.

The village itself is a familiar Time of the Red solution to an impossible housing problem. Old freight containers become one-room homes with improvised power, insulation, furniture, and communal sanitation facilities. Residents weld awnings over entrances, hang laundry between units, install locks that cost more than some appliances, and learn quickly who belongs. Somebody cooks outside. Somebody repairs electronics on a folding table. Kids know not to chase balls across certain streets. At night, lights from the Glen's better neighborhoods glow close enough to feel personal.

That border makes South Cargo Village ideal for smuggling people, information, and goods between two versions of Night City. Someone can leave a government building in the Glen, walk ten minutes, and meet a Fixer somewhere the police suddenly become reluctant to follow. Protesters gather here. Community organizers recruit here. Criminals exploit it. The residents don't need anybody to explain inequality to them. They can see the patrol cars from their front doors.`,
  },

  i7: {
    image: "union-chapel-building",
    text: `In its prime, the Union Chapel Building was an architectural showpiece: sweeping arches, beautiful stained glass, and the kind of graceful religious architecture built by people who assumed the neighborhood around it would remain civilized forever. Night City corrected that assumption one bullet at a time. Years of gang warfare damaged the structure faster than owners could repair it, until eventually everyone responsible for maintaining the place stopped pretending. The chapel was abandoned. Windows broke. Water entered. Beautiful details disappeared beneath soot and vandalism. Officially, the building became another dead structure in South Night City.

Unofficially, the Reckoners moved in. The apocalyptic cult now uses the ruined chapel for services, preaching about the coming Harvest of Souls to anyone willing, desperate, curious, or foolish enough to attend. They have even been known to offer cookies. It's difficult to decide whether that makes the situation more or less unsettling. Ruined stained glass throws fractured colors across people listening to sermons about the end of the world while violence and civic neglect continue outside, doing a remarkable amount of free promotional work for the theology.

For edgerunners, the Chapel is the kind of place where a simple reconnaissance job can become psychologically uncomfortable. The cult might be hiding fugitives in the basement. They might be stockpiling supplies. Someone you're searching for might have joined willingly. Maybe the Reckoners actually know something about a disaster other people haven't noticed yet. Conspiracy theorists are usually wrong. Night City remains deeply inconsiderate about guaranteeing that they're wrong every time.`,
  },

  i8: {
    image: "university-cargo-bay",
    text: `University Cargo Bay answers an important question: how badly do you want that degree? The tiny cargo-container community sits just over the border from the University District, technically inside South Night City's Combat Zone. It contains only around seven residential containers and offers some of the cheapest accommodation available to Night City University students. Which is useful, because tuition hasn't traditionally included the luxury of not being shot at while sleeping.

The students living here occupy a surreal academic frontier. One direction leads toward fortified NCU, lecture halls, libraries, professors, and students complaining about cafeteria prices. The other leads deeper into a Combat Zone. Gunfire at night is common enough to interfere with sleep, making noise-canceling headphones less study equipment than quality-of-life cyberware. Residents learn to identify weapons by sound with a competence rarely included on university transcripts. A freshman might spend the afternoon discussing philosophy and the evening pushing their desk against the container door because something loud is happening outside.

Naturally, the Bay develops fierce camaraderie. Seven containers is small enough that everybody knows everyone else's problems. Notes get shared. Food gets shared. Somebody with a Tech skill keeps everyone's electricity alive. Somebody's friend from Parkside brings contraband booze. If one resident hasn't returned after class, people notice. NCU teaches its students theory. University Cargo Bay provides the practicum in surviving Night City long enough to graduate.`,
  },

  port_of_night_city: {
    image: "port-of-night-city",
    text: `The Port of Night City never really sleeps. **It changes shifts.** Cranes swing cargo above black water beneath floodlights. Tugboats shove freighters into position. Forklifts scream between towers of containers while dockhands, Nomads, smugglers, customs crews, Fixers, and people whose job titles become deliberately vague after midnight move through the maze below. One ship pulls away and another is already waiting to take its berth. Food, machine parts, medicine, weapons, construction equipment, vehicles, electronics, people, and things nobody bothered putting on the manifest enter Night City here. The city may think of the Port as its back door. The people working it know better. **If the Port stops, Night City starts getting hungry almost immediately.**

And the people keeping that door open are **the Thelas Nation**, the largest Sea Nomad nation in North America. After the Fourth Corporate War shattered conventional supply chains, the Thelas did what Nomads everywhere did: they made themselves indispensable. By 2045 they effectively run the Port, with Fleet Captain **Angela "Calypso" Ng** serving as both City Manager and Harbormistress. The **Thelas Marines** provide security, but that's almost misleadingly formal. When serious trouble threatens the Port, every Thelas member is expected to put down whatever they're carrying and help defend the family. Corporations employ security departments. Thelas security is a society-wide obligation. **Attack the docks and the woman unloading your cargo may suddenly become part of the response force.**

The arrangement works because Sea Nomads understand ports as more than infrastructure. A corporate logistics manager sees throughput. Thelas sees weather, tides, families, favors, vessels, debts, repair schedules, smuggling routes, sailors who haven't been paid, captains who can't be trusted, and the difference between a ship that's three hours late because of mechanical trouble and one that's three hours late because somebody boarded it offshore. Their newly constructed loading quays run around the clock and remain a work in progress even in 2045, built not merely for today's traffic but for whatever Night City's resurgence brings next. Roughly a third of the Pacifica Confederation's goods move through this port, which means every functioning crane is doing geopolitical work whether the operator cares or not.

That doesn't make the Port safe. **It makes it organized.** The surrounding waterfront remains rough Combat Zone territory, with the Consortium and DeadWoods among the factions maintaining interests here. Legitimate businesses survive beside grey-market operations because everybody needs the same things: fuel, repairs, food, medicine, storage, entertainment, credit, and someplace to sell an object whose ownership history should not be examined too enthusiastically. Some stretches of seawall are so poorly maintained that approaching them is its own hazard. Cargo communities occupy spaces between working docks. Gangers visit body banks looking for cyberware. Apartment dwellers learn when not to use the local NCART station. Out on the bay, floating settlements assemble themselves from ships, pontoons, rafts, and stubbornness.

For an edgerunner, the Port is a machine that manufactures jobs. **Cargo is possibility with a tracking number.** A container arrives lighter than it left Busan. A ship captain refuses to unload until somebody aboard is found. A corporation needs prototype machinery recovered before the Thelas inspect it. A Nomad family wants stolen freight returned without involving outsiders. Someone needs passage out of Night City tonight, no questions, no passenger manifest. Someone else needs to know which vessel that person boarded. Follow almost any object in Night City backward far enough and eventually you reach a loading dock, a railhead, a highway, or a ship. Here, the trails converge. The Port doesn't merely connect Night City to the outside world. **It is the place where the outside world gets broken into pallets, priced in eurobucks, and handed over to Night City.**`,
  },

  j1: {
    image: "dock-13",
    text: `Dock 13 is occupied by a man who has somehow turned **being hated into a marketing strategy**. Willy Maze, better known as **Mister Amaaaze**, runs his business here with the evangelical enthusiasm of a Fixer who sincerely believes every object becomes more valuable if you yell about it loudly enough. His storefront promises extraordinary bargains, spectacular opportunities, unbelievable merchandise, and the sort of deals sensible people instinctively assume contain explosives. Occasionally, the operation blossoms into a full Night Market, drawing customers from across the district to browse whatever Maze has acquired, sourced, traded, salvaged, or described using strategically flexible adjectives.

The difficulty is that Mister Amaaaze has a remarkable gift for **angering dangerous people**. Gangers, edgerunners, corporate security personnel, cops, and dissatisfied customers have all reportedly found reasons to appear outside Dock 13 demanding restitution. Megaphones are common. Threats are routine. Gunfire isn't unheard of. His neighbors have been treated to furious people publicly discussing increasingly imaginative things they intend to remove from Maze's anatomy. The genius of his defensive strategy is beautifully simple: **he's almost never there when they arrive.**

Which means Dock 13 is simultaneously store, Night Market, rumor mill, trap, and ongoing performance art piece about the consequences of salesmanship. Need something bizarre? Ask Maze. Need something cheap? Definitely ask Maze. Need confidence that the person who sold it to him possessed legal title? **You are asking the wrong Mister Amaaaze question.**`,
  },

  j2: {
    image: "dock-14-studio-apartments",
    text: `On paper, Dock 14 should be one of the better cheap places to live along the waterfront. The apartment building sits directly at the end of the dock, close to work, close to transport, and close enough to the bay that residents can open a window and smell saltwater instead of whatever industrial process is currently happening inland. The studios aren't luxurious, but they offer actual apartments in a district where many people still sleep inside converted freight containers. Then you notice the neighboring pier. **Dock 13.**

Living beside Mister Amaaaze means accepting that your neighborhood soundtrack may include amplified advertisements followed several hours later by amplified death threats. Maze's speakers encourage shoppers to discover the best deals in Night City. His dissatisfied customers respond with megaphones. Some of them bring firearms to reinforce their customer-service concerns. Residents trying to sleep through the confrontation have developed strong opinions about soundproofing, local zoning regulations, and whether murdering a neighbor technically lowers property values if everybody already wanted to do it.

Still, Dock 14 has something approaching community. Waterfront workers come home at strange hours. Tenants trade warnings when another angry group appears outside Maze's shop. Someone always knows which dockhand can get you onto a vessel. Everyone has learned to distinguish routine shouting from the kind requiring movement away from windows. **The apartments aren't bad. The location isn't bad. The neighbor is a natural disaster with a sales pitch.**`,
  },

  j3: {
    image: "dock-cargo-community",
    text: `The Dock Cargo Community is squeezed between working piers because Night City looked at the problem of affordable waterfront housing and once again discovered the architectural potential of **objects originally designed to carry televisions across the Pacific**. Old shipping containers have been cut, insulated, wired, stacked, and converted into one-room homes. Communal facilities handle showers, laundry, and the bits of domestic life difficult to fit inside a steel box. Cranes loom above rooftops. Ship horns rattle windows. Someone's entire living room may still have faded shipping codes painted on the exterior wall.

The neighborhood has a curious weekly security cycle. Sea Nomads frequently dock nearby, attracted partly by proximity to places like the Slammer. While the Nomads are in port, their presence tends to keep the surrounding area comparatively peaceful. Few street gangers are eager to start trouble around several crews of sailors whose extended families include heavily armed people with boats. Then the weekend comes, the Nomads sail out, and ordinary Combat Zone mathematics reassert themselves. **Monday through Friday, neighborhood watch. Saturday and Sunday, neighborhood war.**

Naturally, the residents adapt. Valuable items disappear indoors before the weekend. People know which Nomad crews are friendly. Kids learn when the docks are safe enough to explore. Someone rents storage space to sailors. Someone else quietly moves packages from ship to container without paperwork occurring anywhere in between. **Living at Dock Cargo Community means measuring time less by the calendar than by whether the fleet is currently home.**`,
  },

  j4: {
    image: "flotsam",
    text: `Flotsam isn't an island, although after a few days aboard you may stop caring about the distinction. The Thelas drift town sits permanently anchored in Del Coronado Bay, built around three large vessels: **the Lund**, an old container ship; **the Rose**, a former submarine turned communications center; and **the Sakata Maru**, a transport ship serving as an administrative hub. Around them spreads a constantly changing settlement of smaller boats, kelongs, rafts, pontoons, jury-rigged floats, docks, and walkways. Vessels arrive. Vessels leave. Pathways change. Somebody moves their home twenty meters overnight because another boat needed the berth. **Flotsam doesn't have streets. It has suggestions.**

For the Thelas, this is more than an improvised settlement. It is one of the closest things their sea-going culture has to a permanent home. Elders retire here. Children grow up learning the customs of people who measure distance in nautical miles. Calypso and much of the Port's senior management operate from Flotsam, allowing the district to be governed from decks that still move beneath the tide. The place is simultaneously retirement village, fortress, harbor office, family home, communications center, and floating town square. Thelas Marines provide protection, though in practice everyone aboard understands that defending Flotsam is family business.

And then the **Randy Dandy** docks, and business becomes considerably more entertaining. The passenger ferry turned floating bar is one of the best places in the harbor to buy salvage before it reaches middlemen or learn which captain arrived carrying something interesting. Owner **Skipper** maintains a straightforward house rule: don't start trouble and there won't be trouble. Violators discover that several members of the crew are exceptionally skilled at relocating customers directly into the bay. **Come to Flotsam looking for the Port's official story and you'll find Calypso. Come looking for the unofficial one and start buying drinks.**`,
  },

  j5: {
    image: "medical-technologies",
    text: `Medical Technologies occupies a strange niche even by Night City standards: **they manufacture spare humanity.** The small waterfront facility specializes in growing artificial replacement limbs to order, maintaining the sort of body-bank technology capable of giving someone back meat instead of chrome after an accident, gunfight, industrial disaster, or particularly expensive bad decision. That specialty has kept the operation alive inside territory where less useful businesses have been pushed into the bay, because almost everyone eventually develops a philosophical appreciation for advanced medicine once they're missing something important.

But Medical Technologies also deals in cyberware, including equipment arriving from sources respectable clinics might describe as **extremely educational from a legal standpoint**. Local boostergangs have done business with the facility, and Medical Technologies is known for buying and selling questionable chrome. A cyberarm walks through one door attached to somebody. Another leaves through a different door in a padded crate. Nobody necessarily benefits from asking whether those events were related.

That's what makes the place so useful and so unsettling. Need a replacement limb grown? They can help. Need cyberware without the provenance checks associated with polite medicine? There may be a conversation available. Need to identify a distinctive implant stripped from somebody six weeks ago? Suddenly everyone becomes much less cooperative. **A body bank keeps records because medicine requires them. A grey-market cyberware operation survives because certain records occasionally vanish. Somewhere inside Medical Technologies, both filing systems occupy the same building.**`,
  },

  j6: {
    image: "rustys-dive-shack",
    text: `Rusty's Dive Shack is built from the **bridge of an old container submarine**, which means before anyone ordered the first drink the building had already experienced more interesting evenings than most bars manage in a decade. The place caters to dockworkers, sailors, Sea Nomads, pirates, salvage divers, and anyone else who considers solid ground an optional lifestyle choice. Everything smells faintly of salt, oil, wet neoprene, cigarettes, and machinery. The furniture looks capable of surviving being dropped from a ship. The customers look capable of surviving with it.

Rusty's isn't merely a drinking hole. It also functions as a **pawn shop and diving outfitter**, renting and preparing equipment while allowing salvagers to trade finds directly for useful goods without bothering with a middleman. That's important in a city sitting beside decades of wrecks, lost cargo, sunken infrastructure, dumped evidence, abandoned vessels, and assorted objects their previous owners would very much like returned. A diver can walk in wet, slap something corroded onto the counter, and start negotiating before they've even changed clothes.

Which makes Rusty's one of the Port's best information exchanges. Salvage crews know what they've seen underwater. Sailors know which ships arrived damaged. Nomads know what's moving offshore. Someone at the bar may have found a container nobody knew was missing. Another person knows why three divers never surfaced near a particular wreck. **Want to know what's happening on Night City's waterfront? Ask City Hall. Want to know what's happening underneath it? Buy a round at Rusty's.**`,
  },

  j7: {
    image: "south-night-city-reclaimed-studio",
    text: `South Night City Reclaimed Studio is proof that Night City housing can be both **surprisingly safe and objectively surrounded by terrible decisions**. The apartment building sits close to the waterfront and offers studios within convenient reach of boat transport. It is also near Medical Technologies, meaning the surrounding streets attract a steady population of gangers conducting business with the body bank and cyberware operation. Under ordinary Combat Zone logic, this should make the building an appalling place to live. Instead, the opposite happens.

Nobody wants to start a firefight that damages Medical Technologies. Too many gangs depend on what the clinic provides. The neighborhood immediately around the facility therefore enjoys an accidental peace created not by civic responsibility but by **mutually beneficial access to replacement limbs and questionable cyberware**. The farther you move from that small bubble, the uglier things become. Walking or driving through the surrounding streets is asking for trouble, and the nearby NCART station has earned an especially grim reputation. Residents who can afford the option often travel by boat instead.

The tenants live inside that strange equilibrium. Open your window and the waterfront is right there. Walk downstairs and three Tyger Claws may be leaning against a car waiting for somebody's new arm. Nobody bothers you because bothering you might attract attention to business everyone prefers conducted quietly. **The apartment doesn't have good security. It has something better: neighbors whose commercial interests require everyone nearby to behave themselves. Just don't follow them home from the clinic.**`,
  },

  reclamation_zone: {
    image: "reclamation-zone",
    text: `The Reclamation Zone wasn't conquered, purchased, or handed out as charity. **It was earned with a wrench.** The enclave began when the **Dorado Clan**, former Snake Nation Nomads with generations of experience keeping vehicles and rail systems alive, lost their old railroad contract and found themselves staring at a future of fighting other Nomad families over increasingly scarce work. Their elder, **Santos Dorado**, proposed something audacious instead. Night City's public transportation network was battered, unreliable, and desperately short of people who knew how to keep trains running. The Dorados knew trains. So Santos walked into Night Corp and made an offer: give his people land, and they would give Night City back its transit system. The City Council narrowly approved the deal. A slice of South Night City became the Reclamation Zone, and the Nomads became reclaimers.

That origin story explains nearly everything about the neighborhood. **Things here are expected to work.** Not beautifully. Not elegantly. Work. NCART trains and buses cycle through repair yards twenty-four hours a day. Old transit cars get stripped, rebuilt, or repurposed into housing. Workshops teach plumbing, cyberware repair, fabrication, driving, and railway maintenance because when the Zone lacks a skill, the local response is generally to teach someone how to do it. Scrap goes into piles until somebody discovers another use for it. Broken machinery is disassembled for parts instead of discarded. You see patched concrete, welded railings, old vehicle panels turned into walls, tools hanging beside front doors, and people stopping mid-conversation because they heard an engine make a noise they don't like. The rest of Night City calls it reclaiming. **The Dorados would probably call it Tuesday.**

The district's culture grew out of the same philosophy. Most residents belong to the extended Dorado Clan, although "clan" here means a network of families and adopted community rather than one enormous bloodline. Others are former NCART workers, mechanics, drivers, Techs, and people who saw what was being built and decided they wanted in. Roughly half of the Dorados come from a Muslim community with roots stretching back through Mexico, and the calls to prayer from the district's mobile mosque mingle with the rumble of the Skyline highway, the grinding of NCART repair work, and engines screaming around McGee Speedway. Children go to school in a reinforced former bomb shelter. Neighbors gather after shifts. People race cars for fun because apparently repairing transportation all day does not reduce the desire to operate it irresponsibly at night. **The Reclamation Zone isn't quiet enough to be idyllic. It's too busy building itself.**

Security follows the same community-first model. **Los Perros Guardianes** are a mostly volunteer militia, with most adults receiving enough training to serve as auxiliary members while a smaller professional core handles daily patrols alongside trained K-9 units. Their objective isn't to dominate the streets. It's to solve trouble before it becomes serious enough for the NCPD to decide intervention is necessary. Nobody here particularly wants that. The Zone also receives unwanted attention from the **Kill Krashers**, who periodically attack from the east, with suspicions lingering that South Night City City Manager Garven Haakensen has encouraged the trouble after losing this territory to the Dorados. Santos himself is now pushing eighty, and the district quietly understands that its founder cannot run it forever. People are already wondering who inherits the responsibility when the man who turned Nomads into citizens finally steps aside.

For an edgerunner, the Reclamation Zone is unusual because the first question people ask isn't **who do you know?** or **how much are you worth?** It's **what can you do?** Fix an engine. Guard a repair crew. Teach someone a skill. Find a missing shipment. Keep Kill Krashers away from a school. Recover components Night Corp claims it delivered. People here understand favors, but favors aren't abstract social currency. They're labor. Competence buys respect faster than chrome does. And that makes the Zone quietly radical by Night City standards. Downtown believes money can rebuild the city. Little China believes community can. The Old Combat Zone believes edgerunners can. **The Reclamation Zone looked at a broken train, picked up a toolbox, and decided to prove it.**`,
  },

  k1: {
    image: "herschels-crematorium",
    text: `Night City has countless businesses devoted to keeping people alive. **Herschel has dedicated his life to what happens when they fail.** His crematorium predates the Reclamation Zone itself, surviving from the days when this patch of land was still simply another piece of South Night City. Herschel is a Medtech, undertaker, family man, Buddhist, and apparently one of those rare human beings who encountered Night City's casual contempt for death and decided he would personally provide the counterargument. He and his family prepare the dead with care, honoring religious and cultural customs regardless of who the deceased was, how much money they possessed, or what people thought of them while they were breathing. Charity cases are accepted when families cannot afford the bill. **Herschel believes dignity isn't supposed to stop when the credchip does.**

That generosity requires financing, so Herschel accepts donations and has developed one of the stranger side businesses in Night City hospitality: **he rents sleeping space inside the funeral home.** Edgerunners down on their luck can sometimes earn a night's shelter by helping around the place, provided they're respectful toward the dead. Accommodations may be unconventional. Coffins, apparently, are more comfortable than they look. Herschel's wife and son work alongside him, and vegetarian meals are shared with guests who behave themselves. The whole arrangement should feel macabre. Somehow, it generally doesn't. Herschel treats death too sincerely for that. Bodies aren't decorations, props, or punchlines here. They're people who have reached the point where somebody else must speak for them.

That philosophy has attracted appropriate allies. Members of the **Tombstone Preservers**, a guardian gang devoted to protecting the sanctity of the dead, maintain a presence around the crematorium. They are bald, impeccably dressed Solos trained to respond very badly to grave robbers, corpse thieves, vandals, and anyone else who mistakes death for vulnerability. For an edgerunner, Herschel's can become sanctuary, morgue, meeting place, temporary home, or the beginning of a mystery. A body arrives carrying cyberware someone desperately wants back. A corpse officially belonging to one person turns out to be someone else. A client asks Herschel to delay a cremation until the crew can discover what killed their friend. **Night City is full of people making fortunes from death. Herschel just wants to make sure the dead leave with their names intact.**`,
  },

  old_combat_zone: {
    image: "old-combat-zone",
    text: `The Old Combat Zone began as an act of optimism. In the late 2010s, when corporate money was flooding into Night City and there never seemed to be enough land for the next factory, warehouse, or profit center, engineers began filling in part of San Morro Bay to create the **San Morro Industrial Zone**. New land rose from the water. Automated factories followed. The southeastern edge of the Island was supposed to become a monument to modern industry, a shining demonstration that Night City could manufacture its future almost as quickly as it could finance it. Then the Fourth Corporate War arrived before anybody finished building the dream. Construction stopped. Companies vanished. Infrastructure failed. Refugees moved into unfinished buildings. Gangs discovered acres of territory nobody was protecting. Within a few years, the district intended to showcase Night City's industrial power had become **the worst Combat Zone in the city.**

And the sickness spread. The Old Combat Zone became the infection point from which lawlessness pushed outward into Little China, Old Japantown, and South Night City. Streets that had been laid for freight traffic became gang borders. Robot-driven factories turned into fortresses, hideouts, and scavenging grounds. Entire blocks emptied except for people too dangerous, desperate, poor, or stubborn to leave. For years, outsiders talked about the OCZ as though it were a geographical death sentence. **You didn't live there. You survived there.** Psychos, boosters, scavvers, Iron Sights, and all manner of smaller crews filled the space left behind by the city. There were buildings nobody had entered in years because the people who tried didn't come back. There were intersections where stopping at a red light would have been considerably more dangerous than ignoring it.

Then something unusual happened. People started coming back **on purpose**. Some were born here. Some had spent careers as mercenaries and edgerunners elsewhere and returned with money, skills, weapons, and the dangerous idea that the neighborhood might belong to the people willing to rebuild it rather than whichever corporation eventually bought the land. The most visible of them became **Edgerunners Inc., led by Brick Coleman**, an OCZ native who left to become a mercenary and eventually returned with enough resources to begin dragging his childhood home toward civilization. By 2045, ERI provides much of the district's security, usually pairing experienced Solos with younger recruits who learn neighborhood policing from people whose previous definition of conflict resolution involved considerably larger ammunition. Brick acts as the Zone's unofficial City Manager. Nobody elected him in the conventional sense. **He came back, started fixing things, and enough people decided that counted.**

Not everyone considers that progress. The district is increasingly divided between ERI and **the Faded**, older residents who endured the worst decades and have very little interest in reconnecting with the city that abandoned them. To the Faded, integration means taxes, developers, landlords, cops, corporate buyers, and smiling people with zoning maps explaining why the block you've defended for twenty years would make an excellent mixed-use retail development. To younger residents, isolation means condemned infrastructure, unreliable power, gang violence, and watching every other district rebuild while the OCZ remains an urban cautionary tale. Add **Generation Red, the Iron Sights, and the Shroomers** to that political geography and reclamation becomes far more complicated than clearing rubble. The fight isn't merely over whether the Old Combat Zone survives. **It's over what survival is supposed to turn into.**

For an edgerunner, the OCZ may be the purest expression of the profession anywhere in Night City. Here, yesterday's mercenary can become tomorrow's neighborhood watch. A fortified factory can shelter the families of one of the city's nastiest gangs. A woman who once dreamed of running a prestigious clinic treats whoever comes through her doors whether they have five hundred eurobucks or five. Beneath the streets, a forgotten transit line has become an agricultural community. Every reclaimed building changes the map slightly. Every working streetlight pushes darkness back another ten meters. And every success raises the same uncomfortable question: **when the Old Combat Zone finally becomes valuable again, will Night City reward the people who rebuilt it, or simply arrive to collect?**`,
  },

  l1: {
    image: "from-the-ashes",
    text: `Phoenix Redwyne once intended to run a proper medical clinic. Clean floors. Modern equipment. Paying patients. Maybe even appointments. **The Fourth Corporate War had other ideas.** Phoenix had worked as a Trauma Team Medtech before the city came apart, and when it did she started treating whoever needed her, eventually establishing an improvised operation called **From the Embers**. The clinic migrated with the disaster: tents, temporary facilities, a stint operating alongside the Forlorn Hope during the brutal aftermath of the War, then a storage container, an abandoned storefront, and finally a converted multistory garage in the Old Combat Zone. Somewhere along the way, From the Embers became **From the Ashes**, because Night City does occasionally produce metaphors without requiring help from a marketing department.

Today, From the Ashes operates on a **sliding scale**, charging patients according to what they can actually afford. Community donations keep supplies moving, while Phoenix's extraordinary network of contacts fills the gaps money cannot. After more than two decades of patching up edgerunners, veterans, gangers, civilians, Fixers, Nomads, and anyone else who arrived bleeding, there are very few people of consequence in Night City who don't either know Phoenix or know somebody who owes her. That network may be the clinic's most valuable piece of equipment. When medication runs short, somebody finds some. When a generator dies, a Tech appears. When the wrong gang decides the clinic owes them something, Phoenix can start making calls.

The place itself carries the atmosphere of medicine practiced under permanent emergency conditions. Stretchers migrate wherever there is room. Volunteers scrub blood from concrete. Supplies are inventoried with religious intensity because the next shipment is never guaranteed. Nobody asks why you were shot before stopping the bleeding. **That conversation can happen after your blood pressure exists again.** For edgerunners, From the Ashes can be hospital, sanctuary, contact point, and reminder that reputation doesn't always come from the number of people you've killed. Phoenix built hers by making sure people didn't die. In the Old Combat Zone, that's considerably harder.`,
  },

  l2: {
    image: "jesse-james-kosher-deli",
    text: `Jesse James' Kosher Deli is neither particularly focused on deli food nor historically committed to being kosher. **The sign simply suffered an earthquake and everyone decided correcting it would require unnecessary effort.** Its ancestor was the infamous Jesse James' **Non-Kosher** Deli, an old Night City watering hole whose relationship with food was tenuous even before the Fourth Corporate War. The establishment eventually resurfaced in the Old Combat Zone, still functioning much more like a saloon than a restaurant. Then the 2033 earthquake knocked the word *Non* off the sign. Nobody put it back. Jesse James' Kosher Deli was born through structural damage and administrative laziness, which makes it one of the more authentically Night City naming stories imaginable.

These days the Deli has become inseparable from **Brick Coleman and Edgerunners Inc.** Brick owns the place and manages much of ERI's business from an office in the back, making the bar something between headquarters, recruiting office, neighborhood council chamber, mercenary watering hole, and saloon. Boosters and Nomads mingle with veteran Solos and young runners trying very hard not to look young. Jobs get discussed. Patrol assignments change hands. Somebody knows which block lost power. Somebody else knows why. The atmosphere can still get violent enough to preserve the establishment's old reputation, but there is a growing sense that the people drinking here are responsible for keeping part of the neighborhood alive tomorrow morning.

And yes, despite decades of jokes, **you really can get corned beef on rye**. It costs a small fortune because genuine ingredients require supply contacts well beyond the Combat Zone, and Brick reportedly has a source somewhere out in the Outskirts. The result is good enough that people travel into the worst district in Night City for a sandwich, which may be the greatest culinary endorsement possible. Order one, buy a drink, and listen. If the Afterlife is where Night City's legends gather, Jesse James' is increasingly where people decide whether the Old Combat Zone is going to have a future. **Also, someone may stab you over the mustard. Situational awareness remains important.**`,
  },

  l3: {
    image: "nc-ionic-semiconductor-building",
    text: `The NC Ionic Semiconductor Building used to manufacture the components of a technological future. Now **people live inside its corpse.** The old factory partially collapsed years ago, leaving behind a reinforced concrete shell enormous enough that residents began moving cargo containers into the ruins and converting them into homes. Container stacks occupy former production space. Walkways cross factory floors once intended for machinery. Old structural pillars become walls for bedrooms. Utility cables snake between steel boxes beneath ceilings still blackened by industrial grime. What the building lost in semiconductor production, it has gained in population density.

The community leader's approach to renovation is wonderfully Old Combat Zone: where chunks of exterior wall are missing, **barbed wire has been strung across the gaps**. Not insulation. Not concrete. Barbed wire. Safety is relative. What really matters are the factory's gigantic reinforced steel doors, which automatically seal every night from midnight until seven in the morning, turning the entire community into a fortress while the worst hours of the Combat Zone happen outside. Residents who miss curfew discover that architectural security systems are extraordinarily unsympathetic about excuses.

The strongest endorsement of that security comes from an unexpected source: **many Iron Sights hide their families here.** The gang is infamous for brutality elsewhere in the Zone, but even gangers have parents, partners, siblings, and children they don't want caught in the violence they help create. That gives the building a peculiar protected status. A resident might share a communal sink with the mother of a chrome-heavy killer who spent last night terrorizing someone three blocks away. People notice strangers. Everyone understands that attacking the community risks discovering exactly how many dangerous relatives its residents possess. **The NC Ionic Building may look like a ruined factory wrapped in wire. In the Old Combat Zone, that's practically a gated community.**`,
  },

  l4: {
    image: "the-underground",
    text: `Somewhere beneath the Old Combat Zone, below streets most people already consider the bottom of Night City, **there is another neighborhood entirely.** The Underground occupies forgotten subterranean infrastructure, including disconnected transit spaces far beneath the surface, and serves as the home of the **Shroomers**. There are no gleaming towers down here. No skyline. No advertisements. No weather. Just tunnels, old concrete, jury-rigged electricity, humid air, growing beds, pipes, lanterns, and an entire community that decided the safest response to Night City was to stop living on top of it.

The Shroomers began years ago as **Night City University students growing hallucinogenic mushrooms**. Then the Time of the Red made food considerably more valuable than recreation. They shifted toward edible fungi and discovered they were good at keeping people fed. After their food storehouse was burned in 2025, the group withdrew underground and built a village along a disconnected NCART track. Fungal agriculture flourished in the darkness. Mushrooms require little sunlight because they require none at all, making abandoned tunnels astonishingly useful farmland when the surface has become hostile. Today the Shroomers are part reclaimer collective, part survivalist culture, part agricultural community, producing food beneath one of Night City's least hospitable neighborhoods.

They aren't completely cut off. At eighteen, Shroomers are allowed to make a **pilgrimage topside**, experiencing the wider city and deciding whether to return. Some do. Some don't. Those journeys keep the Underground connected to contacts, trade, news, and the strange world above. Their mushrooms eventually reach customers elsewhere in Night City, including distribution through Mrs. Suzuki's Bodega in Old Japantown. But outsiders don't simply wander into the Underground because they heard the fungus is excellent. Finding the right entrance is one challenge. Being trusted after you find it is another. For an edgerunner, the tunnels invite all sorts of possibilities: someone disappears below and doesn't return; contamination threatens a crop; an old sealed section of NCART suddenly opens; excavation reveals something buried before the War. **Night City keeps trying to rebuild upward. The Shroomers looked beneath its feet and found an entire future nobody else wanted.**`,
  },
  norcal_military_base: {
    image: "norcal-military-base",
    text: `The NorCal Military Base is where Night City stops improvising. Beyond the fences, concrete barriers, checkpoints, armored patrols, radar arrays, hangars, docks, motor pools, and razor wire sits an entire society built around the assumption that **somebody, eventually, is going to attack it**. The base predates the Time of the Red, but the Fourth Corporate War transformed its purpose completely. When Night City's infrastructure collapsed and supply lines to the United States became increasingly unreliable, the soldiers stationed here faced a choice familiar to everyone in 2020s California: cling to the old world until the supplies ran out, or adapt. In 2027, the base formally reorganized as the **Estero Bay Military Combined Operations Group**, or COG, swearing allegiance to Northern California and the Pacifica Confederation. The uniforms remained. The chain of command remained. The flag above them changed.

Under **General Ash Giovanni**, the COG combines soldiers, sailors, air personnel, engineers, armored units, military intelligence, drone operators, and other surviving formations into something closer to a miniature national armed force than a conventional military installation. Military Police hold sole jurisdiction inside the perimeter, and once a visitor passes the gates, Night City's normal rules become largely irrelevant. The Uniform Code of Military Justice governs instead. Civilians require escorts. Drugs are tightly controlled. Restricted areas are actually restricted. Even people who merely live or work on base are generally required to enlist in the COG Reserve and maintain enough training to report for duty if called. Children grow up inside the system too, entering the **COG Training Corps** once they're old enough for school. Most Night City neighborhoods teach kids which gang controls the block. Here, they teach formations.

The base has become a strange little country inside the city. Personnel live according to rank in **the Oaks**, from crowded barracks for new enlisted recruits to apartments, officers' quarters, and detached homes for senior command. There are schools, recreation centers, medical facilities, a mess hall, parade grounds, shops, docks, airfields, a motor pool, and enough supporting infrastructure that a resident can spend weeks inside the perimeter without needing Night City for anything except remembering why the perimeter exists. Even the old carrier **NCS John F. Kennedy** remains here, trapped from normal Pacific operations by autonomous mines left over from the Fourth Corporate War and repurposed as a massive training platform. A warship that cannot safely sail has become a classroom for the next war. There may be no better symbol for the Time of the Red.

Then there is **Militech**. In the early 2030s, Giovanni struck a deal that tells you almost everything about post-War geopolitics. Militech received land inside the base, access to facilities, regional headquarters, and extraordinary commercial opportunities. The COG received discounted weapons, ammunition, supplies, training, and education. Militech's regional headquarters reportedly leases its land for the magnificent sum of **one eurobuck per year**. Officially, Militech employees remain separate from COG personnel and do not participate in military operations. Practically, thousands of soldiers now train with corporate assistance, shoot corporate ammunition, maintain corporate weapons, and walk past corporate employees on their way to breakfast. **There are occupations less intimate than that.**

And even that isn't the deepest loyalty problem. Hidden among the COG is the **Culper Ring**, a secret network of soldiers, sailors, and air personnel who believe Northern California's independence was a mistake and want it reunited with the United States, preferably under a considerably more militarized political order. Ring members have spent years funneling intelligence on NorCal and the Pacifica Confederation to U.S. operatives, allegedly with enough senior involvement that Military Police were slow to stop them. By 2045, Giovanni had finally ordered a serious effort to root them out. So the NorCal Military Base lives with three overlapping allegiances behind the same fence: the COG serves NorCal, Militech serves itself, and the Culper Ring serves a country the COG supposedly left behind. **For an edgerunner, the walls are the easy part. The hard part is discovering whose orders the person on the other side actually follows.**`,
  },

  m1: {
    image: "militech-corporate-operatives-housing",
    text: `Militech Corporate Operatives Housing is corporate accommodation designed by a company that apparently considers **incoming missile fire a reasonable residential planning assumption**. The reinforced conapt building houses roughly half of Militech's personnel assigned to the NorCal Military Base, particularly employees working at the nearby regional headquarters. The apartments themselves are spartan rather than luxurious. Furniture is limited, practical, and built from the sort of durable materials chosen because somebody at Militech probably asked whether a sofa really needs to survive fragmentation damage and received the answer *yes*. The entire structure is hardened enough that it is reportedly capable of surviving a missile strike. Home sweet hardened target.

The building has its own gate onto **Norton III Drive**, guarded by Militech personnel and separated physically from the rest of the military complex. Outside visitors can enter, assuming they're willing to endure a thorough security screening. Moving from corporate housing deeper into the COG base is another matter entirely, requiring passage through a Military Police checkpoint. That physical arrangement mirrors the politics perfectly. Militech lives **inside** the military base without quite being **of** the military base, a corporate island surrounded by another institution's guns. Employees can use non-critical base infrastructure and mingle with COG personnel, but everyone understands where one jurisdiction ends and another begins.

The third-floor **cigar lounge** is where the building becomes genuinely interesting. Militech higher-ups gather there to smoke, discuss military history, trade stories, argue about operations, and perform the ancient executive ritual of pretending important decisions aren't being made because nobody scheduled a meeting. For someone able to gain access, the lounge is a networking opportunity wrapped in smoke. A junior operative might meet a commander who changes their career. A Fixer might overhear which security contract Militech is about to bid on. An edgerunner might discover that somebody's deployment history doesn't match the story they've been telling. **The apartments are protected against missiles. The conversations upstairs are considerably more fragile.**`,
  },

  m2: {
    image: "militech-offices",
    text: `From the outside, Militech's Night City headquarters is almost disappointing. The structure on **Mary E. Walker Street** rises only seven stories in a severe modern corporate style, looking far too small to serve as the Pacifica regional headquarters of one of the most powerful military corporations on Earth. That's because most of the building isn't above ground. Beneath those seven floors descend roughly **twenty additional sublevels**, packed with conference facilities, cafeterias, recreation areas, infirmaries, firing ranges, technical laboratories, security suites, an auditorium, an AV garage, and a state-of-the-art war room. The visible building is effectively the cap on a corporate bunker. **Militech didn't build an office. It buried a fortress and put reception on top.**

Visitors are treated accordingly. Militech maintains its own external gate, allowing authorized civilians to reach the parking area and headquarters without passing freely through the rest of the COG base. People without sufficient clearance are escorted into an ancillary facility near the perimeter containing meeting rooms and a showroom where select customers can inspect Militech products. Anyone permitted into the headquarters itself remains under escort and only sees areas relevant to their business. When the meeting ends, so does the access. Deeper inside, security becomes draconian. Somewhere below ground are weapons programs, operational planning rooms, customer records, technical research, military contracts, personnel files, and exactly the sort of information governments employ intelligence agencies to acquire.

Despite the security, Militech occasionally creates one extraordinary vulnerability itself: the **Surplus Sale Night Market**. During these events, the corporate parking lot becomes a controlled marketplace where civilians can buy surplus equipment under the eyes of guards and rooftop snipers. Security remains formidable, but the unusual influx of outsiders forces procedures to loosen just enough that an ambitious crew might see opportunity. Sneak into the building. Extract an employee. Swap a shipment. Plant surveillance hardware. Steal something from a corporation whose inventory includes products designed specifically to prevent people from stealing things. **Most edgerunners spend their careers trying to avoid attracting Militech's attention. Breaking into its regional headquarters is what happens when someone decides a normal career no longer offers sufficient cardiovascular exercise.**`,
  },

  watson_development: {
    image: "watson-development",
    text: `Watson Development is what happens when corporations attempt to build a city district and the people living inside it develop opinions. **The Night City Co-Prosperity Sphere expected concrete, commerce, and compliance. It got Lucius Rhyne.** The NCCS, an alliance dominated by Japanese corporations, poured money into Northside with the familiar promise that development would improve life for everyone. New offices rose. Apartment blocks appeared. Security tightened. Streets acquired corporate landscaping, transit links, surveillance systems, and carefully designed public spaces where every bench seemed to have been focus-tested. Watson was supposed to demonstrate what postwar reconstruction looked like when competent corporations handled the work instead of politicians. For a while, the corporations even seemed to believe their own advertising.

The problem was the workforce. Someone had to pour the concrete, run the cables, unload the cargo, repair the machinery, clean the offices, serve the drinks, guard the doors, and live in the housing that corporate architects had thoughtfully designed for somebody else. Conditions deteriorated. Complaints accumulated. Then community organizer **Lucius Rhyne** began turning those complaints into organization. Rhyne was already known for the sort of speeches that cause executives to close doors and workers to open them. When he helped lead a district-wide labor strike, Watson stopped. Construction stalled. Deliveries backed up. Corporate schedules began bleeding money. NCPD Precinct #3 tried to restore order and discovered that rifles are considerably less useful against several thousand people who have simply decided not to go to work. Eventually the NCCS did something Night City corporations generally regard as an admission of catastrophic failure: **they allowed an election. Rhyne won.**

That victory did not magically transform Watson into a workers' paradise. It made the district more interesting. Corporate compounds still dominate entire blocks. Petrochem and SovOil stare at one another across the street with the warmth of two gunfighters who have been informed that dueling is prohibited during business hours. Trauma Team operates a medical fortress nearby. Corporate apartment complexes offer employees gyms, security, and amenities while HTown presses against the walls of a gated development whose residents would very much prefer poverty to occur somewhere less visible. On one block Watson looks like the beginning of Night City's recovery. On the next it looks like somebody painted fresh lane markings through a class war.

And after dark, everybody meets. Wage workers drink beside junior Execs at Sakura's. Soviet nostalgists descend underground to Red Oktober. At Smash/Cut, chrome and narcotics dissolve social distinctions beneath music loud enough to erase conversation entirely. At Redline, people settle questions of physical superiority with fewer metaphors. Neo-pagans celebrate the turning seasons at Vargtimmen while Trauma Team AVs scream overhead carrying someone wealthy enough to have emergency extraction written into their lifestyle. **Watson is still under construction, but its culture has already finished moving in.**

For an edgerunner, that makes the district extraordinarily dangerous in a very civilized way. Watson is not a Combat Zone. People have lawyers here. Contracts. Elections. Corporate security departments. Labor organizers. Rival intelligence operations. Police officers nursing political grudges. Homeless communities with long memories. Junior executives desperate to become senior executives. The bullets are usually hidden until somebody has exhausted the respectable alternatives. **Watson's central conflict is no longer about who gets to build the future. Rhyne's election settled that question badly enough to frighten everyone. Now the fight is over who gets to own it.**`,
  },

  n1: {
    image: "city-police-precinct-3",
    text: `Precinct #3 looks like a police station designed by people who believe the phrase *community policing* refers to the community being adequately contained. It is large, heavily armed, and staffed by veteran cops whose accumulated experience has apparently taught many of them the value of paranoia. Militech weaponry sits close at hand. Patrol vehicles leave through reinforced gates. Officers heading north into Watson do so with enough equipment to suggest that somewhere in the district an infantry war has been scheduled without informing the residents.

The precinct's defining trauma, however, wasn't a shootout. **It was losing an argument.** When Lucius Rhyne's labor strike paralyzed Watson, Precinct #3 could intimidate individuals, disperse crowds, arrest organizers, and show everybody exactly how much ammunition the municipal government had purchased. What it could not do was make an entire district go back to work. Rhyne emerged from the confrontation more popular than before and soon became City Manager. Some officers accepted the outcome. Others remember every thrown bottle, shouted insult, blocked intersection, and photograph of cops standing impotently in front of striking workers. Those grudges haven't gone anywhere.

For edgerunners, Precinct #3 is therefore more than somewhere to avoid after committing a felony. It is a pressure point in Watson's new political order. Rhyne needs the NCPD. The NCPD knows he needs them. Corporations want aggressive enforcement without another public-relations catastrophe. Residents remember what happened last time the police pushed too hard. A detained union organizer, a missing evidence file, a corporate complaint quietly bumped to the top of the queue, or a cop looking for people who can perform work that won't survive an internal-affairs audit can turn this fortress into the beginning of a very complicated evening.`,
  },

  n2: {
    image: "htown",
    text: `**HTown exists because somebody built a wall and poor people responded by moving directly beside it.** The settlement is a sprawling community of tents, tarps, improvised shelters, scavenged panels, cookfires, generators, water containers, and possessions arranged with the fragile permanence of people who have already rebuilt their lives more than once. On the opposite side of the wall sits a gated Future BuildWorks development selling Night City's version of suburban security. The contrast is obscene enough that nobody needs a political education to understand it. One side has guards and property values. The other has people the property values would improve by removing.

HTown has been removed before. Future BuildWorks acquired the land after the homeless population depressed local real-estate prices, and the NCPD was used to clear the settlement. Tents were bulldozed, possessions destroyed, and the area prepared for tract housing. **Then the homeless came back.** They rebuilt against the development's eastern wall, creating the urban equivalent of a scar that refuses cosmetic surgery. The name itself reaches backward into American political history, while another nickname, Potatoetown, survives as one of those jokes whose explanation is considerably less important than the fact that everybody keeps telling it.

Now every disagreement becomes potentially explosive. Residents inside the gates blame HTown for crime, noise, declining prices, and the uncomfortable sensation of seeing how the rest of Night City lives. HTown residents know perfectly well what happened the last time developers decided they were inconvenient. Community organizers move through the camp. Corporate representatives quietly discuss redevelopment. Cops patrol the perimeter. Gangers recruit among people with nothing to lose. In a district still celebrating a successful labor revolt, forcibly clearing HTown again could become the spark for something much larger. **The most dangerous thing in the camp isn't poverty. It's memory.**`,
  },

  n3: {
    image: "petrochem-sovoil-joint-housing",
    text: `The Petrochem & SovOil Joint Temporary Housing Solution may be the finest demonstration in Night City of the phrase **temporary arrangement becoming permanent through executive cowardice**. Both corporations lost employee housing and needed replacements quickly. Unfortunately, Petrochem and SovOil are bitter rivals whose relationship has historically involved resources, geopolitics, industrial espionage, proxy violence, and the sort of boardroom hostility that occasionally requires body armor. Somehow, somebody decided their employees should live together.

The resulting conapt building was constructed cheaply and divided almost symmetrically between the two corporate populations. Each side has its own apartments. Its own elevator. Its own tennis court. Employees mostly respect the invisible border because violating it would mean voluntarily interacting with SovOil people before breakfast. There is, magnificently, **one shared rooftop jacuzzi**, an amenity apparently installed by an architect who believed reconciliation could be achieved through warm water. Nobody wants to use it. The building itself isn't exactly a triumph of craftsmanship either. Canonically, the wall finish can come away when leaned against too enthusiastically, which tells you everything necessary about the meaning of *temporary*.

The place practically generates jobs by existing. Petrochem employees overhear SovOil conversations in elevators. SovOil children attend the same nearby facilities as Petrochem children. Someone swaps deliveries. Somebody's Agent connects to the wrong network. A romance across corporate lines becomes an intelligence concern. A drunken rooftop argument turns into a diplomatic incident involving swimwear. Both companies maintain security interests in the building, which means everyone is watched and nobody trusts the watchers. **There are safer places to steal corporate secrets. There may be no easier place to accidentally hear one.**`,
  },

  n4: {
    image: "petrochem-offices",
    text: `Petrochem's Night City headquarters believes very strongly in **controlled access**. Beyond the public-facing areas, the compound is hardened, watched, and defended with the seriousness appropriate to a corporation whose business involves energy, agriculture, chemicals, shipping, strategic resources, and enough geopolitical leverage to make national governments nervous. Employees pass through checkpoints. Security cameras track approaches. Visitors discover quickly that having an appointment and being permitted to wander are entirely different concepts.

And then there is the museum. Petrochem maintains a small public exhibit devoted to the history of petroleum, accompanied by a gift shop, because apparently somebody decided that the most approachable face of a global resource corporation was **educational hydrocarbon tourism**. Old drilling equipment, historical displays, carefully edited corporate timelines, and heroic descriptions of technological progress tell a story in which oil powered civilization and Petrochem merely had the good sense to inherit civilization afterward. School groups occasionally pass through. So do tourists, corporate families, curious locals, and edgerunners who have noticed that a public museum is technically located inside a heavily defended corporate headquarters.

Across the street sits SovOil. Employees can see the rival headquarters from the windows. Security teams can see each other's security teams. Every delivery truck entering either compound is presumably photographed by somebody in the other. The street between them may be one of Watson's most polite battlefields, full of surveillance, recruitment attempts, counterintelligence, defectors, and couriers carrying documents worth killing for. The public museum closes at the end of the day. **The real exhibition begins after everyone thinks the building is empty.**`,
  },

  n5: {
    image: "red-oktober",
    text: `Red Oktober occupies an abandoned subway station because nothing says intimate neighborhood dining quite like descending underground into a recreation of Cold War paranoia. The place was founded by a man called **Tank**, who inherited several storage units packed with Soviet propaganda, military kitsch, and memorabilia from his granduncle Ollie, a former Night City University political science professor. Tank combined the collection with inspiration from an old story about a rogue nuclear submarine and arrived at the only reasonable conclusion: open a restaurant.

The station has been dressed to resemble a Soviet bomb shelter. Propaganda posters cover the walls. Staff wear reproduction military uniforms and deploy Russian accents with wildly varying degrees of authenticity. The jukebox favors old Russian patriotic music. More importantly, Tank hired experienced kitchen staff from a Russian restaurant that had closed, which means the elaborate joke accidentally serves **some of the best Russian food in Night City**. A double of proper vodka costs enough that you remember drinking it. Cold War veterans sit beside Soviet immigrants, curious locals, political tourists, and posergangers for whom ideology is primarily a wardrobe category.

It is also exactly the kind of place where identities become ambiguous. Is the elderly man quietly drinking vodka a harmless émigré, former intelligence officer, or both? Is the loud revolutionary at the bar committed to Soviet ideology or merely very dedicated to the aesthetic? Did the SovOil middle manager choose this place because he likes the borscht, or because the booth at the far end can't be seen from the entrance? Red Oktober begins as a theme restaurant. **Stay until closing and sooner or later the Cold War starts feeling less historical.**`,
  },

  n6: {
    image: "redline",
    text: `Redline answers a question Night City has been asking for decades: **what if the bar fight was the business model?** The establishment is built around a fighting pit where augmented and unaugmented combatants beat one another senseless for a paying crowd. This isn't spontaneous violence. Redline considers spontaneous violence amateurish. The fights have spectators, rules, rankings, challengers, preparation rooms, and enough infrastructure to transform human aggression into an entertainment industry. The upper bar overlooks the arena, while patrons with more money can occupy private viewing rooms behind armored glass close enough to see precisely what a cyberfist does to somebody's dental plan.

The house fighters are the **Wild Things**, a gang whose culture has evolved around organized competitive violence. They favor weapons that are part of the body or extensions of it and reject firearms in the ring. Every Wild Thing dreams of climbing Redline's leaderboard. Their leader, **Jenny Nails**, owns the establishment and has cultivated enough of a reputation that even organizations considerably larger than her gang think carefully before causing trouble inside. The bouts are officially fought to knockout, and Redline maintains Trauma Team coverage because professionalism is apparently what separates bloodsport from poor venue management. Rumors persist about invitation-only deathmatches held under the new moon. Jenny Nails denies this. Night City has always respected a clear corporate communications policy.

For edgerunners, Redline can be arena, recruitment hall, gambling den, neutral ground, or test. Need a Wild Thing's respect? Get in the pit. Need to find someone who prides themselves on physical superiority? Look at the leaderboard. Need to disappear into a crowd that considers facial reconstruction an occupational hazard? Come on fight night. Just remember that drawing a gun inside Redline doesn't make you dangerous. **It announces that you've misunderstood the local religion.**`,
  },

  n7: {
    image: "sakuras",
    text: `Sakura's is the sort of place that becomes precious only after a city has destroyed enough ordinary things. Red paper lanterns mark the entrance. Inside, the atmosphere is deliberately informal, modeled after the Japanese **izakaya**, somewhere to drink beer or sake and eat small dishes while the day's frustrations slowly become tomorrow's problems. Sakura Yamamoto founded the place, and after her death the bar passed to her grandson, **Toru Evans**, who keeps the institution alive in a city where surviving long enough to become traditional is itself an accomplishment.

The menu has shrunk with the realities of the Time of the Red, but old favorites remain. Edamame appears when supply permits. Yakitori still comes off the grill, although accepting that the "chicken" is synthetic makes the experience smoother for everyone involved. Warm sake remains a staple. Sakura's clientele leans heavily Japanese-American rather than corporate Japanese; Arasaka expatriates traditionally preferred establishments with more polish, more exclusivity, and presumably fewer people capable of remembering what the company did before the War. That absence is part of Sakura's identity. **This is Japanese Night City, not a corporate imitation of Tokyo.**

Which makes it excellent territory for quieter stories. Local business gets discussed here. Relationships begin and end over skewers. Old-timers remember streets that no longer exist. Journalists listen. Organizers meet. A junior Exec can sit three stools from somebody who helped shut their corporation down during Rhyne's strike. Nobody needs to draw a weapon for the room to become dangerous. Sometimes all it takes is somebody recognizing somebody else.`,
  },

  n8: {
    image: "smash-cut",
    text: `Smash/Cut does not so much play music as **replace the atmosphere with it**. The EDM club is owned by the band URBIS, whose royalties help keep the place operating despite a business model seemingly designed to discourage profitable drinking. There is no alcohol. Patrons buy energy drinks and isotonic beverages instead, which is sensible because the clientele has generally arrived chemically prepared. Then the lights hit, the bass begins, and ordinary human communication becomes largely theoretical.

The immense dance floor dominates the club. Wraparound vidwalls, holoprojectors, mirrors, strobes, chrome, sweat, and bodies turn the interior into a sensory attack calibrated for people whose nervous systems may already contain aftermarket components. Conversation is so difficult that staff are trained in **American Sign Language**, wear hearing protection, and use smartglasses or cybereyes to conduct transactions without shouting themselves hoarse. People come to dance, get high, make eye contact, avoid names, disappear into private spaces with strangers, and return to the floor without acquiring unnecessary biography. Smash/Cut isn't interested in who you were outside. That's the point.

For an edgerunner, anonymity is both the attraction and the problem. A target can vanish into three hundred moving bodies. A hand signal might be a drink order, gang communication, flirtation, or the beginning of an extraction. Someone can slip a shard into your palm without speaking. Somebody can die twenty meters away and the crowd may keep dancing for several seconds before anyone realizes the movements are wrong. **At Smash/Cut, silence doesn't mean nothing is being said. It means you don't know the language yet.**`,
  },

  n9: {
    image: "sovoil-offices",
    text: `The SovOil Offices do not contain a public lobby in any meaningful sense of the phrase. **They contain a perimeter.** Gates, barriers, surveillance, guards, and institutional hostility separate the headquarters from Watson around it. Where Petrochem permits the public into a carefully curated museum, SovOil's main facility is essentially off-limits. What outsiders can see beyond the gates includes ostentatious gilded statues and monumental architecture, the kind of decorative excess that suggests somebody wanted the building to communicate national power before anyone reached reception.

SovOil reportedly maintains its own petroleum museum, although access and presentation differ from Petrochem's more visitor-friendly operation. The important exhibit sits outside anyway. **Petrochem is directly across the street.** Every morning, employees of two corporations with a long history of rivalry arrive within visual range of each other. SovOil security watches Petrochem. Petrochem security watches SovOil. Corporate intelligence specialists undoubtedly insist they are watching unrelated things in approximately the same direction.

There are places in Night City where breaking in requires defeating security. SovOil is the kind where breaking in requires first determining how many different security departments exist, which ones know about the others, and whether getting caught by one might actually be preferable to being noticed by another. A courier exiting the wrong gate, an employee considering defection, or a data package that absolutely cannot cross the street may be enough to put an edgerunner between two corporations whose arguments have historically been measured in barrels of oil and body counts.`,
  },

  n10: {
    image: "trauma-team-corporate-living-center",
    text: `Trauma Team understands that employees who spend their working hours flying into active gunfights to retrieve critically injured subscribers need somewhere peaceful to go afterward. Naturally, it built them somewhere **where the company can continue monitoring them.** The Corporate Living Center is attached to Trauma Team Tower by an enclosed access tunnel, allowing staff to move between home and work without experiencing the inconvenience of uncontrolled Night City. Inside are clean conapts, a high-end fitness center, emergency medical facilities, and smoothie machines occasionally loaded with actual fruit puree, a luxury that tells you more about the Time of the Red than any history book could.

Trauma Team also provides a therapist whom the company insists is confidential. Employees remain less certain. That suspicion is not helped by **doorknobs equipped with heart-rate sensors**, an architectural decision so aggressively corporate that residents have probably developed elevated blood pressure merely thinking about it. Is the system intended to detect medical emergencies? Track stress? Measure employee health? Identify who came home frightened after a mission? Probably one of those. Possibly all of them. Nobody downstairs in Human Resources seems eager to clarify.

The result is a peculiar residential community filled with pilots, Medtechs, security specialists, administrators, and emergency personnel carrying more trauma than many Combat Zone gangs. Someone here knows which Executive was extracted from which hotel. Somebody else knows which client was already dead when the AV arrived. Another employee hasn't slept properly since last Tuesday and keeps seeing the same face whenever the hallway lights flicker. **The Living Center protects Trauma Team employees from Night City. Whether it protects them from Trauma Team is another question.**`,
  },

  n11: {
    image: "trauma-team-tower",
    text: `Trauma Team Tower is a hospital designed by people who looked at the ambulance and concluded that its greatest weakness was **having to obey roads**. The Night City headquarters is a massive medical and aviation complex, rebuilt in Watson after Trauma Team's earlier facilities were lost during the chaos surrounding the Fourth Corporate War. AVs rise and descend from the upper levels. Air-traffic control manages the constant movement. Repair crews service armored aerodynes between missions. Somewhere inside, dispatchers are always counting minutes because somewhere outside, a subscriber is always running out of them.

The tower includes a hospital reserved for Trauma Team's **Executive-level clients**, which is where Night City's healthcare philosophy becomes architectural. Beyond secure doors lies advanced medicine for the people whose contracts justify it. Trauma teams operate directly from the building; Squad NC4-2, for example, has facilities on the fourth floor, including secure offices, an AV bay, armory, kitchenette, and showers. When the alarm comes, Medtechs and armed security pile into an AV and launch toward a place sensible people are currently fleeing. Minutes later the bay is empty except for ground crews preparing for whoever comes back.

For runners, Trauma Team Tower occupies a strange position between fortress and sanctuary. Getting inside without authorization is extraordinarily difficult. Getting inside while bleeding out may be easier, provided the correct account is paying. Its records could expose affairs, assassinations, overdoses, secret meetings, corporate illnesses, and clients retrieved from places they officially never visited. Its AV bays contain machines capable of crossing Night City faster than almost anything on the ground. **Everybody wants something from Trauma Team Tower eventually. Most people would prefer to arrive conscious.**`,
  },

  n12: {
    image: "vargtimmen",
    text: `Vargtimmen is a neo-pagan mead hall for Night Citizens who looked at the technological nightmare of 2045 and decided the answer involved **horns, fermented honey, and considerably older gods**. Owned by Freki, the establishment cultivates a deliberately heathen atmosphere: heavy wood, ritual imagery, firelight where regulations permit it, music that sounds better after the third drinking horn, and enough Nordic symbolism to keep three competing academic departments arguing about historical accuracy for decades. The mead is supposedly authentic. In Night City, *supposedly authentic* is about as strong a certification as anyone expects.

The real events are the seasonal celebrations. Solstices and equinoxes transform Vargtimmen from eccentric neighborhood bar into packed ritual spectacle. Neo-pagans, spiritual tourists, musicians, chromed Vikings, curious corpos, mercenaries, and people who simply heard the party gets wild crowd inside. Ancient symbolism collides cheerfully with cyberoptics and Agents. Someone raises a drinking horn beneath electric lights while an implanted neural interface quietly reminds them they have a meeting at eight. **Civilization may have collapsed, but apparently Yule survives.**

That mixture makes Vargtimmen fertile ground for stories. Some patrons take the faith seriously. Some treat it as aesthetic rebellion against corporate modernity. Some use the gatherings to exchange information beneath layers of ritual and performance. Old grudges are formally toasted, new alliances sworn, marriages proposed, fights started, and occasionally somebody claims an omen that sounds suspiciously like advance knowledge. In Night City, even prophecy deserves a background check.`,
  },

  n13: {
    image: "watson-central-cubelife",
    text: `There is nothing particularly wrong with Watson Central Cubelife. **That may be its most depressing feature.** It is a standard cube hotel in passable repair, situated in the heart of a district that keeps promising prosperity to everyone willing to wait long enough. Rows of tiny windowless living spaces provide exactly enough room for a bed, fold-out furniture, personal belongings, and the quiet suspicion that adulthood was supposed to contain another room. Shared facilities provide water, showers, and the occasional opportunity to discover how little etiquette survives when several dozen people leave for work at the same time.

Many residents are **low-level corporate employees**, the clerks, junior analysts, assistants, technicians, support staff, and ambitious nobodies holding up the lower floors of Watson's corporate economy. Most expect Cubelife to be temporary. One promotion and they'll rent a studio. Another raise and maybe a conapt. Another year and perhaps they'll get corporate housing. Everyone has a plan. Everyone knows somebody whose plan worked. Everyone also knows someone who has occupied the same cube for six years while continuing to describe it as *just until things stabilize*.

For an edgerunner, that makes Watson Central an extraordinarily useful ecosystem. Hundreds of people work inside corporations without being important enough to receive serious protection. They know schedules, passwords, rumors, office politics, delivery routes, executives' habits, and which manager has suddenly started closing their door during calls. They're lonely, ambitious, frightened of falling backward, and desperate to move forward. **Night City's great corporate secrets aren't always stolen from penthouses. Sometimes they walk home at six, heat kibble in a communal microwave, and sleep in a box.**`,
  },

  kabuki: {
    image: "kabuki",
    text: `Kabuki begins with a theater, which is appropriate because **almost everything important in the district has two faces**. There is the face presented to the street and the thing operating behind it. The security company is also a gang. The gang is also a community institution. The theater is also a museum. The museum is also a political landmark. The cultural elite overlap with corporate power, neighborhood leadership, and organized crime so completely that trying to separate them becomes an academic exercise best attempted somewhere outside stabbing distance. Officially, Kabuki is a small district within Watson Development. In practice, it is one of the places where the **Night City Co-Prosperity Sphere thinks**. The old saying has it exactly right: Watson may be the NCCS's arms and legs, but **Kabuki is its brain and heart.**

That role began in catastrophe. Before the Fourth Corporate War, the celebrated **Nakagawa Kabuki Troupe** performed at the Bodukkan Center in Japantown, one of the most prestigious performance venues on the West Coast. Then the nuclear destruction of central Night City turned Japantown into ruins and scattered the community that had grown around it. The troupe's star, **Shinobu Nakagawa**, became something much larger than an actor. He helped organize Japanese corporations including Segotari, Kendachi, and Kiroshi into the Night City Co-Prosperity Sphere, arranged the movement of survivors north into Watson, and helped reshape the remains of the old Tyger's Claw gang into protectors for the displaced Japanese community. Kabuki grew around the new theater almost literally as a community rebuilt around its cultural center.

Which explains why Kabuki doesn't feel quite corporate and doesn't feel quite municipal. Its City Manager, **Yoshiki Murakami**, was appointed by the NCCS rather than elected like Lucius Rhyne next door. Its contracted security comes from the **Kimen-Gumi**, the legal, public-facing arm of the Tyger Claws. The Kimen-Gumi wear vivid Oni masks, sign security contracts, sometimes cooperate with the NCPD, and can effectively deputize themselves as law enforcement in territories where their contracts apply. Beneath that respectable structure sits the rest of the Tyger Claws, who collect protection money, maintain legitimate fronts, take cuts from local commerce, and understand perfectly well that being indispensable to a neighborhood is considerably more profitable than merely terrorizing it. **Kabuki has police. They just happen to have gang tattoos under the uniforms.**

That arrangement produces a district where violence is present but rarely random. Streets around the theater are busy with restaurants, offices, shops, entertainers, security patrols, corporate employees, musicians, Fixers, gang members, and people whose exact occupation becomes less clear the longer they explain it. Meetings take place over food. Contracts are negotiated in private rooms. Introductions matter. Reputation matters more. Somebody in a Kimen-Gumi mask may politely help an old woman cross the street and later visit a shopkeeper who is two weeks behind on protection payments. A Tyger Claw lieutenant might spend the afternoon attending a corporate reception and the evening explaining territorial etiquette to someone against the hood of a car. **Kabuki doesn't hide the relationship between culture, business, and power. It simply makes the relationship look beautiful.**

For edgerunners, that beauty is dangerous precisely because Kabuki rarely tells you which rules you're breaking until you've broken them. You can walk into the district carrying a rifle and merely attract attention. Walk into the wrong karaoke room with the wrong person, embarrass an important guest, refuse the wrong courtesy, or discover that your employer's corporate problem is also somebody's family problem, and suddenly half the neighborhood becomes relevant. Jobs here tend to arrive wrapped in hospitality: retrieve something quietly, escort someone discreetly, investigate without insulting anyone, convince a person who cannot officially be threatened. **In Kabuki, the gunfight is usually the least interesting thing that can go wrong.**`,
  },

  o1: {
    image: "nakagawa-kabuki-theater",
    text: `The **Nakagawa Kabuki Theater is the most magnificent building in Northside**, and that isn't just civic boosterism. It was built to replace something irreplaceable. Before the War, the Nakagawa Kabuki Troupe performed at the legendary Bodukkan Center in Japantown, where they were regarded as one of the greatest Kabuki companies outside Japan and, according to some admirers, one of the greatest anywhere. Some performers were so committed to their roles that they underwent bodysculpting to resemble the demons, princes, and princesses they portrayed, remaining in character even away from the stage. When Japantown died in the aftermath of the 2023 disaster, Shinobu Nakagawa carried the troupe and much of the surrounding community north. The new theater became more than a replacement venue. **It became proof that the bomb had destroyed a neighborhood without successfully killing its culture.**

Inside, that cultural mission is impossible to miss. The theater houses the Nakagawa troupe and a museum preserving pieces of the community's history, making the building simultaneously performance hall, memorial, cultural institution, and monument to continuity. Audiences arrive beneath elaborate architecture to watch productions whose traditions are centuries older than Night City itself. Corporate guests sit beside wealthy patrons, local families, foreign visitors, and people whose interest in the evening extends somewhat beyond theater criticism. Backstage, makeup, costumes, prosthetics, bodysculpting, old techniques, new technology, and absolute theatrical discipline blur together until performers can appear less like actors portraying supernatural beings than supernatural beings temporarily willing to sign autographs. **Night City usually uses technology to manufacture the future. The Nakagawa uses it to make the past refuse to die.**

Then there are the offices. Because the same building that preserves Kabuki theater also houses the **central leadership of the Tyger Claws and the Kimen-Gumi**. Shinobu Nakagawa originally brought the remnants of the old gang into the community as protectors after Arasaka's withdrawal. By 2045 the arrangement has become institutionalized. The Kimen-Gumi operate legally and publicly while the deeper Tyger Claw organization pursues its own interests behind them. Following Shinobu's suspicious death in 2042, a bloody succession struggle eventually left his son **Hayato Nakagawa, "Shinobu the Second,"** at the top of the Tyger Claws. So somewhere beyond the public galleries, dressing rooms, rehearsal halls, and museum exhibits are offices where decisions can affect commerce, security, organized crime, and the Japanese community across Night City. For an edgerunner, that creates a marvelous problem: a job inside the Nakagawa might involve stealing an artifact, guarding an actor, infiltrating a gala, tracing an assassination, meeting a gang lieutenant, or discovering that all five are the same job. **At the Nakagawa, there is always another performance happening backstage.**`,
  },

  o2: {
    image: "yum-seng",
    text: `From the street, **Yum Seng looks like seafood has discovered advertising and become dangerously enthusiastic about it**. The storefront is a riot of light and color. Barkers in luminous clothing work the pavement, coaxing customers inside while a huge holotank above the entrance displays hyper-real tuna, salmon, shrimp, eel, and octopi swimming through the air at life size or larger. Similar displays continue indoors, all advertising something genuinely rare in 2045: seafood good enough that the imagery isn't entirely fraudulent. Owner **Alan Lam**, a Chinese-American gourmand of Cantonese heritage, built Yum Seng as a host and hostess bar but takes the kitchen seriously. Its seafood is among the freshest and best in Night City, its drinks are expensive and carefully chosen, and the beautiful hosts and hostesses are elegantly bodysculpted and trained in manners rather than merely hired for their faces.

Customers can eat in the communal dining room or choose a booth and receive more personal attention from the staff. But the soul of Yum Seng lies behind another set of doors: **soundproof karaoke boxes**, installed largely because Alan Lam loves karaoke. This becomes considerably more important if you intend to do business with him. Lam has built a modest empire in Night City's vice trade using an inheritance from his grandfather, but Yum Seng isn't simply another laundering operation. He likes the place. He likes the customers. He wanders between tables checking that people are enjoying themselves, sometimes comping a drink, and he has been known to expect mercenaries seeking business with him to join him for karaoke. Singing ability isn't the test. **Having the courage to be terrible in front of everybody is.** A Solo who can walk calmly through machine-gun fire may discover an entirely new definition of bravery when somebody hands them a microphone.

Which is why Yum Seng is close to perfect edgerunner territory. The karaoke rooms are soundproof. Important people like privacy. Alan knows Night City's vice economy. Hosts notice things without appearing to notice them. Expensive seafood attracts corporate money, criminal money, and people who have both. A meeting can happen over steamed fish without anyone at the next table hearing a word. A data shard can change hands during a chorus. Someone entering your supposedly private room halfway through the second verse can transform a negotiation into an ambush without disrupting dinner service outside. And because Lam genuinely cares about the establishment, damaging Yum Seng while conducting business there is an excellent way to turn a useful contact into a long-term problem. **Come for the seafood. Stay because the Fixer has locked the door and selected another song.**`,
  },

  new_westbrook: {
    image: "new-westbrook",
    text: `New Westbrook is what happened when the American Dream survived the apocalypse but **lost the deed to the house**. Before the Fourth Corporate War, this was Westbrook, an affluent suburban sprawl of detached homes, private yards, swimming pools, shopping centers, and people who had paid good money to put several kilometers between themselves and Night City's problems. Then the War came. Refugees poured north. Houses filled with multiple families. Garages became bedrooms. Warehouses became neighborhoods. Walk-in closets became apartments. Empty swimming pools were roofed over and turned into living spaces. Parking lots sprouted tents and cargo containers. For more than a generation, the old beaverville became an enormous refugee camp that simply kept developing until everyone stopped pretending it was temporary.

Now the corporations are coming back, which in Night City is frequently confused with recovery. **Network 54, WorldSat, and Rocklin Augmentics have planted themselves in the Westbrook Hills**, drawn by the high ground, communications potential, available land, and a local population desperate enough to accept opportunities more comfortable districts might examine too closely. Their towers and campuses glow above streets filled with cargo housing and low-rent cubes. Advertising screens are everywhere, burning through the night with celebrities, products, corporate news, braindance stars, new cyberware, and promises that happiness is available immediately provided somebody can establish credit. Some residents have good jobs, SINs, locking doors, and enough money to cosplay the old suburban lifestyle. Others officially do not exist at all. The DataKrash erased identities; children were born without new ones. **New Westbrook contains thousands of people Night City has somehow misplaced while they were standing directly in front of it.**

Even the district government has the polish of a media package. City Manager **Belkis Abera** is presented by Network 54 as a classic street-corner-to-corner-office success story, a tireless local advocate who rose from the community she now governs. Independent journalists have found the biography considerably easier to broadcast than to verify, and rumors persist that Abera was effectively installed by the corporate interests that dominate the hills. The NCPD still operates under emergency powers dating back to the refugee crisis, giving officers broad latitude to break up gatherings and keep the district "peaceful." Recent redevelopment has shown exactly what that can mean: when three homeless camps stood in the way of the planned Megabuilding H6, police cleared them. **Thirty-seven people died. Network 54 somehow missed the story.**

And then there is **The Combat Zone**. Not the real Combat Zone. That would apparently be insufficiently marketable. Network 54 has walled off a huge portion of northern New Westbrook and constructed an artificial urban wasteland inside, one of the largest permanent television sets in existence. Every six months, fifty contestants are selected, stripped down, sedated, implanted, and released into the set to hunt for equipment and kill one another while cameras record everything. On the second day, the producers activate the MIST, a contracting perimeter that tortures and eventually kills contestants who remain outside it. By day three, hiding becomes impossible. One survivor leaves with instant celebrity and **a year's worth of real chicken dinners**. The resulting footage is stretched into seventeen weeks of programming. Network 54's highest-rated show is therefore fifty people murdering one another for seventy-three dinners while families live in cargo containers outside the wall. The metaphor required absolutely no assistance.

That makes New Westbrook a magnificent district for edgerunners because **everything here is about controlling what people see**. Network 54 edits reality for broadcast. Rocklin turns desperate human beings into test platforms and calls it innovation. WorldSat controls the signals carrying information beyond the city. The NCPD keeps disorder out of the camera frame. Talent agents manufacture celebrities. Clubs manufacture nostalgia. Love hotels manufacture privacy. The Prime-Time Players literally reshape themselves around media obsessions, while the digital graffiti artist known as **Warhole** keeps hacking corporate screens to replace advertisements with rebellious messages. In New Westbrook, reputation can be worth more than truth, being seen can save a life, being unseen can save it twice, and the most dangerous question anyone can ask is deceptively simple: **who controls the story?**`,
  },

  p1: {
    image: "canalside-plaza",
    text: `Canalside Plaza is the sort of strip mall that would have been aggressively ordinary before civilization developed a crater problem. It hugs the Morro Canal on the southern edge of New Westbrook, a row of storefronts glowing beneath aging signage, patched roofing, security cameras, and enough foot traffic to keep the pavement permanently dirty. There is food, transport, beauty, groceries, legal advice, pawned weapons, hardware, and entertainment industry ambition all within a few hundred meters. **In other words, almost everything required to begin or end an edgerunning career.**

The most interesting tenant is **Sizzle Jams Talent Agency**, owned and operated by Sizzle Jams herself, a hungry young agent who trawls clubs searching for performers before somebody richer notices them. Her rising act is the **Digital Divas**, and she also operates the Boomtown stable, providing equipment and organization to livecasters and Garden Patch creators in return for a slice of their earnings. Nearby, Rick Shaw runs one of New Westbrook's most reliable pedicab services, occasionally climbing onto a bike himself despite being well past the age when common sense should permit it. Capitán Caliente serves cheap franchise food beneath its cheerful branding. The Mane Event fixes hair and nails. Oasis sells whatever passes for necessity this week. The Armory Pawn Shop ensures that if conversation fails, alternative negotiating tools remain nearby.

The result is a superb piece of Night City social infrastructure. A Rockerboy can leave the Mane Event looking like a million eurobucks, cross the parking lot, and discover Sizzle Jams thinks they're worth sixty. A runner can pawn a pistol, hire a lawyer, grab lunch, buy supplies, and catch a pedicab without moving the car. Young performers loiter outside hoping somebody important notices them. Corporate scouts pretend they aren't scouting. Garden creators manufacture spontaneous moments with three cameras already recording. **Canalside Plaza doesn't sell fame. It sells all the cheap little things people buy while chasing it.**`,
  },

  p2: {
    image: "chatelaines",
    text: `Night City has rebuilt whole neighborhoods out of concrete, cargo steel, and polymer. **Chatelaine's rebuilt one out of atmosphere.** The cabaret is deliberately styled after an early twentieth-century nightclub, with gilt frames pretending to be old brass, artificial wooden flooring distressed until it looks decades older than it is, scratched and hazed mirrors, period costumes, low light, torch songs, burlesque, and the glorious theatrical dishonesty required to make 2045 briefly resemble a century that never actually looked this good. The illusion is painstaking because the people coming here don't want historical accuracy. They want somewhere with a soul.

Chatelaine's has long been one of Night City's most important queer bars, and owner **Lulu deLuz** has earned considerable affection for reasons extending well beyond the stage. Lulu allows homeless queer kids to sleep in stockrooms while she works to find them emergency housing, and she donates heavily to queer causes around New Westbrook. Bartender **Aunt Kevin** is practically an institution in the local bar scene. Torch singer **Kirin**, a Korean-American performer who delivers aching ballads in a tuxedo, regularly draws a devoted crowd. The house signature drink, the Cocktease, combines peach schnapps, Cointreau, and crème de cassis for customers who would like tomorrow's headache served with excellent presentation.

Success has created its own problem. Chatelaine's became so fashionable that straight tourists started arriving in numbers large enough to alter the room. Some nights, queer regulars are effectively outnumbered by visitors eager to experience the famous queer club they've heard about. The **Street Queens** accuse Chatelaine's of becoming sanitized and commercial, boycott its Saturday Drag Nights, and increasingly favor Woody's instead. Lulu's defenders point to everything she still does for the community. Her critics argue that a space can remain charitable while losing the people it was built for. There's no easy villain in the argument, which makes it wonderfully Night City. **Chatelaine's survived marginalization. Now it has to survive becoming desirable.**`,
  },

  p3: {
    image: "dillys",
    text: `**Dilly the Pickle would like everyone to practice safe sex. Dilly is extremely difficult to ignore.** The mascot of Dilly's Pleasure Palace is an anthropomorphic cartoon pickle wearing a rolled-up condom as a beanie, reproduced on signage and animatronics throughout one of New Westbrook's most private love hotels. The character cheerfully reminds guests to use protection with the relentless enthusiasm of children's educational programming that has taken a very sharp turn somewhere during development. It is ridiculous. It is unforgettable. It is also remarkably good branding.

Behind the joke, Dilly's is an impressively serious privacy business. Guests book through an automated lobby vendit rather than a receptionist. Rooms are clean, comfortably furnished for two, equipped with proper bathrooms, soundproofed, and serviced only after occupants leave. Wall vendits provide overpriced food and drink along with instant STI testing, lingerie, lubricants, toys, and Dilly's merchandise that very few customers will admit owning the following morning. Groups can rent adjoining rooms and lower internal walls into the floor to create larger spaces. In a city where cameras, Agents, coworkers, corporate security, livecasters, and neighbors are constantly watching, **privacy may be the most luxurious feature in the building.**

Dilly's location a few blocks from Network 54 Plaza provides the clientele. Corporate employees come here. Minor celebrities come here. Media people come here. People meeting those people come here. Not every transaction is sexual. Soundproof rooms with automated entry and staff forbidden from interrupting occupants are also excellent places for confidential negotiations, talent contracts, blackmail payments, covert interviews, exchanges of stolen data, and meetings whose participants would prefer not to appear together on a security camera. **If the walls at Dilly's could talk, management would immediately demand a refund on the soundproofing.**`,
  },

  p4: {
    image: "evergreen-apartments",
    text: `The name **Evergreen Apartments** suggests trees, longevity, perhaps a tasteful courtyard. Locals call the place **Everwilt**, which demonstrates the continued superiority of community-based branding. The structure began as a warehouse-sized commercial building before slumlord **Sam Banks** sent armed muscle inside, removed the squatters already living there, and announced an exciting new affordable-housing opportunity. Cheap corrugated partitions went up. Rickety metal stairs followed. A former retail shell became an indoor settlement of improvised cubes where every square meter capable of holding a mattress became rentable real estate.

Conditions are appalling even by New Westbrook standards. Cooking and toilets are communal. Running water is absent. Bathing facilities are somebody else's problem. The toilets connect to the sewer in ways city inspectors would presumably describe with screaming. Interior walls are flimsy enough that residents who manage to rent several adjoining units can enlarge their homes with tin snips. Somewhere beneath all the grime is the faint architectural memory of a building that once sold products to suburban families who drove there, bought more things than they needed, and returned to houses with multiple bathrooms. **Now dozens of families live where the shelving used to be.**

Banks' most remarkable amenity is flexibility. For the right bribe, he will evict somebody already living there and give their cube to the higher-paying customer. That makes Evergreen extraordinarily useful to the sort of person who needs housing immediately and morally disastrous to anyone still burdened by empathy. It also means almost every door has a history. Somebody lived here yesterday. Somebody may come back tomorrow carrying friends and a shotgun. Entire families can disappear from the tenancy ledger because an edgerunner needed three connected rooms for a month. **At Evergreen, rent doesn't buy a home. It buys somebody else's turn.**`,
  },

  p5: {
    image: "network-54-offices",
    text: `Network 54 calls its New Westbrook headquarters the district's **economic anchor**, which is a lovely phrase because anchors are large pieces of metal specifically designed to prevent movement. The tower dominates the skyline, its enormous illuminated 54 and constantly shifting displays visible from far across Night City. Headlines crawl along the facade. Advertisements pulse through the night. Celebrities twenty stories tall smile down at people living in tents below. The building doesn't merely occupy New Westbrook. **It broadcasts ownership of the skyline.**

Inside is essentially a small city built to prevent important Network 54 employees from needing the one outside. There are offices, production facilities, soundstages, restaurants, a clinic, recreation and fitness facilities, and private housing reserved for stars and favored guests. Some shows film before live studio audiences, and carefully managed public areas allow tourists to enter, watch productions, attend premieres, and glimpse famous faces. Then the access stops. Lazarus provides heavy security, supplemented by personal protection for celebrities and senior Executives. The message is unmistakable: viewers are welcome to see **exactly what Network 54 has decided they should see.**

For an edgerunner, the tower is less an office building than a refinery where raw events become public reality. Footage enters and stories emerge. Careers are created upstairs and destroyed in editing bays downstairs. Somewhere inside are unbroadcast interviews, rejected stories, contestant footage from The Combat Zone, corporate communications, celebrity scandals, audience records, advertising contracts, and enough archived video to ruin half the city if edited in the correct order. A Media getting inside could expose history. A Netrunner could rewrite it. A Solo might simply be hired to make sure neither happens. **In Night City, people say the truth is out there. At Network 54, it's probably on a server marked DO NOT AIR.**`,
  },

  p6: {
    image: "network-54-westbrook-private-acres",
    text: `Network 54 Westbrook Private Acres offers something rare to its employees: **the ability to stop looking at Network 54 for several consecutive minutes.** The gated conapt development sits among the scenic Westbrook Hills, physically separated from the broadcasting tower and surrounded by enough walls and private security to create the illusion that New Westbrook's larger housing crisis is occurring in another city. Duplexes offer room, quiet, privacy, and actual residential separation, luxuries valuable enough that employees willingly commute rather than live closer to the studio. An armored Network 54 shuttle moves residents between the Acres and the Plaza.

Corporate HR attempts to cultivate community through organized social events, including the sort of pancake breakfasts that suggest somebody in Human Resources still believes mandatory-adjacent breakfast food can repair workplace culture. Attendance is predictably miserable. Residents would rather sleep, party, work from home, or work even harder in the hope that somebody important notices. Network 54 celebrities, despite having exclusive accommodations at the headquarters, occasionally discover compelling reasons to visit assistants or other staff living at the Acres when they need privacy from the constant machinery of fame.

That makes the development less peaceful than it appears. An assistant might be sleeping with a star. Another may be leaking material to a competitor. Producers bring scripts home. Editors bring footage. Employees burn out behind expensive locks while neighbors pretend not to notice who arrived in the armored shuttle at 02:13. Every duplex contains people close enough to power to know something and junior enough that nobody expects them to matter. **Private Acres is where Network 54's employees go to escape the cameras, which naturally makes it one of the most interesting places to point one.**`,
  },

  p7: {
    image: "night-city-firestation-1",
    text: `Fire Station #1 may be the most functional public institution in New Westbrook, which says as much about the firefighters as it does about everything else. Fire is a constant threat here. People cook in improvised shelters. Burn scavenged materials for heat. Run generators indoors. Splice electrical systems built from parts acquired from three different decades and at least one vehicle. Stack residences vertically inside buildings never designed for housing. **New Westbrook is perpetually one bad extension cord away from becoming a district-wide weather event.** Station #1 is why it hasn't.

The station is unusually well supplied, maintaining conventional fire engines alongside specialized **firefighting AVs** that can attack blazes from above or reach areas blocked by collapsed roads and dense construction. Its elite **Hellstriders** are something stranger still: firefighters operating Brimstone and Sheol full-body conversions built to enter chemical fires, industrial catastrophes, toxic spills, and infernos that would cook an ordinary human inside protective gear. One Hellstrider, Latisha "Lucky Sevens" Gunn, has become locally famous for taking chances that would be described as suicidal if she weren't so irritatingly successful at surviving them.

There is, naturally, a darker explanation for the generous funding. A fire beginning in New Westbrook does not respect zoning boundaries. Left uncontrolled, it can spread toward Kabuki, Charter Hill, Upper Marina, and property owned by people whose complaints receive return calls. The city may tolerate poverty. **It cannot tolerate poverty catching fire near valuable real estate.** Whatever the political motive, the firefighters themselves still go into the flames. For edgerunners, Station #1 is a place for disaster-response jobs, rescue operations, hazardous-material emergencies, missing responders, industrial sabotage, and the sobering realization that there are professions in Night City where people run toward danger without expecting to be paid in advance.`,
  },

  p8: {
    image: "north-cargo-village",
    text: `From a distance, North Cargo Village resembles a stack of shipping containers that has developed zoning rights through stubbornness. Up close, it becomes a neighborhood. Containers rise **five or six stories** above an abandoned parking lot, linked by welded stairs, improvised balconies, catwalks, cables, ladders, tarps, and additions whose load-bearing calculations were apparently conducted through optimism. Some boxes retain shipping company paint beneath murals and rust. Others have windows cut into their walls, insulation installed inside, solar panels bolted overhead, and doors reinforced until they could survive a small siege.

By the standards of New Westbrook's housing ecosystem, North Cargo Village is actually relatively desirable. Its apartments are in decent condition, and proximity to Kabuki, Upper Marina, Watson, WorldSat, Petrochem, SovOil, and even the NorCal Military Base puts so much serious security in the surrounding geography that predators must consider where a stray bullet might eventually land. Kimen-Gumi and NCPD patrols pay enough attention to prevent trouble from spilling outward. Within the Village, residents handle the remainder with a mixture of neighborhood watch and **aggressively cultivated ignorance about other people's business**.

At night, the blank sides of containers become enormous pirate cinema screens. Residents project stolen shows and movies across corrugated steel while families watch from catwalks and improvised balconies. That media culture has attracted the **Prime-Time Players**, who recruit obsessives willing to remodel their entire identities around beloved characters and programs. Somewhere in that audience is a kid memorizing every line of an old action show. Somewhere beside them is a ganger wondering whether they'd look better with the protagonist's face. **In most cities, television enters the home. In North Cargo Village, the home becomes the television.**`,
  },

  p9: {
    image: "rocklin-augmentics-campus",
    text: `The Rocklin Augmentics Campus looks like the future arriving early and **asking everyone to sign a waiver**. Shining new buildings line Grant Street, linked through enclosed skybridges and underground passages. Offices, meeting rooms, workshops, cafeterias, medical facilities, and administrative spaces surround a much larger research-and-development complex. Everything is polished, clean, controlled, and designed to communicate technical mastery. Employees move between buildings above the street while residents of New Westbrook live in improvised shelter below. Rocklin builds replacements for defective human bodies within sight of people the city has decided are administratively optional.

The only major public-facing portion is the **Hidalgo Gallery**, where prototypes from Rocklin's Signature Cybernetics Series are displayed like sculpture. These aren't merely medical devices. They're pieces custom-designed by notable artists, presented behind glass as beautiful objects before customers purchase them and receive installation from Rocklin-certified Medtechs. Elsewhere on campus, the distinction between patient, research subject, and raw material becomes substantially less elegant. Rocklin has been known to recruit impoverished New Westbrook residents by offering food and shelter in return for the use of their bodies as test platforms for experimental cyberware. The district produces desperation. Rocklin has found an innovative application for it.

The consequences are severe enough that **MAX-TAC maintains an on-site presence** alongside corporate security because cyberpsychosis incidents are not theoretical. That turns the campus into extraordinary edgerunner territory. A prototype disappears. A test subject escapes. A family wants someone extracted before the next surgery. A researcher has discovered what caused three subjects to die and would prefer not to become number four. A competitor wants Hidalgo Series schematics. An Executive wants proof the deaths are statistically insignificant. **Rocklin Augmentics sells humanity better bodies. What happens to the humans used during development is considered an internal matter.**`,
  },

  p10: {
    image: "rocklin-augmentics-innovation-hub",
    text: `The Innovation Hub is what happens when a corporation hears employees asking for work-life balance and responds by **putting the laboratory inside their apartment building**. Connected to the Rocklin campus by a long enclosed sky-tunnel with a moving walkway, the Hub provides corporate conapts filled with new appliances and convenient technology. Individual residences are modest, because Rocklin has dedicated enormous amounts of floor space to collaborative areas, computer labs, workshops, and maker spaces where employees can continue inventing long after ordinary workplaces would have had the decency to close. Engineers tend to adore it. Employees in accounting presumably wonder what happened to the living room.

Each floor provides equipment for personal experimentation and "off-hours creativity." Public areas are monitored around the clock for safety, which is certainly one reason cameras are watching the workshops. Another is that Rocklin's employment contracts make anything useful created there **company property**. A Tech who wakes at three in the morning with a breakthrough, wanders into the maker space, and solves a problem that has bothered them for ten years has just performed unpaid research for their employer. Rocklin considers this an inspirational corporate culture.

Naturally, side businesses have begun growing inside. Techs modify gear. Medtechs perform discreet work. Employees use corporate equipment for personal projects they absolutely intend to erase before anyone notices. Whether Rocklin knows is the interesting question. Corporate surveillance may have identified these operations months ago and decided they are more useful as experimental data than disciplinary cases. A clandestine workshop can therefore operate for years without knowing whether it has successfully evaded security or become **an unofficial research department with no budget**.`,
  },

  p11: {
    image: "worldsat-offices",
    text: `The WorldSat compound sits high on a ridge at New Westbrook's northeastern edge, because when your business is speaking to orbit, **geography becomes part of the antenna**. The elevation gives its communications arrays an unobstructed position over Night City and helps connect terrestrial infrastructure to satellites overhead. The same cliffs that once attracted recreational climbers now form a natural defensive barrier beneath one of the most sensitive communications facilities in the region. The old climbing routes still exist. These days, anyone using them is either extremely nostalgic or attempting something with a much higher prison sentence.

WorldSat isn't merely another corporate tenant. Its New Westbrook facility is **Night City's primary communications junction with the outside world**. Long-distance audiovisual communications, corporate traffic, satellite links, and information moving beyond the city's fractured local networks pass through systems here. WorldSat's broader communications empire handles enormous volumes of commercial, governmental, and military data, making interruptions potentially catastrophic and interception unimaginably valuable. Consequently, the site has its own defenses, Militech commandos, snipers, sensor systems, and NCPD AV response ready when something triggers an alarm.

The strangest thing is how automated much of the complex is. Past the guards, cliffs, sensors, Militech operators, and hardened infrastructure are systems doing their work with relatively little human attention. For a sufficiently skilled team, that makes WorldSat one of Night City's ultimate infiltration targets. Plug into the right equipment and information no longer stops at the city limits. A runner could contact someone overseas, intercept a corporate transmission, send data beyond local censorship, compromise a satellite connection, or discover exactly who has been listening to whom. **Network 54 controls what Night City sees. WorldSat controls whether Night City can speak to the rest of the planet. That is the kind of power people build cliffs, commandos, and sniper nests around.**`,
  },

  charter_hill: {
    image: "charter-hill",
    text: `Charter Hill is where Night City keeps the people who have **almost made it**. The streets are clean enough that garbage attracts complaints instead of scavengers. Militech patrols keep random violence admirably inconvenient. Apartments have real windows. Restaurants know what linen is. The residents possess expense accounts, corporate healthcare, respectable wardrobes, and enough money to consider poverty a subject suitable for documentaries. Yet on clear days the walls of the **Executive Zone** remain visible from the hills, looming above the district like the finish line of a race everyone here insists they aren't running. Charter Hill is affluent. Comfortable. Influential. And absolutely saturated with the awareness that somewhere nearby, somebody has more.

That ambition is built into the district's politics. Charter Hill's City Manager, **Symon Featherstonehaugh**, is elected by property owners, a wonderfully efficient arrangement that avoids confusing residency with political relevance. Militech provides security. The result is orderly without ever feeling public. Private guards stand beside polished entrances. Corporate cars glide through intersections where traffic cameras actually work. Building managers remember faces. Concierges remember employers. Every institution seems designed around the assumption that the people using it have something valuable enough to protect. **Charter Hill doesn't eliminate inequality. It upholsters it.**

And everyone is watching everyone else. At Bella Mia, clothes function as credentials. At Anjelika's, bodies become luxury objects, augmented until the distinction between flesh and product styling becomes intentionally difficult to locate. L'Ermitage fills and empties according to the travel schedules of visiting Executives, turning wealth into something transient and anonymous. Beneath all of it lies Seral Grove, where even death has premium tiers. Charter Hill's economy is built around a particularly corporate understanding of human existence: **appearance can be optimized, intimacy can be purchased, housing can be serviced, memory can be digitized, and mortality can be upgraded if the package is expensive enough.**

The gangs that operate here understand this ecosystem. Tyger Claws know that wealthy people still want vice. Prime-Time Players know that fashionable people are particularly vulnerable to obsession. Tombstone Preservers circulate around a district where the rich have begun turning remembrance itself into a luxury industry. Yet Charter Hill rarely feels openly gang-controlled because open control would be gauche. Influence travels through favors, club memberships, security contracts, introductions, and private rooms. The person threatening you may never raise their voice. **In poorer districts, power kicks down the door. In Charter Hill, it already has a keycard.**

For an edgerunner, Charter Hill is therefore an excellent place to discover that wealth doesn't reduce danger. It changes its etiquette. Jobs here involve disappearing scandals before promotion boards see them, retrieving stolen prototypes from lovers who should never have received them, protecting visiting Execs who cannot officially admit they're visiting, investigating deaths whose families can afford to make inconvenient questions disappear, or acquiring invitations to rooms where firearms are less useful than the correct shoes. People rarely hire runners here because they lack institutional power. **They hire runners because they need something done that institutional power cannot be seen doing.**`,
  },

  q1: {
    image: "anjelikas",
    text: `Anjelika's is where Charter Hill goes when ordinary human attractiveness has become insufficiently expensive. The host and hostess bar caters openly to clients with a **cyberware fetish**, and the staff have been sculpted accordingly. Hosts are required to undergo bodysculpting and commonly use EMP threading and chemskin to cultivate an intentionally artificial beauty: polished skin, luminous circuitry, geometric highlights, perfect proportions, and faces hovering somewhere between human being and extremely desirable consumer electronics. Some employees take the job precisely because it lets them save toward further modification. **At Anjelika's, the staff are simultaneously workers, performers, and works in progress.**

Clients disappear into private booths where music is loud enough to provide intimacy without necessarily providing privacy. Hosts drink, flatter, listen, flirt, and perform whatever version of synthetic perfection the customer has paid to experience. The signature drink, the **Coolant Flush**, combines Midori, peppermint schnapps, and seltzer with exactly the sort of name you'd expect from a club where somebody may compliment your spinal interface before asking your sign. The most popular host, Gavin, succeeds not because he looks the most artificial but because he's genuinely warm and sympathetic. Sunshine, meanwhile, cultivates the appearance of an empty-headed hostess while quietly moonlighting as a Netrunner. That combination should concern anyone who discusses confidential matters while assuming the pretty person across the table isn't listening.

Anjelika's is therefore built for complications. A visiting Exec develops an obsession with a host who has been quietly copying information from their Agent. A staff member disappears just before completing the cyberware modification they've spent years saving for. Somebody discovers one of the club's synthetic beauties has rather more combat chrome than the job description requires. Or perhaps the client isn't interested in sex at all and simply needs a booth where nobody will question why three heavily augmented strangers are meeting after midnight. **Anjelika's sells the fantasy that flesh can become machinery. Night City being Night City, the machinery occasionally has plans of its own.**`,
  },

  q2: {
    image: "bella-mia",
    text: `**Bella Mia has a dress code in the same way a firing squad has an ammunition policy.** The exclusive Charter Hill club was founded by ultra-model **Velvet Lux**, who uses it simultaneously as nightclub, social arena, public-relations machine, and testing ground for her Lux Lines fashion label. New designs appear here before official releases, worn by the right people beneath the right lights while photographers pretend the resulting attention happened organically. Bella Mia isn't where Night City's fashionable elite come to dance. Dancing is incidental. They come to **be observed successfully**.

Getting through the door is its own performance. Bella Mia's bouncers carry custom **Wardrobe & Style skill chips**, effectively turning fashion judgment into an augmented security function. In game terms, the standard is brutal: a Wardrobe & Style base below 14 isn't enough. Money alone cannot save you. Neither can reputation if you arrive dressed like somebody who assumes reputation makes clothes unnecessary. Inside, the room is filled with models, Rockerboys, senior corporate staff, designers, social predators, aspirational nobodies, and the occasional edgerunner who spent more on tonight's jacket than last month's ammunition. The club's signature Velvet Lush arrives beautifully presented because nothing here is permitted to exist without presentation. Detractors call the place **"Bulimia's,"** although the insult is somewhat unfair given Lux's public emphasis on healthy eating.

The real currency is attention. Who arrived with whom? Who received a table? Which Exec is wearing next season's Lux Lines before anyone else? Why did Velvet speak personally to that unknown woman near the bar? Why has a celebrity suddenly stopped appearing in photographs with their usual entourage? A Fixer who understands Bella Mia can learn more from seating arrangements than some Netrunners pull from databases. For players, that makes the club a wonderful inversion of the usual dungeon: **the guards aren't checking for weapons. They're checking whether you belong. And failing that roll happens before you ever reach the first room.**`,
  },

  q3: {
    image: "lermitage",
    text: `L'Ermitage is less an apartment building than **a place wealthy people borrow while temporarily inhabiting Night City**. Its elegant conapts are spacious, bright, carefully furnished, and equipped for residents accustomed to finding problems solved before they become aware of them. Most units are occupied only intermittently by high-level executives visiting from elsewhere in the Pacifica Confederation for extended assignments, negotiations, audits, restructuring efforts, or whatever other corporate process requires six months in Night City and a carefully worded explanation to the family back home. For much of the year, significant portions of the building sit almost eerily quiet.

The apartments can comfortably house four people in considerable style. Goods and services are available through the building's house video system, usually at prices designed for expense accounts rather than human beings. Food appears. Laundry disappears and returns clean. Cars can be arranged. Deliveries move through the concierge. Privacy is excellent. Security is serious. And because so many tenants are temporary, nobody thinks too hard about seeing unfamiliar faces in the hall. That last feature has made L'Ermitage useful as a **high-end safehouse** for anyone wealthy enough to pay the premium. An edgerunner can effectively rent anonymity here, provided they understand that damage comes out of the considerable sum placed against the apartment.

Which means the building is full of stories disguised as vacancies. A unit officially leased to a Biotechnica VP hasn't been entered by that VP in three months, but somebody orders dinner from it every night. A visiting Executive keeps a second apartment under another corporation's account. A lover, defector, witness, or asset is being hidden three floors above somebody paid to find them. One suite contains luggage belonging to someone whose employer insists never arrived in Night City at all. **L'Ermitage's greatest luxury isn't space. It's the ability to be somewhere without that location becoming part of your permanent life.**`,
  },

  q4: {
    image: "seral-grove",
    text: `Beneath Charter Hill, buried under one of Night City's most aggressively upward-looking communities, lies a place built entirely around looking backward. **Seral Grove began as art before the rich discovered it could be real estate.** In the aftermath of the Fourth Corporate War, wealthy Rockerboys created the subterranean installation as a memorial to people they had lost. Instead of trees, they built gleaming metallic forms. Instead of leaves, holography. Instead of a natural river, streams of data flowed through the environment. The result was cold, artificial, impossibly beautiful, a neon forest commemorating the dead without pretending nature had survived alongside them. Eventually Night City's elite began burying their own dead there, safe from scavengers and the desperate hands that had stripped less protected cemeteries. Burial begins around **10,000eb** and rises sharply from there. Even grief has an entry fee.

Every grave contains a locked server preserving photographs and video of the deceased. Visitors can call up holographic memories and watch someone laugh, speak, celebrate birthdays, tell old stories, or simply move again in three dimensions. The most expensive packages go farther, generating a reconstructed digital personality from archived recordings. These aren't true preserved minds and cannot sustain deep conversation, but they can answer simple questions and recount remembered stories using the deceased person's own voice. A widow can sit beneath an artificial metal tree and hear her husband tell the same anecdote he told every dinner guest for twenty years. A daughter can introduce her child to a grandfather who died before the child was born. **Night City has finally found a way to make mourning interactive.**

And heavily defended. Seral Grove is reached through a service tunnel near the Executive Zone and requires secured access. Large aerial drones patrol the interior. Electrical flooring and stun panels punish unauthorized visitors. The rich aren't merely protecting bodies. Valuable jewelry, cyberware, personal possessions, and data may be buried here as well, making every grave simultaneously memorial and potential treasure chest. In 2045, **Layla Deckard** rests here, and the mysterious Red Knight has used her grave as a refuge, conversing with her holographic reconstruction beneath the artificial trees. That single image captures Seral Grove perfectly: a living person hiding from Night City among expensive simulations of people who escaped it permanently. For edgerunners, the possibilities are irresistible. A grave server contains evidence somebody wants erased. A reconstruction remembers something the family didn't know. A body has vanished. A digital ghost begins saying something it wasn't programmed to say. **Above Charter Hill, everyone dreams of entering the Executive Zone. Beneath it, the people who made it there eventually arrive at the same destination as everybody else. They just get better lighting.**`,
  },

  exec_zone: {
    image: "exec-zone",
    text: `The **Executive Zone is the safest district in Night City**, which should immediately make any sensible person suspicious. Beyond its walls lie roughly twenty private estates scattered across manicured hills, ranging from vertical mansions to sprawling multi-building compounds large enough to qualify as neighborhoods elsewhere. Lawns are green. Trees stand where landscaping plans say trees should stand. Streets are clean enough that litter becomes an event. Some estates even maintain genuine grass, an extravagance in 2045 bordering on performance art, while others use Biotechnica's immaculate synthetic Realgrass and Realtrees to reproduce the suburban paradise the old world promised its richest citizens. **Outside the walls, Night City is rebuilding civilization. Inside, the Executive Zone has paid to pretend civilization never collapsed.**

You cannot simply rent here. Money helps, certainly, but residency is closer to membership in a private nation than signing a lease. Estates belong to Night City's highest corporate leaders, celebrities, industrialists, old-money survivors, and people whose friendships can accomplish what bank accounts cannot. The district's City Manager, **Doctor Karen Davies**, is elected by the homeowners' association, an electorate compact enough that democracy probably requires refreshments. Lazarus provides district security, and there are **no recognized gangs operating inside**. That absence isn't proof that organized coercion has disappeared. It merely means everyone capable of coercing people here has incorporated.

Security is layered everywhere. Lazarus patrols the streets while drones watch from above, automated turrets cover private property, decontamination systems protect compounds, and individual residents add whatever additional defensive technology their paranoia and portfolios can support. Even the records revealing exactly who owns what are among Night City's more closely guarded pieces of information. The Executive Zone is also connected to the rest of corporate Night City by a **private high-speed monorail system** whose access cannot simply be bought. Corporate authorization, identity credentials, and biometric verification determine who boards, and even the seating reflects rank. Ordinary high-level Executives ride comfortably. The people at the very top get something better. **Night City has managed to make public transportation hierarchical down to the upholstery.**

Life inside is engineered to minimize exposure to the city that makes it possible. Residents can play tennis or golf, use private clubs and spas, gamble, dine on fresh food, order luxury goods, and have purchases delivered directly to their estates by drone. Even the local Oasis is unlike those elsewhere in Night City, stocking premium brands and rarities such as **fresh-cut flowers**. Roses still arrive at front doors while, on the other side of the district walls, people live beneath tarps and scavenged roofing. Tent communities have historically crowded the land around the Zone, much to the irritation of residents whose expensive views occasionally include evidence of the economic system supporting them. It is difficult to construct a cleaner image of Night City than **a drone carrying fresh roses over a refugee camp toward a mansion.**

For an edgerunner, the Executive Zone is less a neighborhood than an **endgame dungeon wearing loafers**. Street violence is almost nonexistent because violence here has staff, contracts, surveillance feeds, armored response teams, lawyers, and contingencies. Breaking into an estate means defeating people wealthy enough to have considered the possibility of someone exactly like you months before you accepted the job. But the rewards are equally extreme. Behind those walls live the people who approve wars without firing weapons, erase careers with phone calls, hide prototypes in private labs, shelter fugitives whose names never reach the screamsheets, and possess data capable of collapsing corporations. The Zone's residents have climbed so far above Night City that they can barely hear it anymore. **That doesn't mean they're untouchable. It means touching them is going to be very, very expensive.**`,
  },

  heywood_docks: {
    image: "heywood-docks",
    text: `For twenty years, Night City learned an uncomfortable lesson: **when civilization breaks, the people who know how to move things become more important than the people who own them.** Nomad families crossed shattered highways, rebuilt supply routes, hauled cargo through territories where maps had stopped meaning anything, and kept goods moving while corporations were still figuring out which of their headquarters technically existed. At sea, the Thelas and other Nomad crews performed the same miracle. Food arrived. Medicine arrived. Machinery arrived. People survived. And now that international commerce is beginning to resemble commerce again, the corporations have reached the inevitable conclusion that the people who saved the supply chain are charging entirely too much for access to it.

The **Heywood Docks were created specifically to change that equation**. Corporate sponsors established the district around 2040, taking advantage of the newly completed Morro Canal and building a port designed to support corporate-controlled shipping independent of the Nomad nations. There is an important limitation: the canal and docks cannot accommodate the enormous vessels that once connected Night City directly to the global economy. Those ships still require deeper water and other facilities. But smaller freighters moving north and south along the West Coast can get through, which is enough to create the first serious corporate alternative to Nomad-controlled maritime logistics. **Heywood Docks isn't replacing the Nomads yet. It's proving that someday it might.**

That makes almost every container unloaded here political. Corporate shipping companies are returning. Warehouses fill with cargo. Cranes move across the waterfront. Rail lines and truck yards carry goods inland. Shipping firms establish offices beside construction companies preparing for expansion. **SK Security** provides district protection, and City Manager **Andrea Lee was appointed by SK**, which removes a great deal of tedious uncertainty about whose interests local government is expected to prioritize. The DeadWoods and the Skiv Family operate around the district as well, reminders that building a corporate port does not automatically transform the surrounding population into obedient infrastructure.

To the corporations, Heywood Docks represents recovery. To Nomads, it may look considerably more like **an eviction notice delivered twenty years late**. Every successful shipping route reduces corporate dependence on families who once held enormous bargaining power because nobody else could guarantee that a crate leaving Seattle would actually reach Night City. Every new warehouse means another piece of logistics moving back behind fences and contracts. Corporate security can protect a shipment, but it cannot manufacture generations of road knowledge, dock contacts, repair expertise, smuggling routes, favors, and relationships overnight. So for now the two systems overlap uneasily. Corporate vessels dock beside people who remember when corporate cargo only arrived because a Nomad agreed to carry it. Everybody smiles. Everybody invoices everybody else. Everybody knows the balance of power is changing.

For an edgerunner, that makes Heywood Docks less a neighborhood than **a frontier in an economic war**. Cargo disappears here. Manifests are altered. Containers arrive carrying things nobody declared. Nomads want intelligence on new routes. Corporations want sabotage blamed on Nomads. Security companies need deniable muscle. Shipping firms hire crews to recover stolen freight without admitting it was stolen. Union organizers disappear. Smugglers discover that a modernized port contains considerably more surveillance than the old one. Somewhere beneath all that steel, saltwater, diesel, and corporate optimism lies the question that will define Night City's next decade: **when the old world finally comes back, does it belong to the people who rebuilt the roads or the people who still own the paperwork?**`,
  },

  s1: {
    image: "greenbox-storage-units",
    text: `Greenbox Storage Units promises **secure, climate-controlled storage**, and by Night City standards it actually delivers. The facility is considered one of the better storage operations in the city, consisting of rows upon rows of individual cubes measuring roughly **two meters by two meters by two meters**. Pay the monthly fee, receive access, and Greenbox provides a clean little box where temperature, weather, and casual theft become somebody else's problem. Businesses use them for inventory. Nomads store equipment between runs. Techs fill them with parts. Fixers keep things they would prefer not to explain to landlords. In a city where an intact warehouse can be a strategic asset, reliable storage is surprisingly close to luxury.

The complication is that two meters by two meters by two meters is also, technically, **enough room for a human being**. Greenbox management insists the units are not residences. Some customers have responded to this policy by closing the doors and continuing to live there anyway. A mattress fits. So does a sleeping bag, an Agent, a battery lamp, several possessions, and approximately none of the dignity real-estate advertising usually includes in the floor plan. The only proper toilet and food facilities belong to the guard station, staffed by security personnel who are underpaid, bored, denied full-time status and benefits, and therefore magnificently ill-equipped to develop passionate opinions about what renters do after the doors close. Greenbox may prohibit residential occupancy. **Greenbox does not pay anybody enough to investigate snoring.**

That combination has given Greenbox an almost mythical reputation in Night City's crime culture. Cheap crime shows love the image of sinister Netrunners operating from storage cubes, surrounded by screens while detectives close in. Reality is usually less glamorous: people hiding from landlords, gangs, corporations, former partners, debt collectors, or all four at once. But the trope exists because the facility is genuinely useful for people who need **a small private space nobody asks many questions about**. A stolen weapon can sit three doors from somebody's entire household. A courier can rent a cube without realizing the adjacent unit contains the person they're supposed to find. A Netrunner really might be hiding inside one, irritated that television has made the cliché embarrassing. And somewhere in Greenbox there is almost certainly a unit whose rent has been paid automatically for fifteen years even though nobody remembers who rented it. **Storage facilities exist to hold things people aren't ready to throw away. In Night City, that category occasionally includes people.**`,
  },

  north_heywood: {
    image: "north-heywood",
    text: `North Heywood is the part of Heywood that still gets up in the morning and goes to work. **Not because Night City has become kinder, but because this district never had the luxury of waiting for it to.** Over the past decade, Heywood has split into two increasingly different worlds, and the northern half has become the home of clerks, laborers, maintenance techs, warehouse hands, service workers, line specialists, cyberware installers, couriers, mechanics, and families trying to hold together something recognizably ordinary in a city with very little respect for ordinary life. A great many of them work in the nearby **Heywood Industrial Zone**, which means North Heywood lives by shift changes, freight movement, factory schedules, and the uneasy rhythm of people whose rent depends on systems larger than themselves continuing to function one more week.

That gives the district a grounded quality rare in Night City. North Heywood does not gleam. It does not posture. It is not trying to look richer than it is. Apartment towers stand beside old motels converted into permanent housing. Cargo-container communities fill awkward spaces where development stalled or never arrived. Corner stores know their regulars. Local bars have more history than polish. The streets carry the smell of food carts, machine oil, old concrete, cheap synthcafe, and the faint chemical edge drifting over from the industrial corridor. **People here don't usually talk about reinventing themselves. They talk about making it to Friday.** And because this is Night City, making it to Friday is often a respectable ambition.

But North Heywood is not simple. **Dynalar** has planted one foot here with a regional campus and employee housing, bringing corporate money and cyberware professionals into a district still dominated by working people. **Biotechnica** quietly monitors experimental palms in a manicured little grove as though nature itself has become proprietary. **6th Street** operates openly out of a repurposed armory, making one of the district's most visible power centers a gang that still wraps itself in patriotism and neighborhood-defense mythology. The **Forlorn Hope** anchors a different kind of authority altogether, a place where veterans, edgerunners, and survivors gather under the watchful memory of too many dead friends. North Heywood is therefore held together by overlapping loyalties: to work, to neighborhood, to old service, to gang colors, to community, and occasionally to the dangerous idea that all of those might conflict.

What makes the district sing is that it still contains joy. There are people planting things in defiance of concrete. There are bio-sculpted strays and exotics finding treatment at a clinic that used to heal animals and now heals people trying to become them. There is roller derby at Xanadu, all speed, glitter, bruises, and fierce belonging. There are families packed into towers and motels and cubes, lovers sneaking out after late shifts, old vets drinking to the fallen, and kids in container neighborhoods projecting impossible futures onto rusted metal walls. **North Heywood is not glamorous, and that may be its greatest strength.** It is one of those rare districts where people are not merely surviving Night City. They are stubbornly, messily, imperfectly living in it.

For an edgerunner, that makes North Heywood extremely dangerous in a very human way. Jobs here tend to be personal before they become lucrative. A missing worker. A shipment tied to the wrong people. A gang trying to pressure a neighborhood. A corporation trying to buy silence. A former soldier who drank too much and said too much. A ripperdoc with a patient somebody wants retrieved. A community garden sabotaged because somebody nearby wants the land. **North Heywood does not generate as many elegant conspiracies as richer districts. It generates consequences.** And in Night City, consequences have a habit of hiring muscle.`,
  },

  t1: {
    image: "acorn-towers",
    text: `Acorn Towers is the kind of corporate housing that tells you exactly how a company sees its people: valuable enough to keep close, not important enough to treat luxuriously. The dual-tower complex houses **Dynalar employees**, which means it is filled with junior engineers, cyberware techs, electronics specialists, administrators, support staff, and ambitious corporate climbers whose careers are still young enough to fit inside a company apartment. The towers are respectable, clean, and functional, with enough amenities to make residents feel looked after and enough surveillance to remind them who is doing the looking after.

Inside, life is organized around work in that subtle corporate way that stops just short of admitting it owns your time. Neighbors work together, ride together, gossip about management together, and quietly compare promotions, assignments, and bonus rumors over vending-machine coffee. Doors close at night, but the building never quite stops feeling like an extension of the office. A resident can come home, ride an elevator with their project lead, pass three coworkers in the laundry room, and hear the same workplace argument resume in the hall the next morning. **Acorn Towers is where Dynalar employees go to leave work without ever fully escaping it.**

For players, that makes the place ideal for quiet corporate trouble. Somebody is stealing prototype components. Somebody else is moonlighting as a fixer. A tenant has gone missing after a "voluntary transfer." One resident is a sleeper asset for a competitor. Another is simply behind on rent and desperate enough to sell access they shouldn't have. In a district full of workers, Acorn Towers reminds you that corporate life is just factory life with better lighting and more passwords.`,
  },

  t2: {
    image: "the-armory",
    text: `The Armory used to belong to the **National Guard**. Now it belongs to **6th Street**, which is the sort of sentence that tells you everything necessary about both Night City and American decline. The old structure still carries the bones of its original purpose: thick walls, wide interior floors, hardened storage spaces, drill-ready open areas, and the institutional feel of a place built to issue weapons and organize force. 6th Street has turned it into headquarters, recruiting ground, political symbol, and neighborhood fortress all at once.

To their supporters, this is proof the gang stands for order, patriotism, local defense, and protecting ordinary people from Night City's endless parade of predators. To their critics, it is a heavily armed nostalgia cult wrapping extortion, vigilantism, and territorial power in the flag. Both readings contain enough truth to be uncomfortable. Members drill, drink, posture, clean guns, tell old war stories whether or not they were actually in the military, and speak the language of civic virtue while preparing for violence. **The Armory is where 6th Street turns grievance into identity and identity into jurisdiction.**

For an edgerunner, it is a pressure cooker. A job might involve infiltrating a rally, extracting someone being "protected," stealing stored weapons, learning which neighborhood committee is actually taking orders from gang leadership, or discovering that a patriotic fundraiser is really an arms pipeline with a barbecue attached. The building may look like a relic of old public service, but in Night City relics rarely stay neutral for long.`,
  },

  t3: {
    image: "biotechnica-palm-grove",
    text: `Biotechnica Palm Grove is one of those places that seems harmless until you remember who owns it. On the surface, it is simply a stand of **experimental palm trees**, neat and almost serene, a little patch of cultivated green in a district better known for labor, asphalt, and improvised housing. The trees sway. Sensors watch them. Maintenance crews visit. Security does not overreact unless given a reason. **It looks like landscaping. It feels like a laboratory.**

That is the unsettling part. In Night City, when Biotechnica plants something, it is never just a plant. The grove is monitored, studied, and maintained with corporate attention because these palms are assets before they are flora. Perhaps they are drought-resistant, pollutant-resistant, genetically tuned for carbon capture, salt tolerance, biofuel extraction, or some other product-friendly breakthrough. Perhaps they are merely ornamental proof that Biotechnica can make life flourish where nature had the decency to give up. Either way, the district gets a reminder that even shade can be proprietary.

For players, the Palm Grove is a marvelous small mystery. Why did Biotechnica really put it here? What is being tested beneath the obvious? Are the roots affecting nearby water? Has someone been stealing samples? Did a gardener see something they shouldn't have? It is exactly the kind of location where a simple assignment, grab a leaf sample and don't get caught, turns into corporate espionage, eco-sabotage, or evidence that the pretty little grove has claws underground.`,
  },

  t4: {
    image: "converted-motel-studio-apartments",
    text: `The Converted Motel Studio Apartments don't even bother pretending to have a proper name anymore. Whatever branding the place once had has worn off with the decades, leaving behind a low, tired roadside structure on the edge of the city that has been transformed from temporary lodging into permanent life. The old motel bones remain visible everywhere: exterior-facing doors, narrow parking access, thin walls, awkward plumbing, and rooms designed for overnight guests now serving as homes for people who may stay for years. **North Heywood specializes in turning the provisional into the permanent. This place is practically a district monument.**

The studios are small, cheap by local standards, and occupied by the people who need cheap more than they need dignity: industrial workers, gig laborers, recent arrivals, divorced parents, older residents on fixed income, burnouts, and people between better options for so long that "between" has become a lifestyle. Residents know which units are quiet, which ones cook good food, which tenant can fix appliances, and which door to avoid after midnight. In a city obsessed with reinvention, the motel apartments are refreshingly honest. Nobody here is living a fantasy.

That honesty makes them playable. A room gets rented in cash to someone using the wrong name. A tenant vanishes and management is in no hurry to ask questions. Someone in Unit 12 is clearly running a side business. A battered resident begs the crew to keep a violent ex away. A corpo slumming it under an alias is spotted by exactly the wrong person. Places like this hold stories because they hold people the city has stopped inventorying.`,
  },

  t5: {
    image: "dynalar-campus",
    text: `The Dynalar Campus is North Heywood's cleanest expression of upward mobility. **Dynalar** is one of the more recognizable names in cyberware and consumer electronics, and its regional headquarters brings a distinctly corporate layer to a district otherwise built around shift work and practical survival. The campus includes offices, meeting spaces, and the sort of polished research and clinical environment designed to reassure investors, employees, and patients that technology is both the future and under control. Glass, steel, bright interiors, access badges, and quiet competence define the space.

Yet unlike some more insulated corporate compounds in Night City, Dynalar does not float completely above the district around it. Its workers live nearby. Its products pass through local hands. Its service and medical functions intersect with a population already steeped in chrome culture because this is Night City and cyberware is not luxury here so much as infrastructure. That creates a fascinating blur between corporate image and neighborhood reality. Dynalar wants to be the friendly, reliable face of augmentation. North Heywood knows that even "friendly" corporations still count profit first. **The campus is where cyberware gets presented as progress instead of need, aspiration instead of desperation.**

For players, it offers all the right tensions: prototype theft, patient data, corporate recruitment, black-bag retention of researchers, suspicious hardware failures, or a whistleblower who has learned that a "minor defect" is killing people. Dynalar is respectable enough to make its secrets valuable and human enough to make those secrets leaky.`,
  },

  t6: {
    image: "forlorn-hope-bar",
    text: `The **Forlorn Hope** is not merely a bar. It is one of those rare Night City institutions that has survived long enough to become almost mythic, a veterans' and edgerunners' refuge where history clings to the walls whether management wants it to or not. After the events of *Tales of the RED: Hope Reborn*, the Hope stands renewed but unchanged in spirit: still a place for mercs, soldiers, burned-out heroes, unlucky survivors, and people who have seen enough violence to prefer drinking among others who won't ask for simplifications. **If the Afterlife is where legends become visible, the Forlorn Hope is where the scar tissue goes to sit down.**

The clientele gives the place its gravity. Veterans swap stories with bartenders who have heard them before. Old grudges get aired, old comrades get toasted, and new crews learn quickly that disrespecting the room is a poor survival strategy. There is a sort of weary honor here, not clean enough to become romantic, but real enough to matter. A favor earned at the Hope may count more than a corporate contract because it was given by somebody who knows what promises cost. The drinks help. So does the understanding that everyone in the room has probably buried someone.

For edgerunners, the Hope is pure gold: a source of jobs, contacts, rumors, histories, retired solos, half-forgotten ops, and morally complicated requests that start with "I swore I'd never get involved again, but..." A missing veteran, a haunted old cache, a reunion gone wrong, or a dead teammate's unfinished business all fit here naturally. The Hope doesn't just offer missions. It offers weight.`,
  },

  t7: {
    image: "nana-meows-nursery",
    text: `Nana Meow's Nursery is not itself a guerrilla garden. That would be too obvious. Instead, it supplies the people who turn abandoned planters, traffic medians, vacant lots, cracked courtyards, and forgotten edges of North Heywood into living acts of defiance. Seeds, tools, soil enhancers, planters, lamps, nutrient packs, irrigation fixes, advice, and probably a few things not strictly intended for legal horticultural use all pass through this wonderfully subversive little shop. **In a city that monetizes every square meter, growing something where it wasn't invited is almost political theology.**

Nana Meow herself, or at least the persona and culture around the shop, gives the place its warmth. Customers include community gardeners, aging idealists, local kids, eco-radicals, retirees, people trying to grow food, and residents simply tired of living in a world made entirely of concrete and menu screens. The shop doesn't need to wave a banner to make its values clear. It believes neighborhoods should bloom. It believes ordinary people should know how to coax life out of bad conditions. In Night City, that is nearly a revolutionary position.

For players, the hooks are excellent. Somebody is poisoning community plots. A Biotechnica rep wants to buy out a local growing network. A guerrilla garden has sprouted on valuable land and suddenly the gardeners need protection. A rare seed strain has gone missing. Or perhaps Nana Meow is more connected than she appears, quietly coordinating a district-wide green insurgency with trowels instead of rifles. Not every rebellion needs muzzle flash. Some come in packets.`,
  },

  t8: {
    image: "night-city-animal-shelter",
    text: `The Night City Animal Shelter is one of the more charming lies in North Heywood, because it is **no longer an animal shelter and not really a veterinary clinic either**. The former vet facility is now occupied by a ripperdoc who specializes in **Exotics and Bioexotics**, which means it caters to the wonderfully Night City intersection between body modification, species fantasy, identity expression, and medical necessity. If a patient wants claws, muzzles, tails, fur patterns, feline optics, scaled dermal effects, or more extensive bio-sculpted transformation, this is the sort of place they end up.

The building's old purpose lingers in the atmosphere. Treatment rooms once meant for animals now host people becoming something adjacent to them. Kennels and exam areas have been repurposed into surgical spaces, recovery rooms, and storage. The clientele ranges from committed Exotics living full-time transformed identities to performers, posers, fetishists, and those whose desired self no longer sits neatly inside the word *human*. There is tenderness in that work as well as risk. In a city happy to commodify the body, a clinic like this can become one of the few places where radical self-expression is treated as care rather than pathology. **The chrome may be strange, but the need to be seen is very ordinary.**

That makes it fertile ground for jobs. A patient is being hunted by someone who refuses to recognize their new identity. A procedure has gone catastrophically wrong. A rare bioware component must be obtained fast. A gang wants protection money from the wrong kind of clientele. Or a client undergoing an exotic conversion has ties nobody mentioned until armed professionals start arriving. It's a location with both heart and teeth.`,
  },

  t9: {
    image: "woodland-park",
    text: `Woodland Park is the kind of neighborhood that reveals North Heywood's real personality better than any corporate brochure could. It sits near the Dynalar campus, but its identity is resolutely local: part modest neighborhood, part survival network, part little ecosystem of ordinary people making do beside larger powers. Highlights include the **Burning Bright Bodega**, the mom-and-pop drug store **Breeze**, the **Palms** cargo-container community, the **Shark** apartment building, and the **Zolletta** cube hotel. None of these would qualify as a landmark in wealthier districts. Here, together, they form a whole life.

The bodega is where people hear things first. Breeze is where they try to solve health problems before those problems require hospitals or debt. The Palms container community shows the district's talent for turning hard edges into homes. The Shark houses people who managed to get one rung higher than the cubes. The Zolletta reminds everyone how thin that distance can be. Woodland Park isn't glamorous, but it has density in the best narrative sense: everyone is close enough for problems to spread and kindness to do the same. **This is where neighborhood becomes infrastructure.**

For players, Woodland Park works beautifully as a recurring home base or job cluster. Somebody at the bodega needs help. A kid at the Palms has gone missing. Breeze is being pressured by suppliers. The Shark has a tenant nobody can explain. The Zolletta is hiding someone in plain sight. It is the kind of place where low-stakes jobs suddenly become high-stakes because you start recognizing the faces involved.`,
  },

  t10: {
    image: "xanadu",
    text: `Xanadu is what happens when North Heywood decides that if the world insists on being ugly, **people may as well lace up skates and make the ugliness work for it**. The venue is part roller derby rink, part disco tech, part neighborhood spectacle, and fully committed to the proposition that speed, music, bruises, glitter, and attitude can still qualify as culture. By day, or at least by quieter hours, it is a sporting venue. By night, it becomes a feverish blend of competition and nightlife, with lights, music, collisions, sweat, and bodies moving in deliberate defiance of restraint.

It is also home to **the Muses**, a gang with deep roots in performance, image, and feminine-coded ferocity. That gives Xanadu a distinct energy. This is not a sterile sports arena. It is a place where identity and aggression become choreography. Rivalries matter. Aesthetic matters. The crowd matters. The line between athlete, performer, ganger, and local hero can get very thin very quickly. People come to watch the action, flirt recklessly, support their favorites, place bets, and bask in the kind of collective energy Night City so rarely allows without monetizing into extinction. **Xanadu turns impact into applause.**

For an edgerunner, it is a superb venue for social jobs, gang diplomacy, betting scams, sabotage, recruitment, or public spectacle gone wrong. A star skater gets threatened. A fixer's meet is arranged during derby night. A Muses dispute spills into the crowd. Someone needs to get in, get out, and not wipe out in front of half the district. In a city obsessed with lethal violence, Xanadu offers a reminder that nonlethal violence can still be art.`,
  },

  heywood_industrial_zone: {
    image: "heywood-industrial-zone",
    text: `The **Heywood Industrial Zone is where Night City gets made**. Not imagined. Not financed. Not advertised beneath immaculate lighting by a model with gold-plated cheekbones. Made. Steel arrives here and leaves as infrastructure. Chemicals become plastics. Cyberware components emerge by the pallet. Pharmaceuticals fill sealed crates. Construction machines trundle between warehouses carrying pieces of the city that will eventually become somebody else's skyline. The district sprawls across factories, loading yards, workshops, cranes, storage depots, construction sites, and docks where dead cargo ships sit stranded among newer machinery like fossils from an economic age that almost went extinct. At any given hour, something is being welded, lifted, milled, stamped, assembled, demolished, rebuilt, or loaded onto something larger. **If Night City has a heartbeat, the Industrial Zone is the sound the heart makes when nobody has bothered to install a muffler.**

The district only became official in **2035**, when the City Council separated it from greater Heywood, finally acknowledging that the industrial sprawl had developed enough economic gravity to require its own administration. Its City Manager, **Theodore Walker**, originally came here hoping to establish an office-supply factory. The factory failed. Walker somehow became City Manager instead, suggesting that Night City's political career path remains one of the city's least regulated forms of vertical mobility. The NCPD provides security, and working a successful corporate protection detail here is reputedly a useful audition for beat cops hoping to graduate into better-paid private security. With Militech, Petrochem, SovOil, Rocklin Augmentics, Trauma Team, Raven Microcybernetics, Continental Brands, Ziggurat, Zhirafa, and other corporations operating facilities across the district, there are plenty of auditions available.

The remarkable thing is that the corporations have not started another war. **Yet.** The Industrial Zone concentrates an almost comedic number of competing interests inside one geography: rival manufacturers, resource companies, construction firms, logistics providers, cyberware producers, security contractors, Nomad traders, independent Techs, and criminal organizations all working within truck-driving distance of one another. Everybody spies. Everybody hires away everybody else's workers. Deliveries get photographed. Prototype specifications migrate between companies in ways management insists are coincidental. But large-scale peace remains profitable, so the district exists in a strange industrial détente. Nobody wants to fire the first shot because somebody might answer with an acquisition, a strike team, or a missile.

People live here too, because Night City has never encountered land unsuitable for housing once the rent gets high enough elsewhere. Cargo-container communities accommodate assembly workers, freelance Techs, short-term contractors, and artists attracted to industrial spaces that would be considered dangerously uninhabitable by anyone with less aesthetic conviction. The **Old Ironworks Building** has apartments inside a dead factory and more homes stacked across its roof. The corpse of the **Rambling Rose** has become an entire community. Nearby, Zhirafa has taken that improvised container aesthetic, recreated it as corporate housing, and thoughtfully inserted comfortable conapts behind the fake container doors. **The Industrial Zone may be the only place in Night City where poverty becomes an architectural trend before the people who invented it have been priced out.**

For edgerunners, the Heywood Industrial Zone is almost unfairly useful. There are warehouses nobody watches closely enough, factories everybody watches too closely, cargo manifests worth fortunes, experimental hardware traveling between buildings, desperate workers who know which loading bay is never checked, executives who need sabotage disguised as mechanical failure, and entire abandoned industrial sites where gunfire barely qualifies as unusual noise. A chase can move from factory floor to crane yard to container stack to derelict ship without ever encountering something designed for pedestrians. **This is where Night City keeps its raw materials, its machinery, and many of its secrets. The difference between them is mostly whether somebody has put a barcode on the box.**`,
  },

  u1: {
    image: "dv-rambling-rose",
    text: `The **D.V. Rambling Rose is a ship that stopped being a ship without receiving permission from the ocean**. The hundred-meter cargo feeder entered a Heywood drydock for maintenance in the early 2020s, then the Fourth Corporate War interrupted the work with its usual enthusiasm for permanently changing schedules. The vessel was abandoned after the 2023 disaster and never returned to the water. Time, rust, and several decades of improvised construction did the rest. Today the Rambling Rose is classified as a **Dead Vessel**, permanently embedded in a drylock that residents eventually filled and stabilized around it. Its engines no longer carry cargo between ports. The ship itself has become the port.

Squatters transformed the wreck into a vertical neighborhood. Empty shipping containers were stacked into apartment blocks across and around the old vessel, connected by ladders, metal stairs, open-air walkways, and railings welded together from reclaimed rebar. Bright automotive enamel protects much of the exposed metal from the salt air, giving the community splashes of almost cheerful color against acres of corrosion. There is stored water, a small garden, battery power, functioning cargo equipment, forklifts, lifter exoskeletons, and enough repaired infrastructure that the place feels less abandoned than repurposed. A NET Architecture links surveillance and other systems throughout the Rose. **Somebody looked at a stranded freighter and saw a ruin. Somebody else looked at it and started measuring for curtains.**

The Rose is now the headquarters of **Fixie's Couriers**, a courier collective organized around the legendary Fixie and her network of bicycle riders. From an old command center aboard the vessel, shipments and messages can be distributed across Night City through riders who do not depend on roads remaining open, fuel being available, or corporate delivery systems agreeing to serve the neighborhood. The distinction between gang, courier service, commune, and mutual-aid network becomes wonderfully blurry. Fixie's people have even fielded the **Industrial Zone Skidz**, a roller derby team composed from her cycling network. For runners, the Rose can offer deliveries, information, refuge, smuggling contacts, stolen cargo, or the simple problem of discovering that a package everybody wants is somewhere inside several hundred tons of dead ship inhabited by people who know every hatch. **The Rambling Rose will never sail again. Somehow, it still moves half the city.**`,
  },

  u2: {
    image: "old-ironworks-building",
    text: `The Old Ironworks Building represents the purest Night City solution to two simultaneous problems: **an abandoned factory and nowhere to live**. Instead of solving either problem properly, landlords converted the old industrial interior into small apartments and then kept going, stacking cargo containers across the roof to create additional housing. The result is a building with one community embedded inside the skeleton of heavy industry and another perched above it in painted steel boxes. Old beams, industrial windows, pipes, gantries, and machinery scars remain visible beneath whatever residential improvements could be installed cheaply enough to preserve the investment opportunity.

The rooftop community is particularly striking. Containers crowd together above the factory like a brightly colored second building assembled from children's blocks by someone unconcerned with gravity. Residents paint them, modify them, insulate them, cut windows into them, and connect utilities with the peculiar confidence that comes from having already survived worse electrical decisions. Techs are common here, and many residents provide **parts and contract labor to nearby Zhirafa**. That relationship has become unusually close for a corporation and an improvised housing community. Workers cross between them. Skills cross between them. Spare components presumably cross between them in ways neither accounting department fully understands.

The influence even runs in the other direction. Zhirafa's nearby MicroVillage was deliberately designed to mimic the colorful container housing at the Ironworks, turning the aesthetic of improvised working-class shelter into a corporate residential concept. The people on the roof live in actual boxes because housing is scarce. Zhirafa employees live in comfortable apartments **disguised** as boxes because somebody thought it looked authentic. There are entire dissertations hiding in that relationship, but edgerunners may be more interested in the practical opportunities: freelance Techs, unregistered fabrication work, stolen parts, workers with access badges, corporate recruiters, and an entire rooftop maze where someone can disappear between containers. **Night City eventually copies everything that survives it. Sometimes it even calls the copy innovation.**`,
  },

  u3: {
    image: "yangs-wheels",
    text: `Before **Yang's Wheels**, cheap personal transportation in Night City was less an industry than a scavenger hunt. Then salvage worker **Gabriel Yang** came across boxes of parts recovered from an old skate shop and decided, more or less on impulse, to buy the lot. Reconstructing anything useful from those remains took years. The DataKrash had helped erase much of the information surrounding the old designs, and Yang's early work only truly came together after he partnered with engineer **Edith Lamarr**. Their breakthrough was beautifully unglamorous: a bicycle that could be manufactured cheaply, work reliably, and survive Night City's streets. **No neural interface. No targeting optics. No subscription. Two wheels and the radical promise that both of them keep turning.**

The company grew from an abandoned Santo Domingo garage into a Rancho Coronado warehouse and finally into the Industrial Zone facility that now combines **headquarters, manufacturing plant, and warehouse**. Yang's product family has expanded to bicycles, inline skates, skateboards, rickshaws, and other inexpensive wheeled transportation. The company's slogan, *The Street finds a way*, fits because their customers do too. A Yang bike might carry a courier through traffic a car cannot penetrate. Skates turn dead infrastructure into transit. Rickshaws become local businesses. In the Time of the Red, mobility does not have to be technologically sophisticated to be transformative. Sometimes the smartest transportation system is the one that doesn't require CHOOH2, functioning traffic networks, or permission from an operating system.

The factory therefore has unusual strategic value despite producing products that seem almost quaint beside AVs and cyberbikes. A labor dispute here could disrupt thousands of couriers. A prototype public-transit project could reshape street travel across Night City. A shipment of bearings or frames might matter more to a neighborhood than a crate of expensive cyberware. Fixie's people are obvious customers, as are Nomads, delivery crews, kids, commuters, and anyone who would rather trust their legs than a corporate fuel supply. For runners, Yang's offers industrial espionage with an unusually charming target: somebody might genuinely hire heavily armed mercenaries to steal **the world's most important bicycle prototype**. In Night City, that sentence is considerably less ridiculous than it first appears.`,
  },

  u4: {
    image: "zhirafa-office-park",
    text: `Zhirafa's Night City headquarters looks less like somebody built an office complex and more like **a factory evolved upward**. The corporation took an existing industrial park and constructed new floors directly over older architecture rather than flattening everything and beginning again. The interiors received the full corporate rebirth treatment: cafeterias, collaborative spaces, architectural flourishes, innovation nooks, offices, and, wonderfully, at least **one laser-tag arena**. Outside, the older industrial bones remain visible beneath the newer additions. It is a fitting headquarters for a company whose business revolves around machines designed to lift, build, haul, and reshape the physical world.

And those machines are everywhere. **Drones and mechanical animals patrol the campus**, functioning as both workforce and security. Zhirafa produces machines such as its GRAF construction drones and Savannah series animal-inspired systems, so a visitor can encounter technology performing manual labor one moment and watching them very carefully the next. Heavy equipment shifts cargo. Smaller drones inspect infrastructure. Robotic forms stalk between buildings with the eerie confidence of creatures that know exactly where they are permitted to go. Humans work among them, but the corporate campus makes Zhirafa's philosophy unmistakable: if a repetitive, dangerous, heavy, or inconvenient task can be mechanized, eventually it will be.

That creates a delicious infiltration problem. Traditional corporate security can be bribed, distracted, threatened, or fooled. A cargo drone does not care that your forged badge cost five hundred eurobucks if the transponder behind it is wrong. A mechanical patrol animal does not get bored at three in the morning. On the other hand, machines can be spoofed, hacked, redirected, sabotaged, or convinced that a group of armed intruders belongs in Shipping Bay Four because Shipping Bay Four has suddenly become the designated intruder-storage area. Somewhere inside the Office Park are engineering plans, control software, prototypes, and corporate secrets belonging to a company helping physically rebuild Night City. **Zhirafa makes machines that move the world. A good Netrunner only needs to persuade one of them to move it in the wrong direction.**`,
  },

  u5: {
    image: "zhirafa-office-park-microvillage",
    text: `The Zhirafa Office Park MicroVillage is corporate housing wearing **working-class cosplay**. From the outside, the development resembles the colorful cargo-container community at the nearby Old Ironworks Building: brightly painted metal, industrial styling, container doors, and the carefully curated appearance of people making something beautiful out of whatever materials they could find. Except the Zhirafa residents aren't living inside cargo containers. Open those paint-splattered doors and you find **well-appointed corporate conapts**, comfortable and furnished, with all the amenities an actual shipping box tends to omit. Zhirafa saw its neighbors' improvised housing and apparently thought, *excellent aesthetic*.

The imitation is not entirely cynical. Zhirafa employees have historically had a good relationship with the Tech-heavy community at the Ironworks, and the MicroVillage reflects that connection. Vendors gather outside selling food and drinks at unusually generous prices for corporate housing. The luxury goods can be startlingly cheap, especially alcohol. **Vodka can cost less than bottled water**, an economic arrangement that ensures evenings occasionally develop more enthusiasm than planning. Residents work hard and, once shifts end, can drink hard enough to provide tomorrow's machinery with new cautionary examples about human inefficiency.

For edgerunners, the MicroVillage is almost perfect social infiltration territory. It sits close to the headquarters, houses people with legitimate access to Zhirafa systems, and encourages exactly the sort of informal after-hours mixing that security departments pretend training seminars can eliminate. Engineers complain over cheap cocktails. Techs from the Ironworks visit friends. Someone brings home a component they intended to inspect off the clock. Somebody else mentions tomorrow's prototype test after their fourth vodka. A corporate operative could spend weeks trying to breach Zhirafa's drones and encrypted systems. **A competent Fixer might simply buy an engineer another round and ask how work is going.**`,
  },

  santo_domingo: {
    image: "santo-domingo",
    text: `Nobody officially renamed South Heywood. **The people living there did, which is considerably harder to reverse.** Over the 2030s, the southeastern edge of Night City became a natural gathering point for Nomads moving into and out of the metropolis. Caravans stopped beneath the Petrochem dam. Families lingered. Trade followed. Repair crews, merchants, drivers, guides, smugglers, scouts, and people who had spent years crossing the broken roads of America began turning temporary camps into something resembling permanent civic infrastructure. Eventually *South Heywood* sounded less like a neighborhood and more like something written on an old municipal map. Locals increasingly called it **Santo Domingo**, and by 2045 the name had stuck firmly enough that the city might as well learn to live with it.

For years, the **Aldecaldos** were the gravitational center of that new Santo Domingo. Their huge enclave beneath the Coronado Dam became one of Night City's most important gateways to the Badlands, a place where Nomads could find food, repairs, shelter, trade, medical care, work, news, and people who understood exactly how dangerous the road outside could become. Their Peacekeepers still provide security across the district, patrolling on roadbikes and maintaining enough authority that their headquarters is considered a meaningful counterpart to the local NCPD precinct. The Aldecaldos are not merely another faction operating here. **For a long time, they were part transportation network, part police force, part economic engine, and part unwritten government.**

Then **Theresa Valentino won an election**. She ran as an independent with a brutally effective message: Santo Domingo should belong to everyone living there, not simply the Nomads who had accumulated power during the city's weakest years. Behind that populist campaign stood the **El Norte Cartel**, which financed Valentino and helped defeat the Aldecaldo-backed candidate. The result is one of Night City's stranger political arrangements. Valentino holds the City Manager's office. El Norte's influence is spreading. Yet the Aldecaldo Peacekeepers still hold the district security contract. The people who lost the political contest are therefore still carrying the handcuffs. **Santo Domingo has changed governments without entirely changing who controls the streets.**

And the balance is changing faster than anyone expected. El Norte was supposed to use Theresa. Instead, some cartel members appear increasingly loyal to **her** rather than to their superiors in Mexico, enough that locals have begun calling them **Valentino's Fists**. Even stranger, Valentino has developed a surprisingly functional relationship with former Aldecaldo political rival Genesis Durcal, leaving Nomads wondering exactly what was promised behind closed doors. The cartel sees new smuggling routes and territorial opportunity. Theresa sees something larger: perhaps an independent political power base with herself at its center. The Aldecaldos see a district they helped build slowly learning that dependence works both ways. **Everybody in Santo Domingo still smiles at one another. The smiles have simply become more expensive.**

For an edgerunner, Santo Domingo is therefore a district where almost every job intersects with **loyalty**. Who vouched for you at the Aldecaldo Camp? Whose cousin owns the garage? Does the Peacekeeper pulling you over know the Fixer who hired you? Is the crate you're transporting Aldecaldo cargo, cartel cargo, or something Theresa's people don't want either faction to know about? A boring delivery can become a political statement merely because of which road you took. Beneath the dam, under the freeway, inside container settlements and beer tents, Santo Domingo is deciding what comes after Nomad dominance. **The dangerous part isn't that nobody knows who controls the district. It's that several people can make a convincing argument that they do.**`,
  },

  v1: {
    image: "aldecaldo-camp",
    text: `The Aldecaldo Camp sits beneath the **Coronado Dam** like somebody parked an entire civilization there and forgot to keep driving. Vehicles, tents, trailers, workshops, communal spaces, storage areas, generators, repair stations, cooking fires, market stalls, and improvised infrastructure spread across a large semi-permanent enclave on Night City's southeastern edge. The Aldecaldos dominate the camp, but it is deliberately multicultural and open to Nomads from outside their nation. Pack colors matter less once somebody has been vouched for and passed the guards. Inside, visitors are treated with startling generosity by Night City standards: food, medical help, somewhere to sleep, and assistance getting back on the road are part of the culture rather than premium services itemized on an invoice. **The price is reputation. Money can get you through many doors. Here, somebody has to say you're worth opening one for.**

The camp functions as one of the most important transportation exchanges in the region. Nomads hire out as drivers, guides, couriers, guards, and freight haulers, moving people and goods across the Badlands or into supply networks stretching far beyond Night City. Traders arrive looking for things impossible to obtain reliably through corporate channels. Fixers come hunting transportation that won't appear on a logistics database. Families stop to repair vehicles before crossing dangerous country. The nearby **Tepui** overflow lot even accommodates transient Nomads living from kombis, providing water and electricity for short stays before moving them along again. This isn't just a camp. **It's an airport without airplanes, a truck stop without corporate ownership, and an embassy for people whose country has wheels.**

But the camp's political influence is no longer unquestioned. Theresa Valentino's victory demonstrated that many permanent Santo Domingo residents have grown uncomfortable with a political order dominated by people who can pack up and leave. Every disagreement now carries additional weight. A missing shipment might be ordinary theft or an attempt to undermine the Aldecaldos. A Peacekeeper arrest could become a political incident. An El Norte representative asking for transport access might be negotiating business or testing how far Nomad authority has weakened. For edgerunners, the camp is one of Night City's best places to acquire transportation, information, equipment, or experienced help. Just remember: **once an Aldecaldo calls you family, disappointing them becomes much more dangerous than disappointing a customer.**`,
  },

  v2: {
    image: "city-police-precinct-2",
    text: `Precinct #2 is large enough to suggest somebody once expected it to control Santo Domingo. **The staffing roster suggests otherwise.** More than half of its available officers are tied up dealing with gangs and scavvers, leaving an enormous district to be policed by exhausted people who cannot physically be everywhere they are theoretically responsible for. The solution has been automation. Zhirafa drones increasingly handle patrol work, watching roads, scanning streets, responding to reports, and extending police presence into neighborhoods where there aren't enough human officers to maintain it.

That creates a peculiar hierarchy of authority because the NCPD isn't actually Santo Domingo's primary security provider. The **Aldecaldo Peacekeepers** hold that contract. Precinct #2 therefore operates in a district where another armed organization maintains community legitimacy, local expertise, and considerable practical power. A cop responding to trouble may discover Peacekeepers already there. A patrol drone may record Nomads resolving something the NCPD never heard about. Both sides can cooperate. Both sides can resent each other. Recent tensions have already included arrests involving Aldecaldo-affiliated Nomads, making every enforcement action potentially political.

For runners, Precinct #2 is a perfect example of Night City's fragmented authority. Get wanted by the NCPD and you may still have friends among the Peacekeepers. Anger the Aldecaldos and the cops aren't necessarily coming to save you. Commit something dramatic enough and both organizations may suddenly discover excellent interdepartmental cooperation. And somewhere above the streets, a cheap patrol drone is quietly collecting footage that could prove what actually happened. **Santo Domingo's cops may be overworked, but their cameras never need sleep.**`,
  },

  v3: {
    image: "east-cargo-village",
    text: `East Cargo Village is **dust, steel, and deliberate modesty**. Near Santo Domingo's outer edge sits a strip of cargo containers converted into basic housing, surrounded by the dry margins where city becomes Badlands almost without announcing the transition. This is not the colorful rooftop improvisation of the Old Ironworks or Zhirafa's curated industrial aesthetic. The containers here are practical shelters belonging largely to Nomads and reclaimers who understand that furniture becomes considerably less important when your neighborhood is expected to survive wind, dust, theft, mechanical failure, and the occasional vehicle arriving at extremely irresponsible speed.

The most notable residents are the **Sightseers**, a small Aldecaldo pack founded by Racer Rajavi and Endo. They specialize in transporting small goods and escorting people through the Badlands. They aren't rich and don't particularly want to be. Rather than consume resources at the larger Aldecaldo Camp, the Sightseers chose East Cargo Village and built themselves a self-sufficient little base equipped with what they actually need: containers, motorbikes, a kombi, gear, and enough competence to make everything else negotiable. Their recent trouble with the NCPD, including arrests of pack members, has contributed to growing tension between the police and the Aldecaldos.

For edgerunners, East Cargo Village has the appeal of a place where seemingly small jobs can open very large maps. Need somebody escorted across the Badlands? Need a package moved without corporate logistics? Need to find a missing Nomad who never arrived? Start here. On a quiet evening, the Village is nothing more than containers, engines cooling in the dust, people cooking outside, and Nomads arguing affectionately over vehicle maintenance. **Then someone asks whether you're comfortable crossing fifty kilometers of open country after dark, and suddenly the whole world gets bigger.**`,
  },

  v4: {
    image: "heywood-suites",
    text: `Whoever named **Heywood Suites** either possessed a fine sense of irony or worked in property marketing. The apartment complex sits directly beneath one of Night City's busiest highway overpasses, where heavy trucks thunder toward the Heywood Industrial Zone every morning and return every evening. The building is extensively soundproofed. It doesn't matter. Noise can be muffled; **physics remains unionized**. Vibrations travel through the structure strongly enough to rattle furniture unless residents bolt it down. Cups migrate across tables. Pictures slowly straighten themselves into new positions. Sleep becomes an engineering problem.

The residents have adapted with the peculiar technological pragmatism characteristic of Night City. Many have installed **Level Dampener cyberware**, converting an urban-planning failure into a medical purchasing decision. Others simply live in ear protection. Some residents, including workers from nearby Zhirafa facilities and Precinct #2, have begun learning **American Sign Language** because communicating visually can be easier than trying to overpower the freight traffic. The result is an apartment building developing its own accidental culture around silence in one of the loudest places in Night City.

There are excellent runner stories hidden inside that noise. Nobody hears the argument next door. Nobody notices a gunshot beneath a passing convoy. A meeting can happen during rush hour without needing sophisticated audio countermeasures. Somebody with Level Dampeners doesn't hear the fire alarm. A truck above loses control and turns six apartments into a structural emergency. **Most Night City housing comes with compromises. Heywood Suites comes with tinnitus unless you upgrade.**`,
  },

  v5: {
    image: "marias",
    text: `María's is barely inside Night City, which may be why **Night City hasn't managed to ruin it yet**. The family-run beer tent sits along the Great Nomad Road near the southern limits, spread across a broad parking area among auto shops, chop shops, and vehicle Techs. Plastic and lawn furniture surrounds the bar beneath open air. Most of it is loosely chained together because experience has established that chairs develop legs quickly around travelers. Staff discourage bolt cutters with the sort of threats that do not require translation twice. This is not fine dining. It is better: the kind of place people genuinely miss when they've been away too long.

The bar is named for **María "Viejita" Cruz**, its original owner, who died in 2040. With no children of her own and her husband long dead, María's extended family kept the place running. That continuity matters. Nomads stop here because their parents stopped here. Caravans drink before heading into the Badlands. Travelers returning from long runs arrive dusty and exhausted enough that somebody behind the bar already knows what they're ordering. Thanks to Nomad supply connections, María's is one of the rare non-Executive establishments where customers can obtain **real beer and real tequila**, trucked into Night City rather than synthesized somewhere behind a franchise logo.

For runners, María's is exactly the sort of place where jobs begin almost accidentally. A driver fails to return. A caravan leader needs one more gun. Somebody recognizes your employer's description before you've even asked around. Lupita Garza is tending bar between freelance gigs and knows something she shouldn't. Two packs who dislike each other have chosen adjacent tables because apparently the universe enjoys preparation. **You don't go to María's looking for Night City intrigue. You go for a beer. The intrigue has already ordered a second round.**`,
  },

  v6: {
    image: "metalstorm",
    text: `**MetalStorm appears to have been built on the assumption that eventually somebody would throw a motorcycle through the wall.** Located beneath the Pacifica Bridge, the bar is constructed from heavy materials sturdy enough that decades of abuse have produced character rather than structural collapse. Metal doors guard the entrance. Furnishings are built to survive patrons for whom ordinary chairs can become accidental splinters. Music pounds through the space while chrome-heavy bodies collide, drink, shout, and generally demonstrate why building codes should account for customers capable of bench-pressing compact cars.

The club has become the **spiritual and cultural center of Night City's Full Body Conversion community**. FBCs spend much of ordinary life consciously moderating strength around people and objects built for flesh. At MetalStorm, they can stop. The furniture can take it. The walls can take it. Most importantly, the other patrons can take it. Exotics and heavy chromers are common as well, but the FBC crowd gives the place its identity. For someone accustomed to living inside a machine powerful enough to accidentally injure somebody during a handshake, being able to slam into another body on the dance floor without apologizing afterward can feel surprisingly close to freedom.

That does not make MetalStorm particularly welcoming to unaugmented visitors. Getting through the heavy doors is only the first hint. Inside, a playful shove might break ribs. A mosh pit can resemble close-quarters combat. Starting a fight with an FBC here is less bravery than a strongly worded request for reconstructive surgery. Yet that makes MetalStorm an invaluable contact point for anyone seeking borg specialists, extreme-body Techs, rare maintenance knowledge, or people whose definition of "heavy muscle" is literal. **Every bar says you should know your limits. MetalStorm would merely like to know whether your limits are load-bearing.**`,
  },

  v7: {
    image: "woodchippers-garage",
    text: `**Nobody brings a car to Woodchipper's Garage for repairs.** Despite the vehicle bays, lifts, and tool benches, fixing engines is almost incidental to what happens inside. The garage is the home, office, warehouse, negotiation chamber, and informal court of **Woodchipper**, one of Night City's most influential Nomad Fixers. The woman herself is difficult to overlook: more than two meters tall thanks in part to an internal linear frame, heavily protected, famously loyal, and possessed of the sort of laugh that probably arrives in a room several seconds before she does. Woodchipper has spent decades building relationships across Nomad networks, weapons dealers, Fixers, and mercenary circles. Her garage is where much of that social machinery physically accumulates in crates.

Weapons and goods brought into Night City by Nomad contacts are stored throughout the building before being distributed through Woodchipper's network. She also uses the garage to **mediate disputes**. People with problems can sit down and talk under one uncompromising condition: no weapons and no violence inside her home. This is impressive considering that many of the people involved have spent their lives solving problems with both. Woodchipper's authority isn't based merely on being physically imposing. It comes from decades of favors, loyalty, supply access, judgment, and the knowledge that being cut out of her network can hurt considerably more than being hit.

Then, every month or so, the nearby cul-de-sac transforms. Tables emerge. Stalls line the curb. Music starts. Real street corn and Nomad food perfume the air. The neighborhood becomes one of Woodchipper's famous **Night Markets and block parties**, where invited traders sell weapons, cyberware, vehicles, equipment, and treasures hauled in from places most Night Citizens will never see. Access is based on reputation, invitation, or sponsorship. The market feels like a neighborhood festival until you notice the table beside the food stall is selling something normally transported in an armored convoy. For an edgerunner, Woodchipper's block may be one of the best places in Night City to find the impossible. **Just don't confuse a friendly party with neutral ground. You're standing in Woodchipper's neighborhood, eating Woodchipper's food, buying from Woodchipper's people. Behave accordingly.**`,
  },

  pacifica_playground: {
    image: "pacifica-playground",
    text: `Pacifica was supposed to be where Night City went to relax. Before the Fourth Corporate War, the coastal suburb offered expensive condos, ocean views, galleries, entertainment, and the carefully cultivated fantasy that the violence and desperation of central Night City could be kept somewhere beyond the horizon. Then the city detonated. Refugees flooded south. Condos became shelters. Tent cities filled open ground. Development collapsed, and the old resort community spent years becoming something poorer, denser, and considerably more honest. Through all of it, **Playland by the Sea kept blinking**. Rides rusted, fortunes changed, neighborhoods filled with displaced people, but the amusement park survived long enough to become the seed around which Pacifica began rebuilding.

Playland reopened in **2036**, and corporations began treating the surrounding district as an investment again. Tourism brought restaurants, housing, construction, security contracts, entertainment venues, gangs, hustlers, and people willing to sell tourists things tourists probably shouldn't purchase. Most residents now owe their livelihoods directly or indirectly to Playland, the Tanson Group, the Jodes, or the web of casinos, clubs, brothels, food joints, hotels, and services feeding the tourist economy. Playland management has enough political gravity that it **appointed Elliot Kane as City Manager**, while Militech holds the district security contract. Kane spends a great deal of time shaking hands, flattering sponsors, and ensuring nobody important notices how precariously the whole machine is wired together.

The result is perhaps Night City's strangest vacation destination. Families ride roller coasters while Piranhas party nearby. Corporate mascots beam down from advertisements while homeless kids sleep within walking distance of the gates. Visitors buy souvenir photos, synthetic funnel cake, braindance adventures, and overpriced drinks while **yogangs perform enough unpaid labor around the park to blur the line between neighborhood youth culture and an extraordinarily inventive internship program**. Playland doesn't merely tolerate these kids. It needs them. They know the maintenance passages, scavenging routes, unofficial shortcuts, blind spots, and social geography better than most managers ever will. The park may belong to corporations on paper. In practice, a great deal of it belongs to whoever knows where the service doors lead.

And Pacifica's gangs have learned the same lesson. The **Piranhas** hold enormous influence around Playland, throwing parties, providing unofficial security, and inserting themselves wherever crowds, entertainment, drugs, money, and attractive strangers intersect. Their rivalry with the **Voodoo Boys** has become enough of a problem that local businesses complain about collateral damage even with Militech supposedly maintaining order. Around them orbit other gangs, youth crews, tourists, construction workers, performers, refugees, corporate staff, and opportunists who understand that a destination attracting thousands of people with disposable income also attracts thousands of reasons to steal something. **Pacifica Playground sells escape from Night City while remaining one of the most Night City places imaginable.**

For an edgerunner, Pacifica is therefore a playground in the older, more dangerous meaning of the word. A corporate mascot can conceal surveillance architecture. A kid running a ride may know more about a missing person than Militech. A cheap cube hotel might sit twenty meters from somebody spending more on dinner than its tenants pay in a month. Haunted apartments, secret lovers, gang parties, experimental tech, anonymous restaurants, pirate artists, and straight-edge punks all share the same salt air. **Pacifica promises everyone a few hours away from reality. The smart edgerunner remembers that reality is still waiting outside the gift shop.**`,
  },

  w1: {
    image: "bitsnbolts",
    text: `Bits'n'Bolts is what happens when a junk pile acquires technical expertise. The tiny Pacifica workshop specializes in **salvage and fast repairs for people who cannot afford elegant solutions**, particularly construction workers needing equipment or cyberware patched together before the next shift. The exterior is concrete, graffiti, stickers, and a brutally heavy steel door that appears to have begun life as part of something military. Ring the call box and a camera turns toward you before anyone decides whether opening that door is a good idea. Inside, shelves bow beneath boxes of wire, components, tools, broken electronics, reclaimed cyberware, mysterious assemblies, and objects whose original manufacturers would probably be horrified to learn they remain functional. **Bits'n'Bolts doesn't throw anything away until physics files the paperwork.**

The shop's best-known Tech is **Patchz**, whose repair work occasionally intersects with legendary weaponsmith and inventor **Faisal Farah** of Faisal's Customs. That connection matters. Faisal specializes in precisely the sort of custom hardware that makes ordinary gunsmiths develop professional insecurity, and Patchz has done contract work for him. Bits'n'Bolts therefore occupies a useful niche between repair shop, salvage dealer, informal fabrication space, and doorway into far more interesting hardware than its cluttered storefront suggests. The public area may contain construction gear and replacement wiring. The back rooms contain broken weapons, cyberware, salvage, and opportunities.

For edgerunners, BnB is the kind of place where a job can begin with the sentence, "I found something weird inside this." A salvaged device refuses to identify itself. A weapon somebody wants repaired turns out to be a prototype. A construction crew brings in machinery containing hidden corporate surveillance gear. Patchz needs a component only available inside a secured facility. Or Faisal has designed something brilliant and requires the one person foolish enough to retrieve the material needed to build it. **Never underestimate a hole-in-the-wall Tech shop. Night City's most dangerous machines usually begin life on a workbench somebody forgot to clean.**`,
  },

  w2: {
    image: "cubeland-by-the-sea",
    text: `The phrase **Cubeland by the Sea** conjures coastal breezes, relaxation, perhaps a tasteful little balcony. None of those things survived contact with the business model. Cubeland was originally built as **temporary accommodation for construction workers**, which means its designers expected exhausted people to sleep there briefly and possess extremely modest opinions about architecture. Decades later, the supposedly temporary cube hotel is still standing, its tiny windowless rooms offering fold-out furniture and just enough personal space to reconsider every financial decision that led to the lease. It remains close enough to Playland by the Sea that residents qualify for discounted park admission on certain weekdays, possibly the most cheerful amenity ever attached to deeply depressing housing.

That proximity gives Cubeland a bizarre atmosphere. Fireworks explode above Playland while residents heat cheap food in communal spaces. Screams from amusement rides drift through the neighborhood while tenants sleep in rooms too small to turn around dramatically. Park workers live here because they can walk to shifts. Tourists who badly underestimated Night City accommodation prices occasionally end up here. Young employees promise themselves they'll move somewhere better after promotion. Old employees stopped making that promise years ago. **From Cubeland, you can practically hear other people having the vacation you can't afford.**

For edgerunners, anonymity is the hotel's real attraction. Cube hotels concentrate people without requiring anybody to become particularly invested in their neighbors. A seasonal ride worker, runaway yoganger, corporate technician, wanted courier, or heavily armed stranger can rent a room and disappear into the daily churn. A crew using Cubeland as a temporary base enjoys Playland practically next door, provided they accept the possibility that one of their neighbors is also using Cubeland as a temporary base for reasons considerably less wholesome.`,
  },

  w3: {
    image: "mister-rice-guy",
    text: `Mister Rice Guy is what happens when someone takes an upscale sushi restaurant, removes almost every identifiable employee, fills the interior with **automated conveyor systems and neon machinery**, and then refuses to tell anyone who actually owns it. The restaurant operates twenty-four hours a day and serves everything from cheap South Asian-flavored kibble to genuinely expensive gourmet dishes made with real fish. Its famous black rice roll sits near the top of a menu where colored plates correspond to wildly different price tiers, meaning a table can contain someone eating ten-eurobuck kibble beside somebody consuming seafood worth more than their neighbor's monthly rent. **Class warfare has rarely looked so attractive on a conveyor belt.**

Then **Hime Cat** appears. Connect your Agent to Mister Rice Guy and the restaurant's adorable virtual mascot offers a Lucky Treat, dispensing fortunes, vouchers, random corporate predictions, and occasionally surprisingly consequential little twists of fate. Hime Cat is cute enough to have become famous across Pacifica, which conveniently distracts diners from wondering why an automated restaurant needs their Agents connected in the first place. Customers can also rent private tatami spaces in a Zen garden, while the restaurant automatically summons law enforcement if patrons become violent. Attempts to identify the actual ownership disappear through a maze of old acquisitions and shell companies. Nobody seems to know who truly runs the place. **The sushi is excellent. The ownership structure is terrifying.**

That anonymity makes Mister Rice Guy ideal for runners. Powerful people dine here because the private rooms are comfortable and the food impresses clients. Investigators come because ownership refuses to resolve into a human being. An Agent might receive a Hime Cat fortune that sounds disturbingly specific. A meal ordered from the highest price tier might contain something that was never on the menu. And if somebody tells you they know who owns Mister Rice Guy, the first question should not be *who?* It should be **how long have they known?**`,
  },

  w4: {
    image: "playhouse",
    text: `Playhouse would be an excellent apartment building if it could stop reminding tenants about **the television show where people died there**. The complex once served as the purpose-built setting for a troubled reality program also called *Playhouse*. Cameras were hidden throughout the building to record the inhabitants, because apparently the old world had not yet discovered sufficient ways to turn private humiliation into entertainment. The production ended badly enough that one elevator became permanently associated with the show's murderous finale. The current landlord assures prospective tenants that all hidden cameras have been removed and the **murder elevator has been replaced**. Nothing improves confidence in a residence like needing to specify that second part.

The trouble is that Playhouse hasn't become normal. Residents report hearing screams with no obvious source. Some smell blood while riding the elevator alone. Radios whisper when nobody is transmitting. Cold spots appear in otherwise functioning apartments. Whether any of this is supernatural remains wonderfully unresolved. The building could be haunted. It could contain forgotten production technology. Somebody could still be operating concealed systems. Residents might be collectively feeding one another's paranoia. This is Night City, where **"ghost" and "malfunctioning surveillance AI" belong on the same diagnostic flowchart**. At least the address is excellent, and tenants receive discounted admission to nearby Playland.

For edgerunners, Playhouse practically writes the screamsheet itself. Find the camera that supposedly doesn't exist. Spend one night in the murder elevator. Locate a former contestant who insists something was buried beneath the set. Explain why the building's electrical usage spikes whenever somebody dies. Or discover that the haunting is fake and whoever is faking it desperately needs people to keep believing. **A haunted house is frightening. A haunted house built for reality television is insulting on top of it.**`,
  },

  w5: {
    image: "playland-by-the-sea",
    text: `Playland by the Sea is **Night City's premiere tourist attraction**, a title involving considerably more armor than the same distinction would require elsewhere. The amusement park survived Pacifica's collapse and reopened in 2036 with heavy corporate sponsorship, filling the waterfront with neon rides, braindance adventures, themed zones, corporate food courts, souvenir stands, fireworks, giant mascots, and enough advertising to make childhood nostalgia tax-deductible. Thrill Hill offers dangerous rides and laser attractions. Lovers Lane promises romance. Haunted Woods packages fear for family consumption. Fantasy Island turns corporate science into spectacle. The whole place is a machine designed to extract money in exchange for wonder, and the remarkable thing is that **it often succeeds at the wonder part**.

Behind the bright façades is a much stranger labor ecosystem. **Yogangs are everywhere**. Beaverdams, Gearheads, Glitters, GoFasters, Packrats, Taggers, Thrashers, and other youth gangs gravitate toward the park, and Playland management has developed an alarming talent for converting their enthusiasm into free labor. Kids repair things, fetch things, perform things, move equipment, know the maintenance corridors, and generally keep portions of the park functioning because being part of Playland gives them status, shelter, purpose, entertainment, or simply somewhere to belong. Corporate managers call this community engagement. A labor lawyer might use different nouns.

Above them sit the **Piranhas**, whose party-gang culture fits Playland almost too well. Members hang around the park, throw themselves into its nightlife, and can provide security when appropriately compensated. At attractions such as Biotechnica's Aquarium Fantastique, Piranhas have even taken direct operational roles, policing behavior inside while rumors circulate about initiation rituals involving the actual piranha tanks. Militech remains the official district security provider, which means Playland exists inside an overlapping hierarchy of corporate guards, gang authority, yogang territorial knowledge, and park management. For edgerunners, it is paradise: crowds to disappear into, tunnels to infiltrate, corporate sponsors to rob, mascots to impersonate, rides to sabotage, teenagers who know routes no blueprint shows, and one iron rule worth remembering: **if the Piranhas are suddenly leaving the party, leave before asking why.**`,
  },

  w6: {
    image: "pleasant-valley-apartments",
    text: `Pleasant Valley was built for people who looked at Night City's endless screens, Agents, implants, smart appliances, surveillance systems, NET Architectures, and algorithmic intrusion and said, **absolutely not**. The eight-story apartment building is deliberately designed for neo-luddites and victims of technoshock overload. It looks older than it is, with brownstone and Art Deco styling, traditional Chinese decorative influences, analog locks, push-button elevators, manual climate and water controls, no NET Architecture, and even an old-fashioned generator. The lobby contains couches, bamboo, koi, philosophical quotations criticizing technological dependence, and a juice bar. On the top floor sits an aviary. Entering Pleasant Valley after spending all day in Night City can feel less like entering another building than stepping out of the century.

Ironically, the intended neo-luddite community never really materialized. What Pleasant Valley attracted instead were **Executives seeking discretion**. Wealthy clients rent apartments temporarily for secret meetings, affairs, hiding out, or any other activity improved by the absence of networked appliances recording telemetry. Residents can arrange private guards and self-defense training, and meals from nearby Mister Rice Guy can be delivered for an additional fee. The building designed to escape technology therefore became attractive to exactly the class of people whose corporations helped saturate Night City with it. **Apparently privacy becomes much more compelling once you've personally approved a surveillance budget.**

There is one additional complication: **Inquisitors live here**. A violently anti-cyberware gang finding ideological comfort inside Pleasant Valley makes perfect sense right up until one remembers that many temporary residents are corporate Executives whose bodies may contain expensive chrome. The resulting tension can become explosive. An edgerunner might be hired to protect a cybered-up Exec hiding among zealots, identify who keeps vandalizing an implanted tenant's door, or conduct a meeting whose entire security plan rests on the assumption that nothing in the room can connect to the NET. Pleasant Valley offers sanctuary from technology. It never promised sanctuary from people.`,
  },

  w7: {
    image: "scenic-cubes",
    text: `Scenic Cubes possesses one of Night City's great pieces of real-estate comedy: it sits on **beautiful Pacific waterfront and has no windows**. The cube hotel consists of the familiar tiny enclosed rooms, but residents who want to see the scenery can climb to the communal rooftop, where lawn chairs, hammocks, drinks, and conversation have transformed an architectural deficiency into neighborhood culture. The ocean spreads out beyond the roof. Night City's skyline glows in the distance. Below, everyone returns to sleeping inside boxes. **The view is free. Access requires stairs.**

What Scenic Cubes lacks in windows, it makes up for in walls. The building is covered with **some of the most expressive graffiti in Night City**, much of it created by exceptionally talented residents. Each floor has become a gallery of murals, tags, characters, political statements, memorial pieces, obscene jokes, gang imagery, surreal landscapes, and personal histories layered over one another until the cube hotel feels less like cheap accommodation and more like an evolving art installation people happen to sleep inside. Many residents are rowdy boostergangers, though not generally members of Night City's nastiest crews, giving the building enough edge to keep casual tourists from treating it like a museum.

For edgerunners, the graffiti alone can create jobs. A mural contains coded information. Somebody paints over a memorial and nearly starts a war. A famous anonymous artist lives here and a corporation wants them found. A Tagger has seen something incriminating and hidden the evidence in plain sight across six floors of artwork. Scenic Cubes understands something Night City's corporations routinely forget: **people denied space will still find a way to leave a mark.**`,
  },

  w8: {
    image: "the-xx",
    text: `The XX is a punk dive bar where the floor sticks, the amps hurt, the crowd gets physical, and **the bartender would like to offer you a smoothie**. Pronounced *The Twenty*, the club is owned by **Breakfist**, a straight-edge punk band whose members reject drugs and alcohol. Consequently, the XX serves neither. Instead, the bar pours juice, shakes, and blended concoctions while live rock detonates from the stage every night. Other bands are welcome to perform when Breakfist isn't playing, provided they respect the establishment's one beautifully uncomplicated booking policy: fascists are not welcome.

The unexpectedly excellent drinks are largely the work of bassist **Ten Ton**, who previously worked at Angelo's and uses old restaurant contacts to acquire bruised or cosmetically imperfect fruits and vegetables before they're discarded. The produce may not look luxurious, but after the blender nobody cares. The house specialty, the Lean Mean Machine, combines frozen banana, soymilk, chocolate syrup, and peanut-butter-flavored kibble into something much better than those ingredients have any contractual obligation to become. The result is perhaps Pacifica's strangest nightlife proposition: get punched in the pit, scream yourself hoarse at a punk show, then restore your electrolytes. **Rebellion, now with fiber.**

The lack of booze changes the social chemistry. Nobody can explain tomorrow's mistake by claiming they were drunk. Deals happen sober. Fights happen sober. Music matters because people actually came for it. Breakfist's politics attract punks, activists, young musicians, anti-corporate idealists, and people who simply prefer their nightlife without chemically sponsored amnesia. For runners, the XX is excellent territory for finding Rockerboys, organizers, information, or someone willing to help because your target richly deserves it. **Plenty of Night City bars help you forget what you believe. The XX expects you to remember.**`,
  },

  rancho_coronado: {
    image: "rancho-coronado",
    text: `Rancho Coronado is technically part of Night City in roughly the same way an abandoned child remains technically part of a family. **The paperwork says yes. Everything else says good luck.** Before the Fourth Corporate War, the district was classic beaverville: subdivision after subdivision of modest three-bedroom tract homes, little shopping plazas, commuter streets, and corporate employees raising families far enough from central Night City to imagine themselves insulated from it. Arasaka analysts lived beside Petrochem supervisors. Militech techs cut their lawns. Minivans filled driveways. Private neighborhood security was famously aggressive, and the endless rows of nearly identical houses represented a particular late-twentieth-century dream of safety through mortgages, commuting, and conformity. Then the city broke, and Rancho Coronado discovered that suburbia is only stable while somebody keeps supplying water.

Refugees flooded south after the War. Tent cities filled parks, vacant land, shopping-center parking lots, and the spaces between old subdivisions. Mini-malls collapsed as commercial supply chains dried up, then returned to life as workshops, communes, gardens, markets, and industrial operations. Houses built for four people accommodated twelve. Former football fields filled with shipping containers. Shopping malls became farmland. And unlike districts closer to the rebuilding core, Rancho Coronado never received the great wave of reconstruction money that might have replaced the temporary with something permanent. **The emergency simply lasted long enough to become architecture.**

The political explanation is almost insulting in its simplicity. Every other Night City district eventually acquired a City Manager or some equivalent authority. Rancho Coronado did not. Nobody has been willing to pay the price required to acquire its seat on the City Council, leaving the district without meaningful representation and with painfully inadequate municipal resources. **There is no City Manager. The NCPD is the official security provider only in theory.** Fire response is unreliable. Utilities are fragile. Clean water can become a neighborhood-level strategic resource. Infrastructure failures elsewhere are inconveniences. Here they can reshape who controls a block.

Naturally, other institutions have moved into the empty space. **6th Street, the Albino Alligators, the Dirty Hippies, the Steel Vaqueros, and the Voodoo Boys** all operate within Rancho Coronado. Some are predators. Some are neighbors. Often they are both. The Albino Alligators occupy a defunct carwash that also happens to provide precious clean water. The Steel Vaqueros maintain enough presence around Eagle Rock Stadium to make the container community safer than much of the surrounding district because their extended families live there. Reclaimers grow vegetables where retail chains once sold consumer goods. Fixers coordinate markets because somebody has to move tools, clothes, weapons, medicine, electronics, and luxuries through a district municipal government has mostly abandoned. **Rancho Coronado hasn't become lawless. It has accumulated competing forms of law.**

For an edgerunner, this means Rancho Coronado rewards relationships far more than credentials. Flash an NCPD badge and someone may laugh. Tell them Cheech sent you and suddenly a gate opens. Mention the right Steel Vaquero cousin and you have somewhere safe to sleep. Arrive at Minimallism with an invitation and you can buy things unavailable through legitimate retail channels. Need water? A gang controls one of the district's best sources. Need food? Find the Reclaimers. Need protection? Ask who actually owns the street before assuming the answer appears on a municipal map. **Night City forgot to finish governing Rancho Coronado. The residents finished the job themselves, and they have no particular reason to hand it back.**`,
  },

  x1: {
    image: "albino-alligator-carwash",
    text: `The Albino Alligator Carwash hasn't washed a customer's car in years, yet it may provide **one of Rancho Coronado's most important public utilities**. The dead business became headquarters for the **Albino Alligators**, a posergang whose name came from promotional shirts left behind when the original carwash failed: black polos emblazoned with a cartoon white alligator carrying an assault rifle. The shirts were plentiful enough that an entire gang culture grew around them. Collars stay popped. The logo became tattoos. What began as young punks wearing abandoned advertising evolved into a faction with enough local influence that people in Rancho Coronado have learned to take the ridiculous reptile seriously.

The reason is water. **The old carwash sits on one of the district's most dependable supplies of clean drinking water**, which transforms a decaying piece of commercial infrastructure into strategic territory. Rancho Coronado suffers from unreliable utilities, so people come here carrying bottles, drums, jugs, patched containers, and whatever else will hold something safe enough to drink. The Albino Alligators therefore occupy an awkward social position. They are still a gang. Members party, get high, carry weapons, and can become extremely dangerous. But they also control access to something everyone needs, giving them community leverage no amount of graffiti or bravado could manufacture on its own.

For an edgerunner, the place demonstrates how quickly small problems become political in Rancho Coronado. A broken pump threatens an entire neighborhood. Somebody poisons a tank and blames the Alligators. A corporate developer discovers the water source sits beneath land it wants to acquire. One gang lieutenant wants to monetize access while another knows doing so could turn the whole district against them. **In richer parts of Night City, gangs fight over drugs and territory. In Rancho Coronado, sometimes they fight over the tap.**`,
  },

  x2: {
    image: "coronado-heights",
    text: `Coronado Heights sits on the hills where Rancho Coronado begins leaning into Pacifica, close enough to the border that residents can look toward **Playland by the Sea** and reasonably argue they're practically living in another district. The apartment complex enjoys a genuinely good view, which is enough to make it one of those rare Rancho Coronado properties where the word *Heights* isn't entirely fraudulent. It is a decent place to live by local standards, positioned near enough to Pacifica's tourism economy to enjoy some of its advantages without actually escaping Rancho Coronado's civic neglect.

The real problem is the neighbors. Or rather, **which gang your neighbor belongs to**. Voodoo Boys maintain apartments here and tend to keep to themselves. Steel Vaqueros use the complex while conducting business with Nomads. 6th Street members periodically "patrol" the surrounding neighborhood, quotation marks doing considerable work in that sentence. No one faction fully dominates the building, which creates an uneasy residential détente. Elevator rides can become territorial negotiations. Somebody's cousin visiting from the wrong gang may be enough to change the emotional temperature of an entire floor. Yet despite all that, people genuinely like living here. The apartments are respectable, and the Pacifica views really are excellent.

That makes Coronado Heights fantastic neutral-ground territory for an RPG. A runner can live beside gang members without belonging to any of them, provided they understand local etiquette. A Vaquero meeting takes place two floors beneath a Voodoo Boy safehouse. A 6th Street patrol begins asking questions about a new tenant. Somebody fires from a balcony and three gangs immediately demand to know whose bullet it was. **The rent buys a view of Playland's lights. The real amenity is learning exactly how many kinds of trouble can share one parking lot without starting a war.**`,
  },

  x3: {
    image: "eagle-rock-stadium",
    text: `Eagle Rock Stadium used to be where Rancho Coronado watched football. Now **people live on the field**. During the Time of the Red, displaced residents began moving cargo containers onto the former pitch, converting steel freight boxes into housing until the old stadium became a dense container community. The stands still wrap around what was once sporting ground, but instead of players below there are stacked homes, walkways, improvised wiring, rooftop water tanks, laundry lines, cooking spaces, and narrow lanes threading through the containers. From high in the old seating, the whole settlement looks like somebody poured a neighborhood into a stadium and waited for it to settle.

Eagle Rock occupies an interesting sweet spot. It lies deep enough inside Rancho Coronado that authorities rarely search it thoroughly but remains close enough to the rest of Night City to make travel practical. That makes it useful for ordinary residents and people who would rather not be found. Petty crime is constant. Leave something unattended and somebody may decide ownership has become negotiable. Vehicles get broken into. Gunfire from neighboring tent cities isn't especially unusual. Yet Eagle Rock is **safer than much of Rancho Coronado because the Steel Vaqueros keep a presence here**. Their extended families live among the containers, which gives the gang an unusually sincere reason to discourage serious violence inside.

For an edgerunner, Eagle Rock can be sanctuary, maze, or pressure cooker. A fugitive disappears into five stories of identical freight boxes. A crew needs to protect someone whose family is under Vaquero protection. A missing shipment turns out to have become someone's bedroom wall. An outsider commits a violent crime inside the community and discovers the Steel Vaqueros regard family housing as considerably more sacred than corporate property law. **Once, crowds came to Eagle Rock to watch people fight over a ball. These days the games are less organized and the spectators live in the stadium.**`,
  },

  x4: {
    image: "jack-n-the-green",
    text: `Jack 'N' the Green is one of Rancho Coronado's quiet miracles: **people planting food where the city planted abandonment**. The commune is run by Reclaimers under the leadership of **Cheech**, maintaining guerrilla gardens and helping reclaim pieces of the district one patch of soil at a time. Empty lots become vegetable beds. Ruined landscaping becomes usable earth. Broken structures provide shade, supports, planters, or material for irrigation systems. The work rarely looks spectacular. That's part of the point. Guerrilla gardening succeeds through thousands of small interventions that eventually become difficult to remove without admitting somebody had deliberately chosen to destroy food.

Calling the group gardeners undersells them. Reclaimers operate at the intersection of agriculture, community organization, salvage, infrastructure repair, and stubborn civic optimism. Growing crops in Rancho Coronado means understanding contaminated soil, uncertain water supplies, theft, weather, pests, gangs, corporate land claims, and the possibility that a lot left abandoned for fifteen years will suddenly become valuable precisely because the residents improved it. Jack 'N' the Green therefore grows more than vegetables. **It creates territory worth fighting over.**

For runners, the jobs almost write themselves. Somebody contaminates a garden. Reclaimers discover an old utility tunnel while digging irrigation. A developer produces documents claiming ownership of land nobody cared about until food started growing there. A rare seed shipment needs escort. A nearby gang demands a percentage of the harvest and discovers community gardeners can have surprisingly well-connected friends. **Night City is full of people trying to take territory with guns. Jack 'N' the Green does it with roots.**`,
  },

  x5: {
    image: "minimallism",
    text: `Before the Fourth Corporate War, **Minimallism was a shopping mall**, one of those sprawling suburban temples where Rancho Coronado's corporate families once spent weekends buying clothes, electronics, prepared food, toys, furniture, and the endless minor objects required to maintain a comfortable consumer identity. Then supply chains collapsed. Stores emptied. Businesses failed. Vast metal shutters came down over the entrances, and the mall sat sealed and abandoned while the neighborhood around it filled with refugees. For years it was the corpse of an economy that had promised shopping would remain available forever. Then squatters broke in. Reclaimers followed. **The mall began producing food instead of selling it.**

Guerrilla gardeners converted empty retail spaces into growing areas and began trading excess produce to Nomads. That attracted Fixers, who recognized something valuable happening inside the ruin. Deals emerged: fertilizer and spare parts in exchange for space. Soon the old mall became a patchwork of **Reclaimer territory and Night Markets**, dozens of operations overlapping until residents began calling the whole complex the **RC Night Market**. Among its most prominent figures is **Ms. Mynah**, an avian-bodysculpted Fixer who runs an especially famous market every fifth day of the month. She curates her vendors carefully and sends out a limited number of invitations, turning access to part of a ruined shopping center in neglected Rancho Coronado into one of Night City's more desirable retail experiences.

The irony is exquisite. Where corporate retailers once sold mass-produced goods beneath fluorescent lighting, modern vendors offer scavenged fashion, custom clothing, rare equipment, food, weapons, electronics, and whatever else Fixers managed to move through the fractured economy. Reclaimed fabric becomes high fashion. Shipping-container finds become boutique inventory. Wealthy clients arrive with invitation codes to shop beside gardens growing beneath dead storefront signs. The Reclaimers and Fixers coexist because each has something the other needs: food, space, logistics, material, security, customers. For an edgerunner, Minimallism can supply almost anything, but it is even more valuable as neutral social territory. Every stall has contacts. Every garden has a family behind it. Every Fixer knows another Fixer. **The old mall was built around the idea that consuming things creates community. Rancho Coronado let it die, planted vegetables in the corpse, and accidentally created the real thing.**`,
  },
};

/** The dossier for a district or location key, when one has been written. */
export function placeDossier(key: string): PlaceDossierEntry | undefined {
  return PLACE_DOSSIERS[key.trim().toLowerCase()];
}

/** Where the picture for a dossier lives, for an entry that has one. */
export function placeImage(entry: PlaceDossierEntry): string | undefined {
  return entry.image ? `/images/places/${entry.image}.png` : undefined;
}
